#[inline(always)]
fn mace_polar_trace_timings_enabled() -> bool {
    static TRACE_TIMINGS: OnceLock<bool> = OnceLock::new();
    *TRACE_TIMINGS.get_or_init(|| std::env::var_os("LLMLIP_MACE_POLAR_TRACE_TIMINGS").is_some())
}

#[inline(always)]
fn mace_polar_trace_stage(label: &str, start: Option<Instant>) {
    if let Some(start) = start {
        eprintln!(
            "mace_polar_trace {label} {:.6} ms",
            start.elapsed().as_secs_f64() * 1000.0
        );
    }
}

#[inline(always)]
fn mace_polar_parallel_small_batch_linears_enabled(node_count: usize) -> bool {
    #[cfg(feature = "parallel")]
    {
        node_count <= 512 && rayon::current_num_threads() > 1
    }
    #[cfg(not(feature = "parallel"))]
    {
        let _ = node_count;
        false
    }
}

#[allow(dead_code)]
fn mace_polar_f32_gate_row_parallel_benefits(
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    node_count: usize,
) -> bool {
    let has_second_layer = tensors_f32.contains_key("interactions.1.linear_res.weight");
    let has_third_layer = tensors_f32.contains_key("interactions.2.linear_res.weight");
    has_third_layer || (has_second_layer && node_count >= POLAR_MACE_F32_GATE_ROW_PAR_MIN_ROWS)
}

