pub struct MacePolarExternalTensor {
    pub shape: Vec<usize>,
    pub values: MacePolarExternalTensorValues,
}

#[derive(Clone, Debug)]
pub enum MacePolarExternalTensorValues {
    Bool(Vec<bool>),
    F64(Vec<f64>),
    I32(Vec<i32>),
    I64(Vec<i64>),
}

impl MacePolarExternalTensorValues {
    fn dtype_name(&self) -> &'static str {
        match self {
            Self::Bool(_) => "bool",
            Self::F64(_) => "f64",
            Self::I32(_) => "i32",
            Self::I64(_) => "i64",
        }
    }

    fn len(&self) -> usize {
        match self {
            Self::Bool(values) => values.len(),
            Self::F64(values) => values.len(),
            Self::I32(values) => values.len(),
            Self::I64(values) => values.len(),
        }
    }

    fn byte_size(&self) -> usize {
        match self {
            Self::Bool(values) => values.len(),
            Self::F64(values) => values.len() * 8,
            Self::I32(values) => values.len() * 4,
            Self::I64(values) => values.len() * 8,
        }
    }

    fn all_finite(&self) -> bool {
        match self {
            Self::F64(values) => values.iter().all(|value| value.is_finite()),
            Self::Bool(_) | Self::I32(_) | Self::I64(_) => true,
        }
    }
}

