#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MacePolarTensorDtype {
    Bool,
    F64,
    I32,
    I64,
}

impl MacePolarTensorDtype {
    fn name(self) -> &'static str {
        match self {
            Self::Bool => "bool",
            Self::F64 => "f64",
            Self::I32 => "i32",
            Self::I64 => "i64",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MacePolarTensorSpec {
    name: &'static str,
    dtype: MacePolarTensorDtype,
    shape: &'static [usize],
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MacePolarLocalBackboneForwardContract {
    selected_model: &'static str,
    num_interactions: usize,
    num_bessel: usize,
    edge_attr_dim: usize,
    node_attr_dim: usize,
    hidden_dim: usize,
    radial_mlp_input_dim: usize,
    radial_mlp_hidden_dim: usize,
    radial_mlp_output_dim: usize,
    symmetric_contraction_correlation: usize,
    sh_input_permutation: [usize; 3],
}

