    POLAR_MACE_LONG_RANGE_SOURCE_SCALAR_WEIGHT_LEN + LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;

fn polar_mace_long_range_source_map_has_vector_block(input_dim: usize) -> bool {
    input_dim >= POLAR_MACE_LONG_RANGE_SOURCE_VECTOR_INPUT_DIM
}

fn polar_mace_long_range_source_map_weight_len(input_dim: usize) -> usize {
    POLAR_MACE_LONG_RANGE_SOURCE_SCALAR_WEIGHT_LEN
        + if polar_mace_long_range_source_map_has_vector_block(input_dim) {
            POLAR_MACE_LONG_RANGE_SOURCE_VECTOR_WEIGHT_LEN
        } else {
            0
        }
}

