struct MacePolarTensorAccess<'a> {
    tensors: &'a BTreeMap<String, MacePolarExternalTensor>,
}

struct MacePolarTensorAccessF32<'a> {
    tensors: &'a BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
}

impl<'a> MacePolarTensorAccess<'a> {
    fn new(tensors: &'a BTreeMap<String, MacePolarExternalTensor>) -> Self {
        Self { tensors }
    }

    fn f64(&self, name: &str, shape: &[usize]) -> Result<&'a [f64], MacePolarError> {
        let tensor = self.tensor(name, shape, MacePolarTensorDtype::F64)?;
        match &tensor.values {
            MacePolarExternalTensorValues::F64(values) => Ok(values),
            _ => unreachable!("tensor dtype was checked before value extraction"),
        }
    }

    fn f64_dynamic(&self, name: &str) -> Result<(&'a [usize], &'a [f64]), MacePolarError> {
        let tensor = self
            .tensors
            .get(name)
            .ok_or_else(|| invalid("local_backbone", format!("missing tensor `{name}`")))?;
        match &tensor.values {
            MacePolarExternalTensorValues::F64(values) => Ok((tensor.shape.as_slice(), values)),
            _ => Err(invalid(
                "local_backbone",
                format!(
                    "tensor `{name}` expected dtype f64, got {}",
                    tensor.values.dtype_name()
                ),
            )),
        }
    }

    fn i32(&self, name: &str, shape: &[usize]) -> Result<&'a [i32], MacePolarError> {
        let tensor = self.tensor(name, shape, MacePolarTensorDtype::I32)?;
        match &tensor.values {
            MacePolarExternalTensorValues::I32(values) => Ok(values),
            _ => unreachable!("tensor dtype was checked before value extraction"),
        }
    }

    fn i64(&self, name: &str, shape: &[usize]) -> Result<&'a [i64], MacePolarError> {
        let tensor = self.tensor(name, shape, MacePolarTensorDtype::I64)?;
        match &tensor.values {
            MacePolarExternalTensorValues::I64(values) => Ok(values),
            _ => unreachable!("tensor dtype was checked before value extraction"),
        }
    }

    fn bool(&self, name: &str, shape: &[usize]) -> Result<&'a [bool], MacePolarError> {
        let tensor = self.tensor(name, shape, MacePolarTensorDtype::Bool)?;
        match &tensor.values {
            MacePolarExternalTensorValues::Bool(values) => Ok(values),
            _ => unreachable!("tensor dtype was checked before value extraction"),
        }
    }

    fn tensor(
        &self,
        name: &str,
        shape: &[usize],
        dtype: MacePolarTensorDtype,
    ) -> Result<&'a MacePolarExternalTensor, MacePolarError> {
        let tensor = self
            .tensors
            .get(name)
            .ok_or_else(|| invalid("local_backbone", format!("missing tensor `{name}`")))?;
        if tensor.shape != shape {
            return Err(invalid(
                "local_backbone",
                format!(
                    "tensor `{name}` expected shape {shape:?}, got {:?}",
                    tensor.shape
                ),
            ));
        }
        if tensor.values.dtype_name() != dtype.name() {
            return Err(invalid(
                "local_backbone",
                format!(
                    "tensor `{name}` expected dtype {}, got {}",
                    dtype.name(),
                    tensor.values.dtype_name()
                ),
            ));
        }
        Ok(tensor)
    }
}

impl<'a> MacePolarTensorAccessF32<'a> {
    fn new(tensors: &'a BTreeMap<String, MacePolarRuntimeFloatTensorF32>) -> Self {
        Self { tensors }
    }

    fn f32(&self, name: &str, shape: &[usize]) -> Result<&'a [f32], MacePolarError> {
        let tensor = self
            .tensors
            .get(name)
            .ok_or_else(|| invalid("local_backbone", format!("missing f32 tensor `{name}`")))?;
        if tensor.shape != shape {
            return Err(invalid(
                "local_backbone",
                format!(
                    "f32 tensor `{name}` shape {:?} != expected {:?}",
                    tensor.shape, shape
                ),
            ));
        }
        Ok(&tensor.values)
    }
}

fn validate_dynamic_f64_tensor_rank(
    access: &MacePolarTensorAccess<'_>,
    name: &str,
    rank: usize,
) -> Result<Vec<usize>, MacePolarError> {
    let (shape, values) = access.f64_dynamic(name)?;
    require_usize(&format!("{name}.rank"), shape.len(), rank)?;
    let expected_numel = shape.iter().product();
    require_usize(&format!("{name}.numel"), values.len(), expected_numel)?;
    Ok(shape.to_vec())
}

fn validate_model_specific_local_backbone_forward_contract(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    spec: &MacePolarModelSpec,
) -> Result<(), MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let contract = LOCAL_BACKBONE_FORWARD_CONTRACT;
    let _ = access.f64(
        "atomic_energies_fn.atomic_energies",
        &[contract.node_attr_dim],
    )?;
    let _ = access.f64(
        "node_embedding.linear.weight",
        &[contract.node_attr_dim * contract.hidden_dim],
    )?;
    let _ = access.f64("node_embedding.linear.output_mask", &[contract.hidden_dim])?;
    let _ = access.f64(
        "radial_embedding.bessel_fn.bessel_weights",
        &[contract.num_bessel],
    )?;
    let _ = access.f64("radial_embedding.bessel_fn.r_max", &[])?;
    let _ = access.f64("radial_embedding.bessel_fn.prefactor", &[])?;
    let _ = access.i32("radial_embedding.cutoff_fn.p", &[])?;

    for layer in 0..spec.num_interactions {
        let linear_up_weight = validate_dynamic_f64_tensor_rank(
            &access,
            &format!("interactions.{layer}.linear_up.weight"),
            1,
        )?;
        if linear_up_weight[0] == 0 {
            return Err(invalid(
                "local_backbone.interactions.linear_up.weight",
                format!("layer {layer} has empty linear_up weight"),
            ));
        }
        let conv_output_mask = validate_dynamic_f64_tensor_rank(
            &access,
            &format!("interactions.{layer}.conv_tp.output_mask"),
            1,
        )?;
        if conv_output_mask[0] == 0 {
            return Err(invalid(
                "local_backbone.interactions.conv_tp.output_mask",
                format!("layer {layer} has empty conv_tp output mask"),
            ));
        }
        let radial_in = validate_dynamic_f64_tensor_rank(
            &access,
            &format!("interactions.{layer}.conv_tp_weights.net.0.weight"),
            2,
        )?;
        require_usize(
            "local_backbone.conv_tp_weights.net.0.out",
            radial_in[0],
            contract.radial_mlp_hidden_dim,
        )?;
        require_usize(
            "local_backbone.conv_tp_weights.net.0.in",
            radial_in[1],
            contract.radial_mlp_input_dim,
        )?;
        let radial_out = validate_dynamic_f64_tensor_rank(
            &access,
            &format!("interactions.{layer}.conv_tp_weights.net.9.weight"),
            2,
        )?;
        require_usize(
            "local_backbone.conv_tp_weights.net.9.in",
            radial_out[1],
            contract.radial_mlp_hidden_dim,
        )?;

        let product_plan = MacePolarProductSymmetricVjpLayerPlan::from_access(&access, layer)?;
        let product_width = product_plan.output_dim;
        let product_linear = validate_dynamic_f64_tensor_rank(
            &access,
            &format!("products.{layer}.linear.weight"),
            1,
        )?;
        if product_linear[0] == 0 {
            return Err(invalid(
                "local_backbone.products.linear.weight",
                format!("layer {layer} has empty product linear weight"),
            ));
        }
        let _ = access
            .f64(&format!("products.{layer}.linear.bias"), &[0])
            .or_else(|_| access.f64(&format!("products.{layer}.linear.bias"), &[product_width]))?;
        let _ = access.f64(
            &format!("products.{layer}.linear.output_mask"),
            &[product_width],
        )?;

        let linear_readout = format!("readouts.{layer}.linear.weight");
        if tensors.contains_key(&linear_readout) {
            let readout_weight = validate_dynamic_f64_tensor_rank(&access, &linear_readout, 1)?;
            require_usize(
                "local_backbone.readouts.linear.weight",
                readout_weight[0],
                contract.hidden_dim,
            )?;
            let _ = access.f64(&format!("readouts.{layer}.linear.output_mask"), &[1])?;
        } else {
            let nonlinear_prefix = format!("readouts.{layer}");
            let _ = validate_dynamic_f64_tensor_rank(
                &access,
                &format!("{nonlinear_prefix}.linear_1.weight"),
                1,
            )?;
            let _ = validate_dynamic_f64_tensor_rank(
                &access,
                &format!("{nonlinear_prefix}.linear_mid.weight"),
                1,
            )?;
            let _ = validate_dynamic_f64_tensor_rank(
                &access,
                &format!("{nonlinear_prefix}.linear_2.weight"),
                1,
            )?;
            let _ = access.f64(&format!("{nonlinear_prefix}.linear_2.output_mask"), &[1])?;
        }
    }
    Ok(())
}

fn validate_local_backbone_forward_contract(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    spec: &MacePolarModelSpec,
) -> Result<(), MacePolarError> {
    if spec.selected_model != SELECTED_MODEL_POLAR_1_S {
        return validate_model_specific_local_backbone_forward_contract(tensors, spec);
    }
    require_eq(
        "local_backbone.selected_model",
        LOCAL_BACKBONE_FORWARD_CONTRACT.selected_model,
        SELECTED_MODEL,
    )?;
    require_usize(
        "local_backbone.num_interactions",
        LOCAL_BACKBONE_FORWARD_CONTRACT.num_interactions,
        1,
    )?;
    require_usize(
        "local_backbone.num_bessel",
        LOCAL_BACKBONE_FORWARD_CONTRACT.num_bessel,
        8,
    )?;
    require_usize(
        "local_backbone.edge_attr_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.edge_attr_dim,
        16,
    )?;
    require_usize(
        "local_backbone.node_attr_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
        83,
    )?;
    require_usize(
        "local_backbone.hidden_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        512,
    )?;
    require_usize(
        "local_backbone.radial_mlp_input_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim,
        1_032,
    )?;
    require_usize(
        "local_backbone.radial_mlp_hidden_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim,
        64,
    )?;
    require_usize(
        "local_backbone.radial_mlp_output_dim",
        LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_output_dim,
        2_048,
    )?;
    require_usize(
        "local_backbone.symmetric_contraction_correlation",
        LOCAL_BACKBONE_FORWARD_CONTRACT.symmetric_contraction_correlation,
        3,
    )?;
    require_usize(
        "local_backbone.tensor_count",
        tensors.len(),
        LOCAL_BACKBONE_TENSOR_COUNT,
    )?;
    let numel = tensors.values().map(|tensor| tensor.values.len()).sum();
    require_usize("local_backbone.numel", numel, LOCAL_BACKBONE_NUMEL)?;

    let access = MacePolarTensorAccess::new(tensors);
    for spec in LOCAL_BACKBONE_FORWARD_TENSOR_SPECS {
        match spec.dtype {
            MacePolarTensorDtype::Bool => {
                let _ = access.bool(spec.name, spec.shape)?;
            }
            MacePolarTensorDtype::F64 => {
                let _ = access.f64(spec.name, spec.shape)?;
            }
            MacePolarTensorDtype::I32 => {
                let _ = access.i32(spec.name, spec.shape)?;
            }
            MacePolarTensorDtype::I64 => {
                let _ = access.i64(spec.name, spec.shape)?;
            }
        }
    }
    Ok(())
}

type MacePolarRows = Vec<Vec<f64>>;
type MacePolarRowsF32 = Vec<Vec<f32>>;

#[allow(dead_code)]
#[derive(Clone, Debug)]
struct MacePolarPositionCotangents {
    positions: Vec<[f64; 3]>,
}

impl MacePolarPositionCotangents {
    #[allow(dead_code)]
    fn zeros(node_count: usize) -> Self {
        Self {
            positions: vec![[0.0; 3]; node_count],
        }
    }

    #[allow(dead_code)]
    fn add_node(&mut self, node: usize, cotangent: [f64; 3]) -> Result<(), MacePolarError> {
        let row_count = self.positions.len();
        let row = self.positions.get_mut(node).ok_or_else(|| {
            invalid(
                "mace_polar.position_cotangents",
                format!("node index {node} is out of range for {row_count} rows"),
            )
        })?;
        for component in 0..3 {
            row[component] += cotangent[component];
        }
        Ok(())
    }

    #[allow(dead_code)]
    fn add_in_place(&mut self, other: &Self, name: &str) -> Result<(), MacePolarError> {
        require_usize(
            &format!("{name}.positions.len"),
            other.positions.len(),
            self.positions.len(),
        )?;
        for (row, other_row) in self.positions.iter_mut().zip(&other.positions) {
            for component in 0..3 {
                row[component] += other_row[component];
            }
        }
        Ok(())
    }
}

#[allow(dead_code)]
fn polar_mace_position_cotangents_displacement_gradient(
    positions: &[[f64; 3]],
    cotangents: &MacePolarPositionCotangents,
) -> Result<Mat3, MacePolarError> {
    require_usize(
        "mace_polar.displacement_gradient.positions.len",
        positions.len(),
        cotangents.positions.len(),
    )?;
    let mut displacement_gradient = [[0.0_f64; 3]; 3];
    for (position, cotangent) in positions.iter().zip(&cotangents.positions) {
        for row in 0..3 {
            for (col, bar_component) in cotangent.iter().enumerate() {
                displacement_gradient[row][col] += position[row] * bar_component;
            }
        }
    }
    Ok(displacement_gradient)
}

#[must_use]
fn symmetric_part(matrix: Mat3) -> Mat3 {
    let mut out = matrix;
    for row in 0..3 {
        for col in 0..row {
            let value = 0.5 * (matrix[row][col] + matrix[col][row]);
            out[row][col] = value;
            out[col][row] = value;
        }
    }
    out
}

