#[allow(dead_code)]
fn polar_mace_add_rows_in_place(
    target: &mut [Vec<f64>],
    source: &[Vec<f64>],
    name: &str,
) -> Result<(), MacePolarError> {
    require_usize(&format!("{name}.source.len"), source.len(), target.len())?;
    for (row_index, (target_row, source_row)) in target.iter_mut().zip(source).enumerate() {
        require_usize(
            &format!("{name}.source[{row_index}].len"),
            source_row.len(),
            target_row.len(),
        )?;
        for (target_value, source_value) in target_row.iter_mut().zip(source_row) {
            *target_value += *source_value;
        }
    }
    Ok(())
}

