#[allow(dead_code)]
impl MacePolarLocalBackboneFirstSlice {
    fn non_pbc_from_positions(positions: &[[f64; 3]], r_max: f64) -> Result<Self, MacePolarError> {
        if positions.is_empty() {
            return Err(invalid(
                "local_backbone.first_slice",
                "structure must contain at least one atom",
            ));
        }
        if !r_max.is_finite() || r_max <= 0.0 {
            return Err(invalid(
                "local_backbone.first_slice",
                format!("r_max must be finite and positive, got {r_max}"),
            ));
        }

        let edge_capacity = positions
            .len()
            .saturating_mul(positions.len().saturating_sub(1));
        let mut edge_index = Vec::with_capacity(edge_capacity);
        let mut vectors = Vec::with_capacity(edge_capacity);
        let mut lengths = Vec::with_capacity(edge_capacity);
        let cutoff_squared = r_max * r_max;
        // Upstream MACE uses edge_index[0] as sender/source and edge_index[1]
        // as receiver/target. Vectors therefore follow target - source.
        for (source, source_position) in positions.iter().enumerate() {
            for (target, target_position) in positions.iter().enumerate() {
                if source == target {
                    continue;
                }
                let vector = [
                    target_position[0] - source_position[0],
                    target_position[1] - source_position[1],
                    target_position[2] - source_position[2],
                ];
                let length_squared =
                    vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2];
                if length_squared >= cutoff_squared {
                    continue;
                }
                let length = length_squared.sqrt();
                edge_index.push([source, target]);
                vectors.push(vector);
                lengths.push(length);
            }
        }

        let edge_attrs = polar_mace_edge_attrs(&vectors)?;
        let cutoffs = lengths
            .iter()
            .map(|length| polar_mace_polynomial_cutoff(*length, r_max, 5))
            .collect::<Vec<_>>();
        let edge_feats = polar_mace_radial_edge_feats(&lengths, r_max, 8);

        Ok(Self {
            edge_index,
            vectors,
            lengths,
            edge_attrs,
            cutoffs,
            edge_feats,
        })
    }

    #[cfg(test)]
    fn non_pbc_water_from_positions(positions: &[[f64; 3]]) -> Result<Self, MacePolarError> {
        if positions.len() != 3 {
            return Err(invalid(
                "local_backbone.first_slice",
                "the pinned first arithmetic slice expects the three-atom water fixture",
            ));
        }
        Self::non_pbc_from_positions(positions, 6.0)
    }
}

#[allow(dead_code)]
fn polar_mace_edge_attrs(vectors: &[[f64; 3]]) -> Result<MacePolarRows, MacePolarError> {
    let plan = e3nn_core::SphericalHarmonicsPlan::component(3, true)
        .map_err(|err| invalid("local_backbone.edge_attrs", err.to_string()))?;
    let mut edge_attrs = Vec::with_capacity(vectors.len());
    for vector in vectors {
        let input = permute_polar_mace_vector_to_e3nn(*vector);
        let mut attrs = vec![0.0; plan.output_dim()];
        plan.forward(input, &mut attrs)
            .map_err(|err| invalid("local_backbone.edge_attrs", err.to_string()))?;
        edge_attrs.push(attrs);
    }
    Ok(edge_attrs)
}

#[allow(dead_code)]
fn polar_mace_polynomial_cutoff(length: f64, r_max: f64, p: i32) -> f64 {
    if length >= r_max {
        return 0.0;
    }
    if length <= 0.0 {
        return 1.0;
    }
    let x = length / r_max;
    let p_f64 = f64::from(p);
    1.0 - ((p_f64 + 1.0) * (p_f64 + 2.0) / 2.0) * x.powi(p) + p_f64 * (p_f64 + 2.0) * x.powi(p + 1)
        - (p_f64 * (p_f64 + 1.0) / 2.0) * x.powi(p + 2)
}

#[allow(dead_code)]
fn polar_mace_polynomial_cutoff_derivative(length: f64, r_max: f64, p: i32) -> f64 {
    if length >= r_max || length <= 0.0 {
        return 0.0;
    }
    let x = length / r_max;
    let p_f64 = f64::from(p);
    let a = (p_f64 + 1.0) * (p_f64 + 2.0) / 2.0;
    let b = p_f64 * (p_f64 + 2.0);
    let c = p_f64 * (p_f64 + 1.0) / 2.0;
    (-a * p_f64 * x.powi(p - 1) + b * (p_f64 + 1.0) * x.powi(p) - c * (p_f64 + 2.0) * x.powi(p + 1))
        / r_max
}

#[allow(dead_code)]
fn polar_mace_radial_edge_feats(lengths: &[f64], r_max: f64, num_bessel: usize) -> MacePolarRows {
    let normalization = (2.0 / r_max).sqrt();
    lengths
        .iter()
        .map(|length| {
            (1..=num_bessel)
                .map(|n| {
                    if *length <= 0.0 {
                        0.0
                    } else {
                        let frequency = n as f64 * std::f64::consts::PI / r_max;
                        normalization * (frequency * *length).sin() / *length
                    }
                })
                .collect()
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_radial_edge_feats_from_weights(
    lengths: &[f64],
    prefactor: f64,
    weights: &[f64],
) -> MacePolarRows {
    lengths
        .iter()
        .map(|length| {
            weights
                .iter()
                .map(|weight| {
                    if *length <= 0.0 {
                        0.0
                    } else {
                        prefactor * (*weight * *length).sin() / *length
                    }
                })
                .collect()
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_radial_edge_feats_from_weights_length_vjp(
    output_cotangent: &[Vec<f64>],
    lengths: &[f64],
    prefactor: f64,
    weights: &[f64],
) -> Result<Vec<f64>, MacePolarError> {
    require_usize(
        "radial_edge_feats_vjp.output_cotangent.len",
        output_cotangent.len(),
        lengths.len(),
    )?;
    let mut length_cotangent = vec![0.0_f64; lengths.len()];
    for (edge, (bar_row, length)) in output_cotangent.iter().zip(lengths).enumerate() {
        require_usize(
            &format!("radial_edge_feats_vjp.output_cotangent[{edge}].len"),
            bar_row.len(),
            weights.len(),
        )?;
        if *length <= 0.0 {
            continue;
        }
        let inv_length_sq = 1.0 / (length * length);
        for (bar, weight) in bar_row.iter().zip(weights) {
            let phase = weight * length;
            let derivative =
                prefactor * (weight * phase.cos() * length - phase.sin()) * inv_length_sq;
            length_cotangent[edge] += bar * derivative;
        }
    }
    Ok(length_cotangent)
}

#[allow(dead_code)]
fn polar_mace_node_feats_initial_from_species(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    species: &[String],
) -> Result<MacePolarRows, MacePolarError> {
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    polar_mace_node_feats_initial_from_atomic_numbers(tensors, &atomic_numbers)
}

#[allow(dead_code)]
fn polar_mace_node_feats_initial_from_atomic_numbers(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    atomic_numbers: &[u8],
) -> Result<MacePolarRows, MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let weight = access.f64("node_embedding.linear.weight", &[42_496])?;
    let output_mask = access.f64("node_embedding.linear.output_mask", &[512])?;
    let bias = access
        .f64("node_embedding.linear.bias", &[0])
        .or_else(|_| {
            access.f64(
                "node_embedding.linear.bias",
                &[LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim],
            )
        })?;

    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim;
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    require_usize(
        "node_embedding.linear.weight.rows",
        weight.len(),
        hidden_dim * input_dim,
    )?;
    if !bias.is_empty() && bias.len() != hidden_dim {
        return Err(invalid(
            "node_embedding.linear.bias",
            format!("expected length 0 or {hidden_dim}, got {}", bias.len()),
        ));
    }

    atomic_numbers
        .iter()
        .map(|atomic_number| {
            let type_index = polar_mace_type_index_from_atomic_number(*atomic_number)?;
            let path_weight = 1.0 / (input_dim as f64).sqrt();
            let mut row = Vec::with_capacity(hidden_dim);
            for feature in 0..hidden_dim {
                let weight_value = weight[type_index * hidden_dim + feature];
                let bias_value = bias.get(feature).copied().unwrap_or(0.0);
                row.push((path_weight * weight_value + bias_value) * output_mask[feature]);
            }
            Ok(row)
        })
        .collect()
}

