// Force-only VJP: returns only the edge-feature cotangent needed for position
// derivatives. Source/target embedding cotangents are species-side fixed inputs
// in this runtime and are intentionally not propagated.
fn polar_mace_edge_aug_rows_vjp(
    output_cotangent: &[Vec<f64>],
    edge_feats: &[Vec<f64>],
    edge_index: &[[usize; 2]],
    source_embedding: &[Vec<f64>],
    target_embedding: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        "edge_aug_vjp.output_cotangent.len",
        output_cotangent.len(),
        edge_index.len(),
    )?;
    require_usize(
        "edge_aug_vjp.edge_feats.len",
        edge_feats.len(),
        edge_index.len(),
    )?;
    let edge_feat_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.num_bessel;
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let mut edge_feats_cotangent = polar_mace_zero_rows_like(edge_feats);
    for (edge, [source_index, target_index]) in edge_index.iter().copied().enumerate() {
        require_usize(
            &format!("edge_aug_vjp.edge_feats[{edge}].len"),
            edge_feats[edge].len(),
            edge_feat_dim,
        )?;
        let source = source_embedding.get(source_index).ok_or_else(|| {
            invalid(
                "edge_aug_vjp.source_embedding",
                format!("missing source row {source_index}"),
            )
        })?;
        let target = target_embedding.get(target_index).ok_or_else(|| {
            invalid(
                "edge_aug_vjp.target_embedding",
                format!("missing target row {target_index}"),
            )
        })?;
        require_usize(
            &format!("edge_aug_vjp.source_embedding[{source_index}].len"),
            source.len(),
            hidden_dim,
        )?;
        require_usize(
            &format!("edge_aug_vjp.target_embedding[{target_index}].len"),
            target.len(),
            hidden_dim,
        )?;
        require_usize(
            &format!("edge_aug_vjp.output_cotangent[{edge}].len"),
            output_cotangent[edge].len(),
            edge_feat_dim + 2 * hidden_dim,
        )?;
        edge_feats_cotangent[edge].copy_from_slice(&output_cotangent[edge][0..edge_feat_dim]);
    }
    Ok(edge_feats_cotangent)
}

