#[allow(dead_code)]
fn polar_mace_type_index_from_atomic_number(atomic_number: u8) -> Result<usize, MacePolarError> {
    if (1..=83).contains(&atomic_number) {
        Ok(usize::from(atomic_number - 1))
    } else {
        Err(invalid(
            "node_embedding.atomic_numbers",
            format!("unsupported atomic number `{atomic_number}`; expected 1..83"),
        ))
    }
}

#[allow(dead_code)]
fn polar_mace_node_attr_rows_from_atomic_numbers(
    atomic_numbers: &[u8],
) -> Result<MacePolarRows, MacePolarError> {
    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim;
    atomic_numbers
        .iter()
        .map(|atomic_number| {
            let type_index = polar_mace_type_index_from_atomic_number(*atomic_number)?;
            let mut row = vec![0.0; input_dim];
            row[type_index] = 1.0;
            Ok(row)
        })
        .collect()
}

