impl MacePolarAuxiliaryPrediction {
    fn from_realspace_scf_slice(
        slice: &MacePolarRealspaceScfRuntimeSlice,
    ) -> Result<Self, MacePolarError> {
        let density_coefficients = mace_polar_auxiliary_row4_values(
            &slice.scf.charge_density_outputs.density_coefficients,
            "mace_polar.auxiliary.density_coefficients",
        )?;
        let spin_density = mace_polar_auxiliary_row4_values(
            &slice.scf.charge_density_outputs.spin_density,
            "mace_polar.auxiliary.spin_density",
        )?;
        let spin_charge_density = slice
            .scf
            .step1_update
            .spin_charge_density_after_correction
            .iter()
            .enumerate()
            .map(|(row_index, row)| {
                require_usize(
                    &format!("mace_polar.auxiliary.spin_charge_density[{row_index}].len"),
                    row.len(),
                    8,
                )?;
                Ok([
                    [row[0], row[1], row[2], row[3]],
                    [row[4], row[5], row[6], row[7]],
                ])
            })
            .collect::<Result<Vec<_>, MacePolarError>>()?;

        Ok(Self {
            density_coefficients,
            spin_density,
            spin_charge_density,
            charges: slice.scf.charge_density_outputs.charges.clone(),
            spins: slice.scf.charge_density_outputs.spins.clone(),
            total_charge_by_graph: slice
                .scf
                .charge_density_outputs
                .total_charge_by_graph
                .clone(),
            total_dipole_by_graph: slice
                .scf
                .charge_density_outputs
                .total_dipole_by_graph
                .clone(),
            atomic_energy_by_graph: slice.scf.atomic_energy_by_graph.clone(),
            interaction_energy: slice.scf.handoff.local_backbone.interaction_energy,
            electron_energy: slice.scf.local_electron_energy.electron_energy,
            electrostatic_energy_by_graph: slice
                .scf
                .realspace_coulomb
                .electrostatic_energy_by_graph
                .clone(),
            energy_without_external_by_graph: slice.scf.energy_without_external_by_graph.clone(),
            external_dipole_energy_by_graph: slice.external_dipole_energy_by_graph.clone(),
            total_energy_by_graph: slice.total_energy_by_graph.clone(),
        })
    }
}

fn mace_polar_auxiliary_row4_values(
    rows: &[Vec<f64>],
    field: &str,
) -> Result<Vec<[f64; 4]>, MacePolarError> {
    rows.iter()
        .enumerate()
        .map(|(row_index, row)| {
            require_usize(&format!("{field}[{row_index}].len"), row.len(), 4)?;
            Ok([row[0], row[1], row[2], row[3]])
        })
        .collect()
}

