#[allow(dead_code)]
fn polar_mace_layer_feature_mixer_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    product_out: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_layer_feature_mixer_rows_from_tensors_for_layer(access, 0, product_out)
}

#[allow(dead_code)]
fn polar_mace_layer_feature_mixer_rows_from_tensors_for_layer(
    access: &MacePolarTensorAccess<'_>,
    layer: usize,
    product_out: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    let input_dim = product_out.first().map_or(0, Vec::len);
    let instructions = polar_mace_product_block_linear_instructions(input_dim)?;
    let weight_len = instructions
        .last()
        .map(|instruction| {
            instruction.weight_offset + instruction.input_mul * instruction.output_mul
        })
        .unwrap_or(0);
    let prefix = format!("layer_feature_mixer.linears.{layer}");
    let output_mask = access.f64(&format!("{prefix}.output_mask"), &[input_dim])?;
    let weight = access.f64(&format!("{prefix}.weight"), &[weight_len])?;
    let bias = access
        .f64(&format!("{prefix}.bias"), &[0])
        .or_else(|_| access.f64(&format!("{prefix}.bias"), &[input_dim]))?;
    polar_mace_e3nn_block_linear_rows(
        product_out,
        MacePolarBlockLinearSpec {
            weight,
            bias,
            output_mask,
            instructions: &instructions,
            instruction_path_weights: None,
            input_dim,
            output_dim: input_dim,
            name: &prefix,
        },
    )
}

#[allow(dead_code)]
fn polar_mace_layer_feature_mixer_rows_from_layer_outputs(
    access: &MacePolarTensorAccess<'_>,
    product_out_by_layer: &[MacePolarRows],
) -> Result<MacePolarRows, MacePolarError> {
    let mut iter = product_out_by_layer.iter().enumerate();
    let (first_layer, first_product_out) = iter.next().ok_or_else(|| {
        invalid(
            "layer_feature_mixer",
            "expected at least one layer product output",
        )
    })?;
    let mut mixed = polar_mace_layer_feature_mixer_rows_from_tensors_for_layer(
        access,
        first_layer,
        first_product_out,
    )?;
    for (layer, product_out) in iter {
        let layer_mixed =
            polar_mace_layer_feature_mixer_rows_from_tensors_for_layer(access, layer, product_out)?;
        polar_mace_add_rows_in_place(
            &mut mixed,
            &layer_mixed,
            "layer_feature_mixer.multi_layer_sum",
        )?;
    }
    Ok(mixed)
}

