    mace_polar_trace_stage("scalar_handoff_vjp.total", total_start);

    Ok(MacePolarScalarEnergyHandoffCotangents {
        local_backbone_product_out: product_out_cotangent,
        local_backbone_product_out_by_layer: product_out_by_layer_cotangent,
    })
