#[allow(dead_code)]
fn polar_mace_fukui_norm_rows(
    raw_rows: &[Vec<f64>],
    batch: &[usize],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize("fukui_norm.batch.len", batch.len(), raw_rows.len())?;
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    let mut by_graph = vec![[0.0_f64; 2]; graph_count];
    for (row_index, (row, graph)) in raw_rows.iter().zip(batch).enumerate() {
        require_usize(&format!("fukui_norm.rows[{row_index}].len"), row.len(), 2)?;
        by_graph[*graph][0] += row[0];
        by_graph[*graph][1] += row[1];
    }
    Ok(batch
        .iter()
        .map(|graph| by_graph[*graph].to_vec())
        .collect())
}

#[allow(dead_code)]
fn polar_mace_fukui_norm_rows_vjp(
    output_cotangent: &[Vec<f64>],
    raw_rows: &[Vec<f64>],
    batch: &[usize],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize("fukui_norm_vjp.batch.len", batch.len(), raw_rows.len())?;
    require_usize(
        "fukui_norm_vjp.output_cotangent.len",
        output_cotangent.len(),
        raw_rows.len(),
    )?;
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    let mut by_graph = vec![[0.0_f64; 2]; graph_count];
    for (row_index, (bar_row, raw_row)) in output_cotangent.iter().zip(raw_rows).enumerate() {
        require_usize(
            &format!("fukui_norm_vjp.raw[{row_index}].len"),
            raw_row.len(),
            2,
        )?;
        require_usize(
            &format!("fukui_norm_vjp.output_cotangent[{row_index}].len"),
            bar_row.len(),
            2,
        )?;
        by_graph[batch[row_index]][0] += bar_row[0];
        by_graph[batch[row_index]][1] += bar_row[1];
    }
    Ok(batch
        .iter()
        .map(|graph| by_graph[*graph].to_vec())
        .collect())
}

#[allow(dead_code)]
fn polar_mace_normalize_fukui_source_rows(
    raw_rows: &[Vec<f64>],
    norm_rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        "fukui_normalize.norm_rows.len",
        norm_rows.len(),
        raw_rows.len(),
    )?;
    raw_rows
        .iter()
        .zip(norm_rows)
        .enumerate()
        .map(|(row_index, (raw, norm))| {
            require_usize(
                &format!("fukui_normalize.raw[{row_index}].len"),
                raw.len(),
                2,
            )?;
            require_usize(
                &format!("fukui_normalize.norm[{row_index}].len"),
                norm.len(),
                2,
            )?;
            Ok(vec![
                raw[0] / if norm[0] == 0.0 { 1.0 } else { norm[0] },
                raw[1] / if norm[1] == 0.0 { 1.0 } else { norm[1] },
            ])
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_normalize_fukui_source_rows_vjp(
    output_cotangent: &[Vec<f64>],
    raw_rows: &[Vec<f64>],
    norm_rows: &[Vec<f64>],
) -> Result<(MacePolarRows, MacePolarRows), MacePolarError> {
    require_usize(
        "fukui_normalize_vjp.norm_rows.len",
        norm_rows.len(),
        raw_rows.len(),
    )?;
    require_usize(
        "fukui_normalize_vjp.output_cotangent.len",
        output_cotangent.len(),
        raw_rows.len(),
    )?;
    let mut raw_cotangent = polar_mace_zero_rows_like(raw_rows);
    let mut norm_cotangent = polar_mace_zero_rows_like(norm_rows);
    for (row_index, ((bar_row, raw), norm)) in output_cotangent
        .iter()
        .zip(raw_rows)
        .zip(norm_rows)
        .enumerate()
    {
        require_usize(
            &format!("fukui_normalize_vjp.raw[{row_index}].len"),
            raw.len(),
            2,
        )?;
        require_usize(
            &format!("fukui_normalize_vjp.norm[{row_index}].len"),
            norm.len(),
            2,
        )?;
        require_usize(
            &format!("fukui_normalize_vjp.output_cotangent[{row_index}].len"),
            bar_row.len(),
            2,
        )?;
        for component in 0..2 {
            if norm[component] == 0.0 {
                raw_cotangent[row_index][component] += bar_row[component];
            } else {
                raw_cotangent[row_index][component] += bar_row[component] / norm[component];
                norm_cotangent[row_index][component] -=
                    bar_row[component] * raw[component] / (norm[component] * norm[component]);
            }
        }
    }
    Ok((raw_cotangent, norm_cotangent))
}

#[allow(dead_code)]
fn polar_mace_fukui_charge_correction_rows(
    spin_charge_density_accumulated: &[Vec<f64>],
    fukui_sources_normalized: &[Vec<f64>],
    total_charge: f64,
    total_spin: f64,
    batch: &[usize],
) -> Result<MacePolarFukuiChargeCorrection, MacePolarError> {
    if !total_charge.is_finite() || !total_spin.is_finite() {
        return Err(invalid(
            "fukui_charge_correction",
            "total_charge and total_spin must be finite",
        ));
    }
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    let total_charges = vec![total_charge; graph_count];
    let total_spins = vec![total_spin; graph_count];
    polar_mace_fukui_charge_correction_rows_for_graph_targets(
        spin_charge_density_accumulated,
        fukui_sources_normalized,
        &total_charges,
        &total_spins,
        batch,
    )
}

#[allow(dead_code)]
fn polar_mace_fukui_charge_correction_rows_for_graph_targets(
    spin_charge_density_accumulated: &[Vec<f64>],
    fukui_sources_normalized: &[Vec<f64>],
    total_charges: &[f64],
    total_spins: &[f64],
    batch: &[usize],
) -> Result<MacePolarFukuiChargeCorrection, MacePolarError> {
    let atom_count = spin_charge_density_accumulated.len();
    require_usize(
        "fukui_charge_correction.fukui_sources.len",
        fukui_sources_normalized.len(),
        atom_count,
    )?;
    require_usize("fukui_charge_correction.batch.len", batch.len(), atom_count)?;
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    require_usize(
        "fukui_charge_correction.total_charges.len",
        total_charges.len(),
        graph_count,
    )?;
    require_usize(
        "fukui_charge_correction.total_spins.len",
        total_spins.len(),
        graph_count,
    )?;
    for (graph, (total_charge, total_spin)) in total_charges.iter().zip(total_spins).enumerate() {
        if !total_charge.is_finite() || !total_spin.is_finite() {
            return Err(invalid(
                "fukui_charge_correction",
                format!("graph {graph} total charge/spin must be finite"),
            ));
        }
    }
    let mut predicted_by_graph = vec![[0.0_f64; 2]; graph_count];
    for (row_index, (row, graph)) in spin_charge_density_accumulated
        .iter()
        .zip(batch)
        .enumerate()
    {
        require_usize(
            &format!("fukui_charge_correction.spin_charge_density[{row_index}].len"),
            row.len(),
            8,
        )?;
        predicted_by_graph[*graph][0] += row[0];
        predicted_by_graph[*graph][1] += row[4];
    }

    let mut corrected = spin_charge_density_accumulated.to_vec();
    let mut predicted_total_charges = Vec::with_capacity(atom_count);
    let mut q_plus_s_by_node = Vec::with_capacity(atom_count);
    let mut q_minus_s_by_node = Vec::with_capacity(atom_count);
    for (row_index, ((row, fukui), graph)) in corrected
        .iter_mut()
        .zip(fukui_sources_normalized)
        .zip(batch)
        .enumerate()
    {
        require_usize(
            &format!("fukui_charge_correction.fukui_sources[{row_index}].len"),
            fukui.len(),
            2,
        )?;
        let total_charge = total_charges[*graph];
        let total_spin = total_spins[*graph];
        let q_plus_s = total_charge + (total_spin - 1.0);
        let q_minus_s = total_charge - (total_spin - 1.0);
        let predicted = predicted_by_graph[*graph];
        row[0] += fukui[0] * ((q_plus_s / 2.0) - predicted[0]);
        row[4] += fukui[1] * ((q_minus_s / 2.0) - predicted[1]);
        predicted_total_charges.push(predicted.to_vec());
        q_plus_s_by_node.push(q_plus_s);
        q_minus_s_by_node.push(q_minus_s);
    }

    Ok(MacePolarFukuiChargeCorrection {
        corrected_spin_charge_density: corrected,
        predicted_total_charges,
        q_plus_s_by_node,
        q_minus_s_by_node,
    })
}

#[allow(dead_code)]
fn polar_mace_fukui_charge_correction_rows_vjp(
    output_cotangent: &[Vec<f64>],
    predicted_total_charges_cotangent: Option<&[Vec<f64>]>,
    spin_charge_density_accumulated: &[Vec<f64>],
    fukui_sources_normalized: &[Vec<f64>],
    total_charges: &[f64],
    total_spins: &[f64],
    batch: &[usize],
) -> Result<MacePolarFukuiChargeCorrectionCotangents, MacePolarError> {
    let atom_count = spin_charge_density_accumulated.len();
    require_usize(
        "fukui_charge_correction_vjp.output_cotangent.len",
        output_cotangent.len(),
        atom_count,
    )?;
    require_usize(
        "fukui_charge_correction_vjp.fukui_sources.len",
        fukui_sources_normalized.len(),
        atom_count,
    )?;
    require_usize(
        "fukui_charge_correction_vjp.batch.len",
        batch.len(),
        atom_count,
    )?;
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    require_usize(
        "fukui_charge_correction_vjp.total_charges.len",
        total_charges.len(),
        graph_count,
    )?;
    require_usize(
        "fukui_charge_correction_vjp.total_spins.len",
        total_spins.len(),
        graph_count,
    )?;
    for (graph, (total_charge, total_spin)) in total_charges.iter().zip(total_spins).enumerate() {
        if !total_charge.is_finite() || !total_spin.is_finite() {
            return Err(invalid(
                "fukui_charge_correction_vjp",
                format!("graph {graph} total charge/spin must be finite"),
            ));
        }
    }
    let mut predicted_by_graph = vec![[0.0_f64; 2]; graph_count];
    for (row_index, (row, graph)) in spin_charge_density_accumulated
        .iter()
        .zip(batch)
        .enumerate()
    {
        require_usize(
            &format!("fukui_charge_correction_vjp.spin_charge_density[{row_index}].len"),
            row.len(),
            8,
        )?;
        predicted_by_graph[*graph][0] += row[0];
        predicted_by_graph[*graph][1] += row[4];
    }

    let mut spin_cotangent = polar_mace_zero_rows_like(spin_charge_density_accumulated);
    let mut fukui_cotangent = polar_mace_zero_rows_like(fukui_sources_normalized);
    let mut predicted_cotangent_by_graph = vec![[0.0_f64; 2]; graph_count];
    if let Some(predicted_cotangent) = predicted_total_charges_cotangent {
        require_usize(
            "fukui_charge_correction_vjp.predicted_total_charges_cotangent.len",
            predicted_cotangent.len(),
            atom_count,
        )?;
        for (row_index, (bar_predicted, graph)) in predicted_cotangent.iter().zip(batch).enumerate()
        {
            require_usize(
                &format!(
                    "fukui_charge_correction_vjp.predicted_total_charges_cotangent[{row_index}].len"
                ),
                bar_predicted.len(),
                2,
            )?;
            predicted_cotangent_by_graph[*graph][0] += bar_predicted[0];
            predicted_cotangent_by_graph[*graph][1] += bar_predicted[1];
        }
    }
    for (row_index, ((bar_row, fukui), graph)) in output_cotangent
        .iter()
        .zip(fukui_sources_normalized)
        .zip(batch)
        .enumerate()
    {
        require_usize(
            &format!("fukui_charge_correction_vjp.output_cotangent[{row_index}].len"),
            bar_row.len(),
            8,
        )?;
        require_usize(
            &format!("fukui_charge_correction_vjp.fukui_sources[{row_index}].len"),
            fukui.len(),
            2,
        )?;
        for component in 0..8 {
            spin_cotangent[row_index][component] += bar_row[component];
        }
        let q_plus_s = total_charges[*graph] + (total_spins[*graph] - 1.0);
        let q_minus_s = total_charges[*graph] - (total_spins[*graph] - 1.0);
        let delta_plus = (q_plus_s / 2.0) - predicted_by_graph[*graph][0];
        let delta_minus = (q_minus_s / 2.0) - predicted_by_graph[*graph][1];
        fukui_cotangent[row_index][0] += bar_row[0] * delta_plus;
        fukui_cotangent[row_index][1] += bar_row[4] * delta_minus;
        predicted_cotangent_by_graph[*graph][0] -= bar_row[0] * fukui[0];
        predicted_cotangent_by_graph[*graph][1] -= bar_row[4] * fukui[1];
    }
    for (row_index, graph) in batch.iter().enumerate() {
        spin_cotangent[row_index][0] += predicted_cotangent_by_graph[*graph][0];
        spin_cotangent[row_index][4] += predicted_cotangent_by_graph[*graph][1];
    }
    Ok(MacePolarFukuiChargeCorrectionCotangents {
        spin_charge_density_accumulated: spin_cotangent,
        fukui_sources_normalized: fukui_cotangent,
    })
}

