#[allow(dead_code)]
fn polar_mace_fukui_source_map_activation_rows(
    input_rows: &[Vec<f64>],
    normalize2mom_constant: f64,
) -> Result<MacePolarRows, MacePolarError> {
    if !normalize2mom_constant.is_finite() {
        return Err(invalid(
            "fukui_source_map.activation",
            "normalize2mom constant must be finite",
        ));
    }
    input_rows
        .iter()
        .enumerate()
        .map(|(row_index, row)| {
            require_usize(
                &format!("fukui_source_map.activation.input[{row_index}].len"),
                row.len(),
                16,
            )?;
            Ok(row
                .iter()
                .map(|value| normalize2mom_constant * value / (1.0 + (-value).exp()))
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_fukui_source_map_activation_rows_vjp(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    normalize2mom_constant: f64,
) -> Result<MacePolarRows, MacePolarError> {
    if !normalize2mom_constant.is_finite() {
        return Err(invalid(
            "fukui_source_map.activation",
            "normalize2mom constant must be finite",
        ));
    }
    require_usize(
        "fukui_source_map.activation.output_cotangent.len",
        output_cotangent.len(),
        input_rows.len(),
    )?;
    input_rows
        .iter()
        .zip(output_cotangent)
        .enumerate()
        .map(|(row_index, (row, bar_output))| {
            require_usize(
                &format!("fukui_source_map.activation.input[{row_index}].len"),
                row.len(),
                16,
            )?;
            require_usize(
                &format!("fukui_source_map.activation.output_cotangent[{row_index}].len"),
                bar_output.len(),
                16,
            )?;
            if !row.iter().all(|value| value.is_finite())
                || !bar_output.iter().all(|value| value.is_finite())
            {
                return Err(invalid(
                    "fukui_source_map.activation",
                    format!("row {row_index} input and output cotangent must be finite"),
                ));
            }
            Ok(row
                .iter()
                .zip(bar_output)
                .map(|(value, bar)| {
                    let sigmoid = 1.0 / (1.0 + (-value).exp());
                    bar * normalize2mom_constant * (sigmoid + value * sigmoid * (1.0 - sigmoid))
                })
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_fukui_source_map_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    input_rows: &[Vec<f64>],
    normalize2mom_constant: f64,
) -> Result<MacePolarRows, MacePolarError> {
    let input_dim = input_rows.first().map_or(0, Vec::len);
    let linear_1 = if input_dim == 512 {
        polar_mace_fukui_source_map_linear_rows_from_tensors(
            access, "linear_1", input_rows, 512, 16, 0,
        )?
    } else {
        polar_mace_runtime_block_linear_rows_from_tensors(
            access,
            "fukui_source_map.linear_1",
            input_rows,
            &MacePolarRuntimeLinearPlan {
                input_dim,
                output_dim: 16,
                weight_len: 512 * 16,
                instructions: vec![MacePolarBlockLinearInstruction {
                    input_start: 0,
                    output_start: 0,
                    input_mul: 512,
                    output_mul: 16,
                    irrep_dim: 1,
                    weight_offset: 0,
                }],
                path_weights: vec![polar_mace_scalar_path_weight(512)],
            },
        )?
    };
    let activation_1 =
        polar_mace_fukui_source_map_activation_rows(&linear_1, normalize2mom_constant)?;
    let linear_mid = polar_mace_fukui_source_map_linear_rows_from_tensors(
        access,
        "linear_mid",
        &activation_1,
        16,
        16,
        16,
    )?;
    let activation_mid =
        polar_mace_fukui_source_map_activation_rows(&linear_mid, normalize2mom_constant)?;
    polar_mace_fukui_source_map_linear_rows_from_tensors(
        access,
        "linear_2",
        &activation_mid,
        16,
        2,
        2,
    )
}

#[allow(dead_code)]
fn polar_mace_fukui_source_map_rows_vjp_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    normalize2mom_constant: f64,
) -> Result<MacePolarRows, MacePolarError> {
    let input_dim = input_rows.first().map_or(0, Vec::len);
    let dynamic_linear_1_plan = MacePolarRuntimeLinearPlan {
        input_dim,
        output_dim: 16,
        weight_len: 512 * 16,
        instructions: vec![MacePolarBlockLinearInstruction {
            input_start: 0,
            output_start: 0,
            input_mul: 512,
            output_mul: 16,
            irrep_dim: 1,
            weight_offset: 0,
        }],
        path_weights: vec![polar_mace_scalar_path_weight(512)],
    };
    let linear_1 = if input_dim == 512 {
        polar_mace_fukui_source_map_linear_rows_from_tensors(
            access, "linear_1", input_rows, 512, 16, 0,
        )?
    } else {
        polar_mace_runtime_block_linear_rows_from_tensors(
            access,
            "fukui_source_map.linear_1",
            input_rows,
            &dynamic_linear_1_plan,
        )?
    };
    let activation_1 =
        polar_mace_fukui_source_map_activation_rows(&linear_1, normalize2mom_constant)?;
    let linear_mid = polar_mace_fukui_source_map_linear_rows_from_tensors(
        access,
        "linear_mid",
        &activation_1,
        16,
        16,
        16,
    )?;
    let activation_mid =
        polar_mace_fukui_source_map_activation_rows(&linear_mid, normalize2mom_constant)?;

    let activation_mid_cotangent = polar_mace_fukui_source_map_linear_rows_vjp_from_tensors(
        access,
        "linear_2",
        output_cotangent,
        &activation_mid,
        16,
        2,
        2,
    )?;
    let linear_mid_cotangent = polar_mace_fukui_source_map_activation_rows_vjp(
        &activation_mid_cotangent,
        &linear_mid,
        normalize2mom_constant,
    )?;
    let activation_1_cotangent = polar_mace_fukui_source_map_linear_rows_vjp_from_tensors(
        access,
        "linear_mid",
        &linear_mid_cotangent,
        &activation_1,
        16,
        16,
        16,
    )?;
    let linear_1_cotangent = polar_mace_fukui_source_map_activation_rows_vjp(
        &activation_1_cotangent,
        &linear_1,
        normalize2mom_constant,
    )?;
    if input_dim == 512 {
        return polar_mace_fukui_source_map_linear_rows_vjp_from_tensors(
            access,
            "linear_1",
            &linear_1_cotangent,
            input_rows,
            512,
            16,
            0,
        );
    }
    let prefix = "fukui_source_map.linear_1";
    let weight = access.f64(
        &format!("{prefix}.weight"),
        &[dynamic_linear_1_plan.weight_len],
    )?;
    let output_mask = access.f64(&format!("{prefix}.output_mask"), &[16])?;
    let bias = access
        .f64(&format!("{prefix}.bias"), &[0])
        .or_else(|_| access.f64(&format!("{prefix}.bias"), &[16]))?;
    polar_mace_e3nn_block_linear_rows_vjp(
        &linear_1_cotangent,
        input_rows,
        MacePolarBlockLinearSpec {
            weight,
            bias,
            output_mask,
            instructions: &dynamic_linear_1_plan.instructions,
            instruction_path_weights: Some(&dynamic_linear_1_plan.path_weights),
            input_dim,
            output_dim: 16,
            name: prefix,
        },
    )
}

#[allow(dead_code)]
fn polar_mace_normalized_field_feature_rows(
    raw_field_rows: &[Vec<f64>],
    half_external_field_rows: &[Vec<f64>],
    field_feature_norms: &[f64],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        "field_features.half_external.rows.len",
        half_external_field_rows.len(),
        raw_field_rows.len(),
    )?;
    require_usize("field_features.norms.len", field_feature_norms.len(), 8)?;
    raw_field_rows
        .iter()
        .zip(half_external_field_rows)
        .enumerate()
        .map(|(row_index, (raw, external))| {
            require_usize(
                &format!("field_features.raw[{row_index}].len"),
                raw.len(),
                8,
            )?;
            require_usize(
                &format!("field_features.half_external[{row_index}].len"),
                external.len(),
                8,
            )?;
            Ok(raw
                .iter()
                .zip(external)
                .zip(field_feature_norms)
                .map(|((raw_value, external_value), norm)| (raw_value + external_value) / norm)
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_normalized_field_feature_rows_vjp(
    output_cotangent: &[Vec<f64>],
    raw_field_rows: &[Vec<f64>],
    half_external_field_rows: &[Vec<f64>],
    field_feature_norms: &[f64],
) -> Result<(MacePolarRows, MacePolarRows), MacePolarError> {
    require_usize(
        "field_features_vjp.output_cotangent.len",
        output_cotangent.len(),
        raw_field_rows.len(),
    )?;
    require_usize(
        "field_features_vjp.half_external.rows.len",
        half_external_field_rows.len(),
        raw_field_rows.len(),
    )?;
    require_usize("field_features_vjp.norms.len", field_feature_norms.len(), 8)?;
    if !field_feature_norms
        .iter()
        .all(|norm| norm.is_finite() && *norm != 0.0)
    {
        return Err(invalid(
            "field_features_vjp.norms",
            "field feature norms must be finite and non-zero",
        ));
    }
    let mut raw_cotangent = polar_mace_zero_rows_like(raw_field_rows);
    let mut external_cotangent = polar_mace_zero_rows_like(half_external_field_rows);
    for (row_index, ((bar_row, raw), external)) in output_cotangent
        .iter()
        .zip(raw_field_rows)
        .zip(half_external_field_rows)
        .enumerate()
    {
        require_usize(
            &format!("field_features_vjp.raw[{row_index}].len"),
            raw.len(),
            8,
        )?;
        require_usize(
            &format!("field_features_vjp.half_external[{row_index}].len"),
            external.len(),
            8,
        )?;
        require_usize(
            &format!("field_features_vjp.output_cotangent[{row_index}].len"),
            bar_row.len(),
            8,
        )?;
        for component in 0..8 {
            let bar = bar_row[component] / field_feature_norms[component];
            raw_cotangent[row_index][component] += bar;
            external_cotangent[row_index][component] += bar;
        }
    }
    Ok((raw_cotangent, external_cotangent))
}

