#[allow(dead_code)]
fn polar_mace_rows_add(
    left_rows: &[Vec<f64>],
    right_rows: &[Vec<f64>],
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{name}.right_rows.len"),
        right_rows.len(),
        left_rows.len(),
    )?;
    left_rows
        .iter()
        .zip(right_rows)
        .enumerate()
        .map(|(row_index, (left, right))| {
            require_usize(
                &format!("{name}.right_rows[{row_index}].len"),
                right.len(),
                left.len(),
            )?;
            Ok(left
                .iter()
                .zip(right)
                .map(|(left_value, right_value)| left_value + right_value)
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_rows_concat(
    left_rows: &[Vec<f64>],
    right_rows: &[Vec<f64>],
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{name}.right_rows.len"),
        right_rows.len(),
        left_rows.len(),
    )?;
    Ok(left_rows
        .iter()
        .zip(right_rows)
        .map(|(left, right)| {
            let mut row = Vec::with_capacity(left.len() + right.len());
            row.extend_from_slice(left);
            row.extend_from_slice(right);
            row
        })
        .collect())
}

#[allow(dead_code)]
fn polar_mace_rows_slice(
    rows: &[Vec<f64>],
    start: usize,
    len: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    rows.iter()
        .enumerate()
        .map(|(row_index, row)| {
            let end = start + len;
            if end > row.len() {
                return Err(invalid(
                    name,
                    format!(
                        "row {row_index} expected at least {end} columns, got {}",
                        row.len()
                    ),
                ));
            }
            Ok(row[start..end].to_vec())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_pbc_descriptor_forward_dynamic_from_cache(
    source_feats: &[Vec<f64>],
    cache: MacePolarPbcDescriptorCacheView<'_>,
    correction_terms: Option<&[Vec<f64>]>,
) -> Result<MacePolarPbcDescriptorRows, MacePolarError> {
    require_usize(
        "pbc_descriptor.source_feats.len",
        source_feats.len(),
        cache.node_count,
    )?;
    require_usize(
        "pbc_descriptor.cosines.len",
        cache.cosines.len(),
        cache.k_count * cache.node_count,
    )?;
    require_usize(
        "pbc_descriptor.sines.len",
        cache.sines.len(),
        cache.k_count * cache.node_count,
    )?;
    require_usize(
        "pbc_descriptor.density_basis_fs.len",
        cache.density_basis_fs.len(),
        cache.k_count * 4 * 2,
    )?;
    require_usize(
        "pbc_descriptor.feature_basis_fs.len",
        cache.feature_basis_fs.len(),
        cache.k_count * 2 * 4 * 2,
    )?;
    require_usize(
        "pbc_descriptor.volume_per_k.len",
        cache.volume_per_k.len(),
        cache.k_count,
    )?;
    require_usize(
        "pbc_descriptor.k_factor_coulomb.len",
        cache.k_factor_coulomb.len(),
        cache.k_count,
    )?;
    require_usize(
        "pbc_descriptor.k_factor_proj.len",
        cache.k_factor_proj.len(),
        cache.k_count,
    )?;
    if let Some(rows) = correction_terms {
        require_usize(
            "pbc_descriptor.correction_terms.len",
            rows.len(),
            cache.node_count,
        )?;
    }
    for (node, row) in source_feats.iter().enumerate() {
        require_usize(
            &format!("pbc_descriptor.source_feats[{node}].len"),
            row.len(),
            4,
        )?;
    }

    let scale = (2.0_f64 * std::f64::consts::PI).powi(3);
    let mut density = vec![0.0_f64; cache.k_count * 2];
    let mut potential = vec![0.0_f64; cache.k_count * 2];
    for k_index in 0..cache.k_count {
        let mut rho_real = 0.0_f64;
        let mut rho_imag = 0.0_f64;
        for m_index in 0..4 {
            let mut coeff_cos = 0.0_f64;
            let mut coeff_sin = 0.0_f64;
            for (node_index, source) in source_feats.iter().enumerate() {
                coeff_cos +=
                    cache.cosines[k_index * cache.node_count + node_index] * source[m_index];
                coeff_sin += cache.sines[k_index * cache.node_count + node_index] * source[m_index];
            }
            let basis_offset = k_index * 8 + m_index * 2;
            let basis_r = cache.density_basis_fs[basis_offset];
            let basis_i = cache.density_basis_fs[basis_offset + 1];
            rho_real += basis_r * coeff_cos + basis_i * coeff_sin;
            rho_imag += basis_i * coeff_cos - basis_r * coeff_sin;
        }
        let density_real = scale * rho_real / cache.volume_per_k[k_index];
        let density_imag = scale * rho_imag / cache.volume_per_k[k_index];
        density[k_index * 2] = density_real;
        density[k_index * 2 + 1] = density_imag;
        potential[k_index * 2] = density_real
            * cache.k_factor_coulomb[k_index]
            * POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT;
        potential[k_index * 2 + 1] = density_imag
            * cache.k_factor_coulomb[k_index]
            * POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT;
    }

    let mut features_si = vec![0.0_f64; cache.node_count * 2 * 4];
    for node_index in 0..cache.node_count {
        for sigma_index in 0..2 {
            for m_index in 0..4 {
                let mut projection = 0.0_f64;
                for k_index in 0..cache.k_count {
                    let basis_offset = (k_index * 2 + sigma_index) * 4 * 2 + m_index * 2;
                    let basis_r = cache.feature_basis_fs[basis_offset];
                    let basis_i = cache.feature_basis_fs[basis_offset + 1];
                    let potential_real = potential[k_index * 2];
                    let potential_imag = potential[k_index * 2 + 1];
                    let a = (potential_real * basis_r + potential_imag * basis_i)
                        * cache.k_factor_proj[k_index];
                    let b = (potential_real * basis_i - potential_imag * basis_r)
                        * cache.k_factor_proj[k_index];
                    projection += a * cache.cosines[k_index * cache.node_count + node_index]
                        + b * cache.sines[k_index * cache.node_count + node_index];
                }
                features_si[(node_index * 2 + sigma_index) * 4 + m_index] =
                    2.0 * projection / scale;
            }
        }
    }

    let mut features_flat_pre_permutation = Vec::with_capacity(cache.node_count);
    let mut features_flat_post_permutation = Vec::with_capacity(cache.node_count);
    let mut self_interaction_terms = Vec::with_capacity(cache.node_count);
    let mut final_rows = Vec::with_capacity(cache.node_count);
    for node_index in 0..cache.node_count {
        let pre = features_si[node_index * 8..node_index * 8 + 8].to_vec();
        let mut post = Vec::with_capacity(8);
        for src_index in POLAR_MACE_DESCRIPTOR_OUTPUT_PERMUTATION {
            post.push(pre[src_index]);
        }
        let mut self_terms = Vec::with_capacity(8);
        for term_index in 0..8 {
            self_terms.push(
                POLAR_MACE_DESCRIPTOR_SELF_INTERACTION_OVERLAP_CONSTANTS[term_index]
                    * source_feats[node_index]
                        [POLAR_MACE_DESCRIPTOR_SELF_INTERACTION_SELECT_INDICES[term_index]],
            );
        }
        let mut final_row = Vec::with_capacity(8);
        for index in 0..8 {
            let correction = if let Some(rows) = correction_terms {
                require_usize(
                    &format!("pbc_descriptor.correction_terms[{node_index}].len"),
                    rows[node_index].len(),
                    8,
                )?;
                rows[node_index][index]
            } else {
                0.0
            };
            final_row.push(post[index] - self_terms[index] + correction);
        }
        features_flat_pre_permutation.push(pre);
        features_flat_post_permutation.push(post);
        self_interaction_terms.push(self_terms);
        final_rows.push(final_row);
    }

    Ok(MacePolarPbcDescriptorRows {
        density,
        potential,
        features_si,
        features_flat_pre_permutation,
        features_flat_post_permutation,
        self_interaction_terms,
        final_rows,
    })
}

#[allow(dead_code)]
fn polar_mace_realspace_descriptor_forward_dynamic_rows(
    source_feats: &[Vec<f64>],
    positions: &[[f64; 3]],
    batch: &[usize],
    total_width_factors: &[f64],
    l0_factors: &[f64],
    l1_factors: &[f64],
    self_interaction_overlap_constants: &[f64],
    self_interaction_select_indices: &[i64],
    offset: f64,
    displacement_vectors: &[[f64; 3]; 3],
    include_self_interaction: bool,
) -> Result<MacePolarRealspaceDescriptorRows, MacePolarError> {
    require_usize(
        "realspace_descriptor.positions.len",
        positions.len(),
        source_feats.len(),
    )?;
    require_usize(
        "realspace_descriptor.batch.len",
        batch.len(),
        source_feats.len(),
    )?;
    let num_radial = total_width_factors.len();
    require_usize(
        "realspace_descriptor.l0_factors.len",
        l0_factors.len(),
        num_radial,
    )?;
    require_usize(
        "realspace_descriptor.l1_factors.len",
        l1_factors.len(),
        num_radial,
    )?;
    let output_dim = 4 * num_radial;
    require_usize(
        "realspace_descriptor.self_interaction_overlap_constants.len",
        self_interaction_overlap_constants.len(),
        output_dim,
    )?;
    require_usize(
        "realspace_descriptor.self_interaction_select_indices.len",
        self_interaction_select_indices.len(),
        output_dim,
    )?;
    if num_radial == 0 {
        return Err(invalid(
            "realspace_descriptor.num_radial",
            "expected at least one radial feature",
        ));
    }
    if !offset.is_finite() || offset == 0.0 {
        return Err(invalid(
            "realspace_descriptor.offset",
            "offset must be finite and non-zero",
        ));
    }
    for (index, vector) in displacement_vectors.iter().enumerate() {
        if !vector.iter().all(|value| value.is_finite()) {
            return Err(invalid(
                "realspace_descriptor.displacement_vectors",
                format!("entry {index} must contain only finite values"),
            ));
        }
    }
    for (index, value) in total_width_factors.iter().enumerate() {
        if !value.is_finite() || *value <= 0.0 {
            return Err(invalid(
                "realspace_descriptor.total_width_factors",
                format!("entry {index} must be finite and positive"),
            ));
        }
    }

    let mut extended_positions = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_charges = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_original = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_batch = Vec::with_capacity(source_feats.len() * 4);
    for (atom, source) in source_feats.iter().enumerate() {
        require_usize(
            &format!("realspace_descriptor.source_feats[{atom}].len"),
            source.len(),
            4,
        )?;
        let position = positions[atom];
        let qx = source[3] / offset;
        let qy = source[1] / offset;
        let qz = source[2] / offset;
        let q0 = source[0] - (qx + qy + qz);
        let expanded = [
            (position, q0),
            (
                [
                    position[0] + displacement_vectors[0][0],
                    position[1] + displacement_vectors[0][1],
                    position[2] + displacement_vectors[0][2],
                ],
                qx,
            ),
            (
                [
                    position[0] + displacement_vectors[1][0],
                    position[1] + displacement_vectors[1][1],
                    position[2] + displacement_vectors[1][2],
                ],
                qy,
            ),
            (
                [
                    position[0] + displacement_vectors[2][0],
                    position[1] + displacement_vectors[2][1],
                    position[2] + displacement_vectors[2][2],
                ],
                qz,
            ),
        ];
        for (extended_position, charge) in expanded {
            extended_positions.push(extended_position);
            extended_charges.push(charge);
            extended_original.push(atom);
            extended_batch.push(batch[atom]);
        }
    }

    let mut edge_sender = Vec::new();
    let mut edge_receiver = Vec::new();
    let mut edge_vectors_sender_minus_receiver = Vec::new();
    let mut distances = Vec::new();
    let mut scalar_features = vec![vec![0.0_f64; num_radial]; extended_positions.len()];
    #[cfg(feature = "parallel")]
    if extended_positions.len() >= 128 && rayon::current_num_threads() > 1 {
        scalar_features
            .par_iter_mut()
            .enumerate()
            .for_each(|(receiver, receiver_features)| {
                for sender in 0..extended_positions.len() {
                    if extended_batch[sender] != extended_batch[receiver] {
                        continue;
                    }
                    if extended_original[sender] == extended_original[receiver] {
                        continue;
                    }
                    let vector = [
                        extended_positions[sender][0] - extended_positions[receiver][0],
                        extended_positions[sender][1] - extended_positions[receiver][1],
                        extended_positions[sender][2] - extended_positions[receiver][2],
                    ];
                    let distance =
                        (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2])
                            .sqrt();
                    for (radial, width) in total_width_factors.iter().enumerate() {
                        let smooth =
                            polar_mace_erf_approx(0.5 * distance / *width) / (distance + 1.0e-6);
                        receiver_features[radial] += extended_charges[sender]
                            * smooth
                            * POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT
                            / (4.0 * std::f64::consts::PI);
                    }
                }
            });
    } else {
        for sender in 0..extended_positions.len() {
            for receiver in 0..extended_positions.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions[sender][0] - extended_positions[receiver][0],
                    extended_positions[sender][1] - extended_positions[receiver][1],
                    extended_positions[sender][2] - extended_positions[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let smooth =
                        polar_mace_erf_approx(0.5 * distance / *width) / (distance + 1.0e-6);
                    scalar_features[receiver][radial] +=
                        extended_charges[sender] * smooth * POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT
                            / (4.0 * std::f64::consts::PI);
                }
                edge_sender.push(sender);
                edge_receiver.push(receiver);
                edge_vectors_sender_minus_receiver.push(vector);
                distances.push(distance);
            }
        }
    }
    #[cfg(not(feature = "parallel"))]
    {
        for sender in 0..extended_positions.len() {
            for receiver in 0..extended_positions.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions[sender][0] - extended_positions[receiver][0],
                    extended_positions[sender][1] - extended_positions[receiver][1],
                    extended_positions[sender][2] - extended_positions[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let smooth =
                        polar_mace_erf_approx(0.5 * distance / *width) / (distance + 1.0e-6);
                    scalar_features[receiver][radial] +=
                        extended_charges[sender] * smooth * POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT
                            / (4.0 * std::f64::consts::PI);
                }
                edge_sender.push(sender);
                edge_receiver.push(receiver);
                edge_vectors_sender_minus_receiver.push(vector);
                distances.push(distance);
            }
        }
    }

    let mut features_without_self = vec![vec![0.0_f64; output_dim]; source_feats.len()];
    for atom in 0..source_feats.len() {
        let base = atom * 4;
        for radial in 0..num_radial {
            features_without_self[atom][radial] =
                l0_factors[radial] * scalar_features[base][radial];
            features_without_self[atom][num_radial + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 2][radial] - scalar_features[base][radial]);
            features_without_self[atom][num_radial + 1 + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 3][radial] - scalar_features[base][radial]);
            features_without_self[atom][num_radial + 2 + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 1][radial] - scalar_features[base][radial]);
        }
    }

    let mut self_interaction_terms = Vec::with_capacity(source_feats.len());
    for (row_index, source) in source_feats.iter().enumerate() {
        let mut row = Vec::with_capacity(output_dim);
        for term_index in 0..output_dim {
            let selected =
                usize::try_from(self_interaction_select_indices[term_index]).map_err(|_| {
                    invalid(
                        "realspace_descriptor.self_interaction_select_indices",
                        format!("row {row_index} term {term_index} has a negative select index"),
                    )
                })?;
            if selected >= source.len() {
                return Err(invalid(
                    "realspace_descriptor.self_interaction_select_indices",
                    format!(
                        "row {row_index} term {term_index} select index {selected} exceeds source width {}",
                        source.len()
                    ),
                ));
            }
            row.push(self_interaction_overlap_constants[term_index] * source[selected]);
        }
        self_interaction_terms.push(row);
    }

    let final_rows = features_without_self
        .iter()
        .zip(&self_interaction_terms)
        .enumerate()
        .map(|(row_index, (features, self_terms))| {
            require_usize(
                &format!("realspace_descriptor.features_without_self[{row_index}].len"),
                features.len(),
                output_dim,
            )?;
            if include_self_interaction {
                Ok(features
                    .iter()
                    .zip(self_terms)
                    .map(|(feature, self_term)| feature + self_term)
                    .collect())
            } else {
                Ok(features.clone())
            }
        })
        .collect::<Result<MacePolarRows, MacePolarError>>()?;

    Ok(MacePolarRealspaceDescriptorRows {
        extended_positions,
        extended_charges,
        edge_sender,
        edge_receiver,
        edge_vectors_sender_minus_receiver,
        distances,
        scalar_features,
        features_without_self,
        self_interaction_terms,
        final_rows,
    })
}

#[allow(dead_code)]
fn polar_mace_realspace_descriptor_forward_dynamic_rows_vjp(
    output_cotangent: &[Vec<f64>],
    source_feats: &[Vec<f64>],
    positions: &[[f64; 3]],
    batch: &[usize],
    total_width_factors: &[f64],
    l0_factors: &[f64],
    l1_factors: &[f64],
    self_interaction_overlap_constants: &[f64],
    self_interaction_select_indices: &[i64],
    offset: f64,
    displacement_vectors: &[[f64; 3]; 3],
    include_self_interaction: bool,
) -> Result<MacePolarRealspaceDescriptorCotangents, MacePolarError> {
    require_usize(
        "realspace_descriptor_vjp.positions.len",
        positions.len(),
        source_feats.len(),
    )?;
    require_usize(
        "realspace_descriptor_vjp.batch.len",
        batch.len(),
        source_feats.len(),
    )?;
    require_usize(
        "realspace_descriptor_vjp.output_cotangent.len",
        output_cotangent.len(),
        source_feats.len(),
    )?;
    let num_radial = total_width_factors.len();
    require_usize(
        "realspace_descriptor_vjp.l0_factors.len",
        l0_factors.len(),
        num_radial,
    )?;
    require_usize(
        "realspace_descriptor_vjp.l1_factors.len",
        l1_factors.len(),
        num_radial,
    )?;
    let output_dim = 4 * num_radial;
    require_usize(
        "realspace_descriptor_vjp.self_interaction_overlap_constants.len",
        self_interaction_overlap_constants.len(),
        output_dim,
    )?;
    require_usize(
        "realspace_descriptor_vjp.self_interaction_select_indices.len",
        self_interaction_select_indices.len(),
        output_dim,
    )?;
    if num_radial == 0 {
        return Err(invalid(
            "realspace_descriptor_vjp.num_radial",
            "expected at least one radial feature",
        ));
    }
    if !offset.is_finite() || offset == 0.0 {
        return Err(invalid(
            "realspace_descriptor_vjp.offset",
            "offset must be finite and non-zero",
        ));
    }
    for (index, vector) in displacement_vectors.iter().enumerate() {
        if !vector.iter().all(|value| value.is_finite()) {
            return Err(invalid(
                "realspace_descriptor_vjp.displacement_vectors",
                format!("entry {index} must contain only finite values"),
            ));
        }
    }
    for (index, value) in total_width_factors.iter().enumerate() {
        if !value.is_finite() || *value <= 0.0 {
            return Err(invalid(
                "realspace_descriptor_vjp.total_width_factors",
                format!("entry {index} must be finite and positive"),
            ));
        }
    }
    if !l0_factors
        .iter()
        .chain(l1_factors)
        .all(|value| value.is_finite())
    {
        return Err(invalid(
            "realspace_descriptor_vjp.factors",
            "l0 and l1 factors must be finite",
        ));
    }

    let mut source_cotangent = polar_mace_zero_rows_like(source_feats);
    let mut extended_positions = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_charges = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_original = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_batch = Vec::with_capacity(source_feats.len() * 4);
    for (atom, source) in source_feats.iter().enumerate() {
        require_usize(
            &format!("realspace_descriptor_vjp.source_feats[{atom}].len"),
            source.len(),
            4,
        )?;
        let position = positions[atom];
        let qx = source[3] / offset;
        let qy = source[1] / offset;
        let qz = source[2] / offset;
        let q0 = source[0] - (qx + qy + qz);
        let expanded = [
            (position, q0),
            (
                [
                    position[0] + displacement_vectors[0][0],
                    position[1] + displacement_vectors[0][1],
                    position[2] + displacement_vectors[0][2],
                ],
                qx,
            ),
            (
                [
                    position[0] + displacement_vectors[1][0],
                    position[1] + displacement_vectors[1][1],
                    position[2] + displacement_vectors[1][2],
                ],
                qy,
            ),
            (
                [
                    position[0] + displacement_vectors[2][0],
                    position[1] + displacement_vectors[2][1],
                    position[2] + displacement_vectors[2][2],
                ],
                qz,
            ),
        ];
        for (extended_position, charge) in expanded {
            extended_positions.push(extended_position);
            extended_charges.push(charge);
            extended_original.push(atom);
            extended_batch.push(batch[atom]);
        }
    }

    let mut scalar_features_cotangent = vec![vec![0.0_f64; num_radial]; extended_positions.len()];
    for (atom, bar_final) in output_cotangent.iter().enumerate() {
        require_usize(
            &format!("realspace_descriptor_vjp.output_cotangent[{atom}].len"),
            bar_final.len(),
            output_dim,
        )?;
        let base = atom * 4;
        for radial in 0..num_radial {
            scalar_features_cotangent[base][radial] += l0_factors[radial] * bar_final[radial];
            let bar_x = bar_final[num_radial + radial * 3];
            let bar_y = bar_final[num_radial + 1 + radial * 3];
            let bar_z = bar_final[num_radial + 2 + radial * 3];
            scalar_features_cotangent[base + 2][radial] += l1_factors[radial] * bar_x;
            scalar_features_cotangent[base][radial] -= l1_factors[radial] * bar_x;
            scalar_features_cotangent[base + 3][radial] += l1_factors[radial] * bar_y;
            scalar_features_cotangent[base][radial] -= l1_factors[radial] * bar_y;
            scalar_features_cotangent[base + 1][radial] += l1_factors[radial] * bar_z;
            scalar_features_cotangent[base][radial] -= l1_factors[radial] * bar_z;
        }
        if include_self_interaction {
            for term_index in 0..output_dim {
                let selected = usize::try_from(self_interaction_select_indices[term_index])
                    .map_err(|_| {
                        invalid(
                            "realspace_descriptor_vjp.self_interaction_select_indices",
                            format!("row {atom} term {term_index} has a negative select index"),
                        )
                    })?;
                if selected >= source_feats[atom].len() {
                    return Err(invalid(
                        "realspace_descriptor_vjp.self_interaction_select_indices",
                        format!(
                            "row {atom} term {term_index} select index {selected} exceeds source width {}",
                            source_feats[atom].len()
                        ),
                    ));
                }
                source_cotangent[atom][selected] +=
                    bar_final[term_index] * self_interaction_overlap_constants[term_index];
            }
        }
    }

    let mut extended_charge_cotangent = vec![0.0_f64; extended_charges.len()];
    let mut extended_position_cotangent = vec![[0.0_f64; 3]; extended_positions.len()];
    let pair_scale = POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT / (4.0 * std::f64::consts::PI);
    #[cfg(feature = "parallel")]
    if extended_positions.len() >= 128 && rayon::current_num_threads() > 1 {
        let node_count = extended_positions.len();
        let chunk_target = (rayon::current_num_threads() * 4).max(1);
        let chunk_size = node_count.div_ceil(chunk_target).max(1);
        let sender_chunks = (0..node_count)
            .step_by(chunk_size)
            .map(|start| (start, (start + chunk_size).min(node_count)))
            .collect::<Vec<_>>();
        let partials = sender_chunks
            .into_par_iter()
            .map(|(start, end)| {
                let mut local_charge_cotangent = vec![0.0_f64; node_count];
                let mut local_position_cotangent = vec![[0.0_f64; 3]; node_count];
                for sender in start..end {
                    for receiver in 0..node_count {
                        if extended_batch[sender] != extended_batch[receiver] {
                            continue;
                        }
                        if extended_original[sender] == extended_original[receiver] {
                            continue;
                        }
                        let vector = [
                            extended_positions[sender][0] - extended_positions[receiver][0],
                            extended_positions[sender][1] - extended_positions[receiver][1],
                            extended_positions[sender][2] - extended_positions[receiver][2],
                        ];
                        let distance =
                            (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2])
                                .sqrt();
                        let mut bar_distance = 0.0_f64;
                        for (radial, width) in total_width_factors.iter().enumerate() {
                            let erf_arg = 0.5 * distance / *width;
                            let erf_value = polar_mace_erf_approx(erf_arg);
                            let denom = distance + 1.0e-6;
                            let smooth = erf_value / denom;
                            let bar_scalar =
                                scalar_features_cotangent[receiver][radial] * pair_scale;
                            local_charge_cotangent[sender] += bar_scalar * smooth;
                            let bar_smooth = bar_scalar * extended_charges[sender];
                            let derf_dd = polar_mace_erf_approx_derivative(erf_arg) * 0.5 / *width;
                            bar_distance +=
                                bar_smooth * (derf_dd / denom - erf_value / (denom * denom));
                        }
                        if distance > 0.0 {
                            for component in 0..3 {
                                let bar_vector = bar_distance * vector[component] / distance;
                                local_position_cotangent[sender][component] += bar_vector;
                                local_position_cotangent[receiver][component] -= bar_vector;
                            }
                        }
                    }
                }
                (local_charge_cotangent, local_position_cotangent)
            })
            .collect::<Vec<_>>();
        for (local_charge_cotangent, local_position_cotangent) in partials {
            for node in 0..node_count {
                extended_charge_cotangent[node] += local_charge_cotangent[node];
                for component in 0..3 {
                    extended_position_cotangent[node][component] +=
                        local_position_cotangent[node][component];
                }
            }
        }
    } else {
        for sender in 0..extended_positions.len() {
            for receiver in 0..extended_positions.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions[sender][0] - extended_positions[receiver][0],
                    extended_positions[sender][1] - extended_positions[receiver][1],
                    extended_positions[sender][2] - extended_positions[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                let mut bar_distance = 0.0_f64;
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let erf_arg = 0.5 * distance / *width;
                    let erf_value = polar_mace_erf_approx(erf_arg);
                    let denom = distance + 1.0e-6;
                    let smooth = erf_value / denom;
                    let bar_scalar = scalar_features_cotangent[receiver][radial] * pair_scale;
                    extended_charge_cotangent[sender] += bar_scalar * smooth;
                    let bar_smooth = bar_scalar * extended_charges[sender];
                    let derf_dd = polar_mace_erf_approx_derivative(erf_arg) * 0.5 / *width;
                    bar_distance += bar_smooth * (derf_dd / denom - erf_value / (denom * denom));
                }
                if distance > 0.0 {
                    for component in 0..3 {
                        let bar_vector = bar_distance * vector[component] / distance;
                        extended_position_cotangent[sender][component] += bar_vector;
                        extended_position_cotangent[receiver][component] -= bar_vector;
                    }
                }
            }
        }
    }
    #[cfg(not(feature = "parallel"))]
    {
        for sender in 0..extended_positions.len() {
            for receiver in 0..extended_positions.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions[sender][0] - extended_positions[receiver][0],
                    extended_positions[sender][1] - extended_positions[receiver][1],
                    extended_positions[sender][2] - extended_positions[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                let mut bar_distance = 0.0_f64;
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let erf_arg = 0.5 * distance / *width;
                    let erf_value = polar_mace_erf_approx(erf_arg);
                    let denom = distance + 1.0e-6;
                    let smooth = erf_value / denom;
                    let bar_scalar = scalar_features_cotangent[receiver][radial] * pair_scale;
                    extended_charge_cotangent[sender] += bar_scalar * smooth;
                    let bar_smooth = bar_scalar * extended_charges[sender];
                    let derf_dd = polar_mace_erf_approx_derivative(erf_arg) * 0.5 / *width;
                    bar_distance += bar_smooth * (derf_dd / denom - erf_value / (denom * denom));
                }
                if distance > 0.0 {
                    for component in 0..3 {
                        let bar_vector = bar_distance * vector[component] / distance;
                        extended_position_cotangent[sender][component] += bar_vector;
                        extended_position_cotangent[receiver][component] -= bar_vector;
                    }
                }
            }
        }
    }

    let mut position_cotangents = MacePolarPositionCotangents::zeros(positions.len());
    for atom in 0..source_feats.len() {
        let base = atom * 4;
        source_cotangent[atom][0] += extended_charge_cotangent[base];
        source_cotangent[atom][3] +=
            (extended_charge_cotangent[base + 1] - extended_charge_cotangent[base]) / offset;
        source_cotangent[atom][1] +=
            (extended_charge_cotangent[base + 2] - extended_charge_cotangent[base]) / offset;
        source_cotangent[atom][2] +=
            (extended_charge_cotangent[base + 3] - extended_charge_cotangent[base]) / offset;
        let mut atom_position_cotangent = [0.0_f64; 3];
        for duplicate in 0..4 {
            for component in 0..3 {
                atom_position_cotangent[component] +=
                    extended_position_cotangent[base + duplicate][component];
            }
        }
        position_cotangents.add_node(atom, atom_position_cotangent)?;
    }
    Ok(MacePolarRealspaceDescriptorCotangents {
        source_feats: source_cotangent,
        positions: position_cotangents,
    })
}

#[allow(dead_code)]
fn polar_mace_realspace_descriptor_forward_dynamic_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    source_feats: &[Vec<f64>],
    positions: &[[f64; 3]],
    batch: &[usize],
    include_self_interaction: bool,
) -> Result<MacePolarRealspaceDescriptorRows, MacePolarError> {
    let total_width_factors = access.f64(
        "electric_potential_descriptor.realspace_features.total_width_factors",
        &[2],
    )?;
    let l0_factors = access.f64(
        "electric_potential_descriptor.realspace_features.l0_factors",
        &[2],
    )?;
    let l1_factors = access.f64(
        "electric_potential_descriptor.realspace_features.l1_factors",
        &[2],
    )?;
    let displacement_x = access.f64("electric_potential_descriptor.realspace_features.x", &[3])?;
    let displacement_y = access.f64("electric_potential_descriptor.realspace_features.y", &[3])?;
    let displacement_z = access.f64("electric_potential_descriptor.realspace_features.z", &[3])?;
    // Upstream stores these finite-difference displacement buffers as artifact
    // tensors; they may be f32-rounded before model.double(). The charge
    // denominator remains the scalar offset used by graph_longrange.
    let displacement_vectors = [
        [displacement_x[0], displacement_x[1], displacement_x[2]],
        [displacement_y[0], displacement_y[1], displacement_y[2]],
        [displacement_z[0], displacement_z[1], displacement_z[2]],
    ];
    let self_interaction_overlap_constants = access
        .f64(
            "electric_potential_descriptor.realspace_features.self_interaction.overlap_constants",
            &[8],
        )
        .or_else(|_| {
            access.f64(
                "electric_potential_descriptor.self_interaction_terms.overlap_constants",
                &[8],
            )
        })?;
    let self_interaction_select_indices = access
        .i64(
            "electric_potential_descriptor.realspace_features.self_interaction.select_indices",
            &[8],
        )
        .or_else(|_| {
            access.i64(
                "electric_potential_descriptor.self_interaction_terms.select_indices",
                &[8],
            )
        })?;
    polar_mace_realspace_descriptor_forward_dynamic_rows(
        source_feats,
        positions,
        batch,
        total_width_factors,
        l0_factors,
        l1_factors,
        self_interaction_overlap_constants,
        self_interaction_select_indices,
        0.1,
        &displacement_vectors,
        include_self_interaction,
    )
}

#[allow(dead_code)]
fn polar_mace_realspace_descriptor_forward_dynamic_rows_vjp_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    output_cotangent: &[Vec<f64>],
    source_feats: &[Vec<f64>],
    positions: &[[f64; 3]],
    batch: &[usize],
    include_self_interaction: bool,
) -> Result<MacePolarRealspaceDescriptorCotangents, MacePolarError> {
    let total_width_factors = access.f64(
        "electric_potential_descriptor.realspace_features.total_width_factors",
        &[2],
    )?;
    let l0_factors = access.f64(
        "electric_potential_descriptor.realspace_features.l0_factors",
        &[2],
    )?;
    let l1_factors = access.f64(
        "electric_potential_descriptor.realspace_features.l1_factors",
        &[2],
    )?;
    let displacement_x = access.f64("electric_potential_descriptor.realspace_features.x", &[3])?;
    let displacement_y = access.f64("electric_potential_descriptor.realspace_features.y", &[3])?;
    let displacement_z = access.f64("electric_potential_descriptor.realspace_features.z", &[3])?;
    // Match the artifact displacement buffers used to build upstream duplicate
    // positions; the scalar offset is still the charge finite-difference
    // denominator.
    let displacement_vectors = [
        [displacement_x[0], displacement_x[1], displacement_x[2]],
        [displacement_y[0], displacement_y[1], displacement_y[2]],
        [displacement_z[0], displacement_z[1], displacement_z[2]],
    ];
    let self_interaction_overlap_constants = access
        .f64(
            "electric_potential_descriptor.realspace_features.self_interaction.overlap_constants",
            &[8],
        )
        .or_else(|_| {
            access.f64(
                "electric_potential_descriptor.self_interaction_terms.overlap_constants",
                &[8],
            )
        })?;
    let self_interaction_select_indices = access
        .i64(
            "electric_potential_descriptor.realspace_features.self_interaction.select_indices",
            &[8],
        )
        .or_else(|_| {
            access.i64(
                "electric_potential_descriptor.self_interaction_terms.select_indices",
                &[8],
            )
        })?;
    polar_mace_realspace_descriptor_forward_dynamic_rows_vjp(
        output_cotangent,
        source_feats,
        positions,
        batch,
        total_width_factors,
        l0_factors,
        l1_factors,
        self_interaction_overlap_constants,
        self_interaction_select_indices,
        0.1,
        &displacement_vectors,
        include_self_interaction,
    )
}

