#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_realspace_descriptor_forward_dynamic_rows_f32(
    source_feats: &[Vec<f64>],
    positions: &[[f64; 3]],
    batch: &[usize],
    total_width_factors: &[f32],
    l0_factors: &[f32],
    l1_factors: &[f32],
    self_interaction_overlap_constants: &[f32],
    self_interaction_select_indices: &[i64],
    offset: f32,
    displacement_vectors: &[[f32; 3]; 3],
    include_self_interaction: bool,
) -> Result<MacePolarRealspaceDescriptorRows, MacePolarError> {
    require_usize(
        "realspace_descriptor_f32.positions.len",
        positions.len(),
        source_feats.len(),
    )?;
    require_usize(
        "realspace_descriptor_f32.batch.len",
        batch.len(),
        source_feats.len(),
    )?;
    let num_radial = total_width_factors.len();
    require_usize(
        "realspace_descriptor_f32.l0_factors.len",
        l0_factors.len(),
        num_radial,
    )?;
    require_usize(
        "realspace_descriptor_f32.l1_factors.len",
        l1_factors.len(),
        num_radial,
    )?;
    let output_dim = 4 * num_radial;
    require_usize(
        "realspace_descriptor_f32.self_interaction_overlap_constants.len",
        self_interaction_overlap_constants.len(),
        output_dim,
    )?;
    require_usize(
        "realspace_descriptor_f32.self_interaction_select_indices.len",
        self_interaction_select_indices.len(),
        output_dim,
    )?;
    if num_radial == 0 {
        return Err(invalid(
            "realspace_descriptor_f32.num_radial",
            "expected at least one radial feature",
        ));
    }
    if !offset.is_finite() || offset == 0.0 {
        return Err(invalid(
            "realspace_descriptor_f32.offset",
            "offset must be finite and non-zero",
        ));
    }
    if !total_width_factors
        .iter()
        .all(|value| value.is_finite() && *value > 0.0)
    {
        return Err(invalid(
            "realspace_descriptor_f32.total_width_factors",
            "all entries must be finite and positive",
        ));
    }
    if !l0_factors
        .iter()
        .chain(l1_factors)
        .chain(self_interaction_overlap_constants)
        .all(|value| value.is_finite())
    {
        return Err(invalid(
            "realspace_descriptor_f32.factors",
            "descriptor factors must be finite",
        ));
    }
    for (index, vector) in displacement_vectors.iter().enumerate() {
        if !vector.iter().all(|value| value.is_finite()) {
            return Err(invalid(
                "realspace_descriptor_f32.displacement_vectors",
                format!("entry {index} must contain only finite values"),
            ));
        }
    }

    let mut extended_positions_f32 = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_charges_f32 = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_original = Vec::with_capacity(source_feats.len() * 4);
    let mut extended_batch = Vec::with_capacity(source_feats.len() * 4);
    for (atom, source) in source_feats.iter().enumerate() {
        require_usize(
            &format!("realspace_descriptor_f32.source_feats[{atom}].len"),
            source.len(),
            4,
        )?;
        let position = [
            positions[atom][0] as f32,
            positions[atom][1] as f32,
            positions[atom][2] as f32,
        ];
        let qx = source[3] as f32 / offset;
        let qy = source[1] as f32 / offset;
        let qz = source[2] as f32 / offset;
        let q0 = source[0] as f32 - (qx + qy + qz);
        let expanded = [
            (position, q0),
            (
                [
                    position[0] + displacement_vectors[0][0],
                    position[1] + displacement_vectors[0][1],
                    position[2] + displacement_vectors[0][2],
                ],
                qx,
            ),
            (
                [
                    position[0] + displacement_vectors[1][0],
                    position[1] + displacement_vectors[1][1],
                    position[2] + displacement_vectors[1][2],
                ],
                qy,
            ),
            (
                [
                    position[0] + displacement_vectors[2][0],
                    position[1] + displacement_vectors[2][1],
                    position[2] + displacement_vectors[2][2],
                ],
                qz,
            ),
        ];
        for (extended_position, charge) in expanded {
            extended_positions_f32.push(extended_position);
            extended_charges_f32.push(charge);
            extended_original.push(atom);
            extended_batch.push(batch[atom]);
        }
    }

    let mut edge_sender = Vec::new();
    let mut edge_receiver = Vec::new();
    let mut edge_vectors_sender_minus_receiver = Vec::new();
    let mut distances = Vec::new();
    let mut scalar_features = vec![vec![0.0_f32; num_radial]; extended_positions_f32.len()];
    let pair_scale =
        (POLAR_MACE_ELECTROSTATIC_FIELD_CONSTANT as f32) / (4.0 * std::f32::consts::PI);
    #[cfg(feature = "parallel")]
    if extended_positions_f32.len() >= 128 && rayon::current_num_threads() > 1 {
        scalar_features
            .par_iter_mut()
            .enumerate()
            .for_each(|(receiver, receiver_features)| {
                for sender in 0..extended_positions_f32.len() {
                    if extended_batch[sender] != extended_batch[receiver] {
                        continue;
                    }
                    if extended_original[sender] == extended_original[receiver] {
                        continue;
                    }
                    let vector = [
                        extended_positions_f32[sender][0] - extended_positions_f32[receiver][0],
                        extended_positions_f32[sender][1] - extended_positions_f32[receiver][1],
                        extended_positions_f32[sender][2] - extended_positions_f32[receiver][2],
                    ];
                    let distance =
                        (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2])
                            .sqrt();
                    for (radial, width) in total_width_factors.iter().enumerate() {
                        let smooth = polar_mace_erf_approx_f32(0.5 * distance / *width)
                            / (distance + 1.0e-6);
                        receiver_features[radial] +=
                            extended_charges_f32[sender] * smooth * pair_scale;
                    }
                }
            });
    } else {
        for sender in 0..extended_positions_f32.len() {
            for receiver in 0..extended_positions_f32.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions_f32[sender][0] - extended_positions_f32[receiver][0],
                    extended_positions_f32[sender][1] - extended_positions_f32[receiver][1],
                    extended_positions_f32[sender][2] - extended_positions_f32[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let smooth =
                        polar_mace_erf_approx_f32(0.5 * distance / *width) / (distance + 1.0e-6);
                    scalar_features[receiver][radial] +=
                        extended_charges_f32[sender] * smooth * pair_scale;
                }
                edge_sender.push(sender);
                edge_receiver.push(receiver);
                edge_vectors_sender_minus_receiver.push([
                    vector[0] as f64,
                    vector[1] as f64,
                    vector[2] as f64,
                ]);
                distances.push(distance as f64);
            }
        }
    }
    #[cfg(not(feature = "parallel"))]
    {
        for sender in 0..extended_positions_f32.len() {
            for receiver in 0..extended_positions_f32.len() {
                if extended_batch[sender] != extended_batch[receiver] {
                    continue;
                }
                if extended_original[sender] == extended_original[receiver] {
                    continue;
                }
                let vector = [
                    extended_positions_f32[sender][0] - extended_positions_f32[receiver][0],
                    extended_positions_f32[sender][1] - extended_positions_f32[receiver][1],
                    extended_positions_f32[sender][2] - extended_positions_f32[receiver][2],
                ];
                let distance =
                    (vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]).sqrt();
                for (radial, width) in total_width_factors.iter().enumerate() {
                    let smooth =
                        polar_mace_erf_approx_f32(0.5 * distance / *width) / (distance + 1.0e-6);
                    scalar_features[receiver][radial] +=
                        extended_charges_f32[sender] * smooth * pair_scale;
                }
                edge_sender.push(sender);
                edge_receiver.push(receiver);
                edge_vectors_sender_minus_receiver.push([
                    vector[0] as f64,
                    vector[1] as f64,
                    vector[2] as f64,
                ]);
                distances.push(distance as f64);
            }
        }
    }

    let mut features_without_self_f32 = vec![vec![0.0_f32; output_dim]; source_feats.len()];
    for atom in 0..source_feats.len() {
        let base = atom * 4;
        for radial in 0..num_radial {
            features_without_self_f32[atom][radial] =
                l0_factors[radial] * scalar_features[base][radial];
            features_without_self_f32[atom][num_radial + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 2][radial] - scalar_features[base][radial]);
            features_without_self_f32[atom][num_radial + 1 + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 3][radial] - scalar_features[base][radial]);
            features_without_self_f32[atom][num_radial + 2 + radial * 3] = l1_factors[radial]
                * (scalar_features[base + 1][radial] - scalar_features[base][radial]);
        }
    }

    let mut self_interaction_terms_f32 = Vec::with_capacity(source_feats.len());
    for (row_index, source) in source_feats.iter().enumerate() {
        let mut row = Vec::with_capacity(output_dim);
        for term_index in 0..output_dim {
            let selected =
                usize::try_from(self_interaction_select_indices[term_index]).map_err(|_| {
                    invalid(
                        "realspace_descriptor_f32.self_interaction_select_indices",
                        format!("row {row_index} term {term_index} has a negative select index"),
                    )
                })?;
            if selected >= source.len() {
                return Err(invalid(
                    "realspace_descriptor_f32.self_interaction_select_indices",
                    format!(
                        "row {row_index} term {term_index} select index {selected} exceeds source width {}",
                        source.len()
                    ),
                ));
            }
            row.push(self_interaction_overlap_constants[term_index] * source[selected] as f32);
        }
        self_interaction_terms_f32.push(row);
    }

    let mut final_rows_f32 = Vec::with_capacity(source_feats.len());
    for row_index in 0..source_feats.len() {
        require_usize(
            &format!("realspace_descriptor_f32.features_without_self[{row_index}].len"),
            features_without_self_f32[row_index].len(),
            output_dim,
        )?;
        let row = if include_self_interaction {
            features_without_self_f32[row_index]
                .iter()
                .zip(&self_interaction_terms_f32[row_index])
                .map(|(feature, self_term)| feature + self_term)
                .collect()
        } else {
            features_without_self_f32[row_index].clone()
        };
        final_rows_f32.push(row);
    }

    Ok(MacePolarRealspaceDescriptorRows {
        extended_positions: extended_positions_f32
            .iter()
            .map(|position| [position[0] as f64, position[1] as f64, position[2] as f64])
            .collect(),
        extended_charges: extended_charges_f32
            .iter()
            .map(|charge| *charge as f64)
            .collect(),
        edge_sender,
        edge_receiver,
        edge_vectors_sender_minus_receiver,
        distances,
        scalar_features: polar_mace_rows_to_f64(&scalar_features),
        features_without_self: polar_mace_rows_to_f64(&features_without_self_f32),
        self_interaction_terms: polar_mace_rows_to_f64(&self_interaction_terms_f32),
        final_rows: polar_mace_rows_to_f64(&final_rows_f32),
    })
}

