#[allow(dead_code)]
fn polar_mace_expand_compact_bias(
    compact_bias: &[f64],
    output_dim: usize,
    scalar_blocks: &[(usize, usize)],
    name: &str,
) -> Result<Vec<f64>, MacePolarError> {
    let expected_len = scalar_blocks.iter().map(|(_, len)| *len).sum::<usize>();
    if compact_bias.is_empty() {
        return Ok(vec![0.0; output_dim]);
    }
    require_usize(
        &format!("{name}.compact_bias.len"),
        compact_bias.len(),
        expected_len,
    )?;
    let mut expanded = vec![0.0_f64; output_dim];
    let mut compact_offset = 0_usize;
    for (start, len) in scalar_blocks {
        let end = *start + *len;
        if end > output_dim {
            return Err(invalid(
                name,
                format!("bias block end {end} exceeds output_dim {output_dim}"),
            ));
        }
        expanded[*start..end].copy_from_slice(&compact_bias[compact_offset..compact_offset + *len]);
        compact_offset += *len;
    }
    Ok(expanded)
}

fn polar_mace_field_map_readout_linear_1_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    readout_prefix: &str,
    input_rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    let prefix = format!("{readout_prefix}.linear_1");
    let input_dim = input_rows.first().map_or(512, Vec::len);
    let mut instructions = vec![MacePolarBlockLinearInstruction {
        input_start: 0,
        output_start: 0,
        input_mul: 512,
        output_mul: 64,
        irrep_dim: 1,
        weight_offset: 0,
    }];
    if input_dim >= 2_048 {
        instructions.push(MacePolarBlockLinearInstruction {
            input_start: 512,
            output_start: 64,
            input_mul: 512,
            output_mul: 32,
            irrep_dim: 3,
            weight_offset: 32_768,
        });
    }
    polar_mace_field_map_block_linear_rows_from_tensors(
        access,
        &prefix,
        input_rows,
        input_dim,
        160,
        if input_dim >= 2_048 { 49_152 } else { 32_768 },
        &instructions,
        None,
    )
}

