#[allow(dead_code)]
fn polar_mace_field_map_readout_gate_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    readout_prefix: &str,
    input_rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    let mul_output_mask = access.f64(
        &format!("{readout_prefix}.equivariant_nonlin.mul.output_mask"),
        &[96],
    )?;
    let mul_weight = access.f64(
        &format!("{readout_prefix}.equivariant_nonlin.mul.weight"),
        &[0],
    )?;
    if !mul_weight.is_empty() {
        return Err(invalid(
            "field_dependent_charge_map.readout_gate",
            "expected empty gate mul weight tensor",
        ));
    }
    input_rows
        .iter()
        .enumerate()
        .map(|(row_index, input)| {
            require_usize(
                &format!("{readout_prefix}.gate.input_rows[{row_index}].len"),
                input.len(),
                160,
            )?;
            let mut output = Vec::with_capacity(128);
            for value in &input[0..32] {
                output.push(
                    POLAR_MACE_READOUT_SCALAR_ACTIVATION_NORM * (value / (1.0 + (-value).exp())),
                );
            }
            let gate_activation = input[32..64]
                .iter()
                .map(|value| POLAR_MACE_READOUT_GATE_ACTIVATION_NORM / (1.0 + (-value).exp()))
                .collect::<Vec<_>>();
            for gate_index in 0..32 {
                for component in 0..3 {
                    let value = input[64 + gate_index * 3 + component];
                    output.push(
                        value
                            * gate_activation[gate_index]
                            * mul_output_mask[gate_index * 3 + component],
                    );
                }
            }
            Ok(output)
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_field_map_readout_gate_rows_vjp_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    readout_prefix: &str,
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    let mul_output_mask = access.f64(
        &format!("{readout_prefix}.equivariant_nonlin.mul.output_mask"),
        &[96],
    )?;
    let mul_weight = access.f64(
        &format!("{readout_prefix}.equivariant_nonlin.mul.weight"),
        &[0],
    )?;
    if !mul_weight.is_empty() {
        return Err(invalid(
            "field_dependent_charge_map.readout_gate_vjp",
            "expected empty gate mul weight tensor",
        ));
    }
    require_usize(
        &format!("{readout_prefix}.gate_vjp.output_cotangent.len"),
        output_cotangent.len(),
        input_rows.len(),
    )?;
    let mut input_cotangent = polar_mace_zero_rows_like(input_rows);
    for (row_index, (input, bar_output)) in input_rows.iter().zip(output_cotangent).enumerate() {
        require_usize(
            &format!("{readout_prefix}.gate_vjp.input_rows[{row_index}].len"),
            input.len(),
            160,
        )?;
        require_usize(
            &format!("{readout_prefix}.gate_vjp.output_cotangent[{row_index}].len"),
            bar_output.len(),
            128,
        )?;
        for scalar_index in 0..32 {
            let value = input[scalar_index];
            let sigmoid = 1.0 / (1.0 + (-value).exp());
            input_cotangent[row_index][scalar_index] += bar_output[scalar_index]
                * POLAR_MACE_READOUT_SCALAR_ACTIVATION_NORM
                * (sigmoid + value * sigmoid * (1.0 - sigmoid));
        }
        let mut gate_activation = [0.0_f64; 32];
        let mut gate_activation_cotangent = [0.0_f64; 32];
        for gate_index in 0..32 {
            let value = input[32 + gate_index];
            gate_activation[gate_index] =
                POLAR_MACE_READOUT_GATE_ACTIVATION_NORM / (1.0 + (-value).exp());
        }
        for gate_index in 0..32 {
            for component in 0..3 {
                let vector_index = 64 + gate_index * 3 + component;
                let output_index = 32 + gate_index * 3 + component;
                let mask = mul_output_mask[gate_index * 3 + component];
                let scale = mask;
                let bar = bar_output[output_index];
                input_cotangent[row_index][vector_index] +=
                    bar * gate_activation[gate_index] * scale;
                gate_activation_cotangent[gate_index] += bar * input[vector_index] * scale;
            }
        }
        for gate_index in 0..32 {
            let value = input[32 + gate_index];
            let sigmoid = 1.0 / (1.0 + (-value).exp());
            input_cotangent[row_index][32 + gate_index] += gate_activation_cotangent[gate_index]
                * POLAR_MACE_READOUT_GATE_ACTIVATION_NORM
                * sigmoid
                * (1.0 - sigmoid);
        }
    }
    Ok(input_cotangent)
}

