fn polar_mace_local_electron_energy_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    node_feats: &[Vec<f64>],
    field_feats: &[Vec<f64>],
    charges_0: &[Vec<f64>],
    charges_induced: &[Vec<f64>],
) -> Result<MacePolarLocalElectronEnergyRows, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let mut stage_start = trace_timings.then(Instant::now);
    let q_in = polar_mace_rows_add(charges_induced, charges_0, "local_electron_energy.q_in")?;
    let feature_dim = node_feats.first().map_or(512, Vec::len);
    let q_up = polar_mace_local_electron_linear_up_q_rows_from_tensors(access, &q_in, feature_dim)?;
    let v_up =
        polar_mace_local_electron_linear_up_v_rows_from_tensors(access, field_feats, feature_dim)?;
    mace_polar_trace_stage("local_electron.forward.linear_up", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let dot_products_q = polar_mace_sparse_uvu_scalar_rows_from_tensors(
        access,
        "local_electron_energy.dot_products_q",
        node_feats,
        &q_up,
        512,
    )?;
    let dot_products_v = polar_mace_sparse_uvu_scalar_rows_from_tensors(
        access,
        "local_electron_energy.dot_products_v",
        node_feats,
        &v_up,
        512,
    )?;
    let invar_feats = polar_mace_rows_concat(
        &dot_products_q,
        &dot_products_v,
        "local_electron_energy.invar_feats",
    )?;
    mace_polar_trace_stage("local_electron.forward.sparse_uvu", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let mlp_prefix = "local_electron_energy.mlp.net";
    let z0 = polar_mace_torch_linear_rows(
        &invar_feats,
        access.f64(&format!("{mlp_prefix}.0.weight"), &[128, 1_024])?,
        access.f64(&format!("{mlp_prefix}.0.bias"), &[128])?,
        1_024,
        128,
        &format!("{mlp_prefix}.0"),
    )?;
    let ln1 = polar_mace_layer_norm_rows(
        &z0,
        access.f64(&format!("{mlp_prefix}.1.weight"), &[128])?,
        access.f64(&format!("{mlp_prefix}.1.bias"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.1"),
    )?;
    let a1 = polar_mace_silu_rows(&ln1);
    let z3 = polar_mace_torch_linear_rows(
        &a1,
        access.f64(&format!("{mlp_prefix}.3.weight"), &[128, 128])?,
        access.f64(&format!("{mlp_prefix}.3.bias"), &[128])?,
        128,
        128,
        &format!("{mlp_prefix}.3"),
    )?;
    let ln4 = polar_mace_layer_norm_rows(
        &z3,
        access.f64(&format!("{mlp_prefix}.4.weight"), &[128])?,
        access.f64(&format!("{mlp_prefix}.4.bias"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.4"),
    )?;
    let a4 = polar_mace_silu_rows(&ln4);
    let z6 = polar_mace_torch_linear_rows(
        &a4,
        access.f64(&format!("{mlp_prefix}.6.weight"), &[128, 128])?,
        access.f64(&format!("{mlp_prefix}.6.bias"), &[128])?,
        128,
        128,
        &format!("{mlp_prefix}.6"),
    )?;
    let ln7 = polar_mace_layer_norm_rows(
        &z6,
        access.f64(&format!("{mlp_prefix}.7.weight"), &[128])?,
        access.f64(&format!("{mlp_prefix}.7.bias"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.7"),
    )?;
    let a7 = polar_mace_silu_rows(&ln7);
    let output_rows = polar_mace_torch_linear_rows(
        &a7,
        access.f64(&format!("{mlp_prefix}.9.weight"), &[1, 128])?,
        access.f64(&format!("{mlp_prefix}.9.bias"), &[1])?,
        128,
        1,
        &format!("{mlp_prefix}.9"),
    )?;
    let local_q_e = output_rows
        .iter()
        .enumerate()
        .map(|(row_index, row)| {
            require_usize(
                &format!("local_electron_energy.output[{row_index}].len"),
                row.len(),
                1,
            )?;
            Ok(row[0])
        })
        .collect::<Result<Vec<_>, MacePolarError>>()?;
    let electron_energy = local_q_e.iter().sum();
    mace_polar_trace_stage("local_electron.forward.mlp", stage_start);
    Ok(MacePolarLocalElectronEnergyRows {
        q_in,
        q_up,
        v_up,
        dot_products_q,
        dot_products_v,
        invar_feats,
        z0,
        ln1,
        a1,
        z3,
        ln4,
        a4,
        z6,
        ln7,
        a7,
        local_q_e,
        electron_energy,
    })
}

#[allow(dead_code)]
fn polar_mace_local_electron_energy_rows_vjp_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    retained: &MacePolarLocalElectronEnergyRows,
    electron_energy_cotangent: f64,
    node_feats: &[Vec<f64>],
    field_feats: &[Vec<f64>],
    _charges_0: &[Vec<f64>],
    _charges_induced: &[Vec<f64>],
) -> Result<MacePolarLocalElectronEnergyCotangents, MacePolarError> {
    if !electron_energy_cotangent.is_finite() {
        return Err(invalid(
            "local_electron_energy_vjp",
            "electron energy cotangent must be finite",
        ));
    }
    let trace_timings = mace_polar_trace_timings_enabled();
    let mut stage_start = trace_timings.then(Instant::now);
    let q_in = &retained.q_in;
    let feature_dim = node_feats.first().map_or(512, Vec::len);
    let q_up = &retained.q_up;
    let v_up = &retained.v_up;
    mace_polar_trace_stage("local_electron.vjp.recompute_linear_up", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let dot_products_q = &retained.dot_products_q;
    let dot_products_v = &retained.dot_products_v;
    mace_polar_trace_stage("local_electron.vjp.recompute_sparse_uvu", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let mlp_prefix = "local_electron_energy.mlp.net";
    let z0 = &retained.z0;
    let ln1 = &retained.ln1;
    let z3 = &retained.z3;
    let ln4 = &retained.ln4;
    let z6 = &retained.z6;
    let ln7 = &retained.ln7;
    let a7 = &retained.a7;
    mace_polar_trace_stage("local_electron.vjp.recompute_mlp", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let bar_output = vec![vec![electron_energy_cotangent]; a7.len()];
    let bar_a7 = polar_mace_torch_linear_rows_vjp(
        &bar_output,
        access.f64(&format!("{mlp_prefix}.9.weight"), &[1, 128])?,
        128,
        1,
        &format!("{mlp_prefix}.9"),
    )?;
    let bar_ln7 = polar_mace_silu_rows_vjp(&bar_a7, ln7, "local_electron_energy_vjp.silu7")?;
    let bar_z6 = polar_mace_layer_norm_rows_vjp(
        &bar_ln7,
        z6,
        access.f64(&format!("{mlp_prefix}.7.weight"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.7"),
    )?;
    let bar_a4 = polar_mace_torch_linear_rows_vjp(
        &bar_z6,
        access.f64(&format!("{mlp_prefix}.6.weight"), &[128, 128])?,
        128,
        128,
        &format!("{mlp_prefix}.6"),
    )?;
    let bar_ln4 = polar_mace_silu_rows_vjp(&bar_a4, ln4, "local_electron_energy_vjp.silu4")?;
    let bar_z3 = polar_mace_layer_norm_rows_vjp(
        &bar_ln4,
        z3,
        access.f64(&format!("{mlp_prefix}.4.weight"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.4"),
    )?;
    let bar_a1 = polar_mace_torch_linear_rows_vjp(
        &bar_z3,
        access.f64(&format!("{mlp_prefix}.3.weight"), &[128, 128])?,
        128,
        128,
        &format!("{mlp_prefix}.3"),
    )?;
    let bar_ln1 = polar_mace_silu_rows_vjp(&bar_a1, ln1, "local_electron_energy_vjp.silu1")?;
    let bar_z0 = polar_mace_layer_norm_rows_vjp(
        &bar_ln1,
        z0,
        access.f64(&format!("{mlp_prefix}.1.weight"), &[128])?,
        1.0e-5,
        128,
        &format!("{mlp_prefix}.1"),
    )?;
    let bar_invar_feats = polar_mace_torch_linear_rows_vjp(
        &bar_z0,
        access.f64(&format!("{mlp_prefix}.0.weight"), &[128, 1_024])?,
        1_024,
        128,
        &format!("{mlp_prefix}.0"),
    )?;
    let (bar_dot_products_q, bar_dot_products_v) = polar_mace_rows_concat_vjp(
        &bar_invar_feats,
        dot_products_q,
        dot_products_v,
        "local_electron_energy_vjp.invar_feats",
    )?;
    mace_polar_trace_stage("local_electron.vjp.mlp_backprop", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let (mut node_cotangent, bar_q_up) = polar_mace_sparse_uvu_scalar_rows_vjp_from_tensors(
        access,
        "local_electron_energy.dot_products_q",
        &bar_dot_products_q,
        node_feats,
        q_up,
        512,
    )?;
    let (node_from_v, bar_v_up) = polar_mace_sparse_uvu_scalar_rows_vjp_from_tensors(
        access,
        "local_electron_energy.dot_products_v",
        &bar_dot_products_v,
        node_feats,
        v_up,
        512,
    )?;
    polar_mace_add_rows_in_place(
        &mut node_cotangent,
        &node_from_v,
        "local_electron_energy_vjp.node_feats",
    )?;
    mace_polar_trace_stage("local_electron.vjp.sparse_uvu_backprop", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let mut q_in_instructions = vec![MacePolarBlockLinearInstruction {
        input_start: 0,
        output_start: 0,
        input_mul: 1,
        output_mul: 512,
        irrep_dim: 1,
        weight_offset: 0,
    }];
    let q_in_weight_len = if feature_dim >= 2_048 {
        q_in_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 1,
            output_start: 512,
            input_mul: 1,
            output_mul: 512,
            irrep_dim: 3,
            weight_offset: 512,
        });
        q_in_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 4,
            output_start: 0,
            input_mul: 1,
            output_mul: 512,
            irrep_dim: 1,
            weight_offset: 1_024,
        });
        q_in_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 5,
            output_start: 512,
            input_mul: 1,
            output_mul: 512,
            irrep_dim: 3,
            weight_offset: 1_536,
        });
        2_048
    } else {
        q_in_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 4,
            output_start: 0,
            input_mul: 1,
            output_mul: 512,
            irrep_dim: 1,
            weight_offset: 512,
        });
        1_024
    };
    let q_in_path_weights = vec![std::f64::consts::FRAC_1_SQRT_2; q_in_instructions.len()];
    let q_in_cotangent = polar_mace_field_map_block_linear_rows_vjp_from_tensors(
        access,
        "local_electron_energy.linear_up_q",
        &bar_q_up,
        q_in,
        8,
        feature_dim,
        q_in_weight_len,
        &q_in_instructions,
        Some(&q_in_path_weights),
    )?;
    let mut field_instructions = vec![MacePolarBlockLinearInstruction {
        input_start: 0,
        output_start: 0,
        input_mul: 2,
        output_mul: 512,
        irrep_dim: 1,
        weight_offset: 0,
    }];
    let field_weight_len = if feature_dim >= 2_048 {
        field_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 2,
            output_start: 512,
            input_mul: 2,
            output_mul: 512,
            irrep_dim: 3,
            weight_offset: 1_024,
        });
        field_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 8,
            output_start: 0,
            input_mul: 2,
            output_mul: 512,
            irrep_dim: 1,
            weight_offset: 2_048,
        });
        field_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 10,
            output_start: 512,
            input_mul: 2,
            output_mul: 512,
            irrep_dim: 3,
            weight_offset: 3_072,
        });
        4_096
    } else {
        field_instructions.push(MacePolarBlockLinearInstruction {
            input_start: 8,
            output_start: 0,
            input_mul: 2,
            output_mul: 512,
            irrep_dim: 1,
            weight_offset: 1_024,
        });
        2_048
    };
    let field_path_weights = vec![0.5; field_instructions.len()];
    let field_cotangent = polar_mace_field_map_block_linear_rows_vjp_from_tensors(
        access,
        "local_electron_energy.linear_up_v",
        &bar_v_up,
        field_feats,
        16,
        feature_dim,
        field_weight_len,
        &field_instructions,
        Some(&field_path_weights),
    )?;
    mace_polar_trace_stage("local_electron.vjp.linear_up_backprop", stage_start);
    Ok(MacePolarLocalElectronEnergyCotangents {
        node_feats: node_cotangent,
        field_feats: field_cotangent,
        charges_0: q_in_cotangent.clone(),
        charges_induced: q_in_cotangent,
    })
}

fn polar_mace_atomic_energy_by_graph_from_atomic_numbers(
    access: &MacePolarTensorAccess<'_>,
    atomic_numbers: &[u8],
    batch: &[usize],
) -> Result<Vec<f64>, MacePolarError> {
    require_usize(
        "atomic_energies.batch.len",
        batch.len(),
        atomic_numbers.len(),
    )?;
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    let atomic_energies = access.f64("atomic_energies_fn.atomic_energies", &[83])?;
    let mut energy_by_graph = vec![0.0_f64; graph_count];
    for (atomic_number, graph) in atomic_numbers.iter().zip(batch) {
        let type_index = polar_mace_type_index_from_atomic_number(*atomic_number)?;
        energy_by_graph[*graph] += atomic_energies[type_index];
    }
    Ok(energy_by_graph)
}

