fn polar_mace_external_dipole_energy_by_graph(
    external_potential_by_graph: &[[f64; 4]],
    total_dipoles_by_graph: &[[f64; 3]],
) -> Result<Vec<f64>, MacePolarError> {
    require_usize(
        "external_dipole_energy.total_dipoles_by_graph.len",
        total_dipoles_by_graph.len(),
        external_potential_by_graph.len(),
    )?;
    external_potential_by_graph
        .iter()
        .zip(total_dipoles_by_graph)
        .enumerate()
        .map(|(graph, (external, dipole))| {
            if !external.iter().all(|value| value.is_finite())
                || !dipole.iter().all(|value| value.is_finite())
            {
                return Err(invalid(
                    "external_dipole_energy",
                    format!("graph {graph} external potential or dipole is non-finite"),
                ));
            }
            Ok(external[1] * dipole[0] + external[2] * dipole[1] + external[3] * dipole[2])
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_external_dipole_energy_by_graph_vjp(
    energy_cotangent_by_graph: &[f64],
    external_potential_by_graph: &[[f64; 4]],
    total_dipoles_by_graph: &[[f64; 3]],
) -> Result<Vec<[f64; 3]>, MacePolarError> {
    require_usize(
        "external_dipole_energy_vjp.energy_cotangent_by_graph.len",
        energy_cotangent_by_graph.len(),
        external_potential_by_graph.len(),
    )?;
    require_usize(
        "external_dipole_energy_vjp.total_dipoles_by_graph.len",
        total_dipoles_by_graph.len(),
        external_potential_by_graph.len(),
    )?;
    external_potential_by_graph
        .iter()
        .zip(total_dipoles_by_graph)
        .zip(energy_cotangent_by_graph)
        .enumerate()
        .map(|(graph, ((external, dipole), bar_energy))| {
            if !external.iter().all(|value| value.is_finite())
                || !dipole.iter().all(|value| value.is_finite())
                || !bar_energy.is_finite()
            {
                return Err(invalid(
                    "external_dipole_energy_vjp",
                    format!("graph {graph} external potential, dipole, or cotangent is non-finite"),
                ));
            }
            Ok([
                bar_energy * external[1],
                bar_energy * external[2],
                bar_energy * external[3],
            ])
        })
        .collect()
}

