#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_field_coupled_scf_runtime_slice_from_handoff_with_step0(
    runtime: &MacePolarRuntimeState,
    species: &[String],
    positions: &[[f64; 3]],
    handoff: MacePolarScalarEnergyHandoff,
    total_charge: f64,
    total_spin: f64,
    step1_potential_features: &[Vec<f64>],
    step0_charge_map: MacePolarFieldDependentChargeMapRows,
    step0_update: MacePolarScfChargeUpdate,
) -> Result<MacePolarFieldCoupledScfRuntimeSlice, MacePolarError> {
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let node_attrs = polar_mace_node_attr_rows_from_atomic_numbers(&atomic_numbers)?;
    let batch = vec![0_usize; positions.len()];
    let access = MacePolarTensorAccess::new(&runtime.all_tensors.tensors);
    let atomic_energy_by_graph =
        polar_mace_atomic_energy_by_graph_from_atomic_numbers(&access, &atomic_numbers, &batch)?;
    let step1_charge_map = polar_mace_field_dependent_charge_map_rows_from_tensors(
        &access,
        1,
        &handoff.features_mixed,
        step1_potential_features,
        &step0_update.spin_charge_density_after_correction,
        &node_attrs,
    )?;
    let step1_update = polar_mace_scf_charge_update_rows(
        &step0_update.spin_charge_density_after_correction,
        &step1_charge_map.charge_sources_out,
        total_charge,
        total_spin,
        &batch,
    )?;
    let local_electron_energy = polar_mace_local_electron_energy_rows_from_tensors(
        &access,
        &handoff.local_backbone.product_out,
        step1_potential_features,
        &handoff.field_independent_spin_charge_density,
        &step1_update.spin_charge_density_after_correction,
    )?;
    let charge_density_outputs = polar_mace_charge_density_outputs_from_spin_charge_density(
        &step1_update.spin_charge_density_after_correction,
        positions,
        &batch,
    )?;
    let charge_density_source_feats = charge_density_outputs.density_coefficients.clone();
    let realspace_coulomb = polar_mace_realspace_coulomb_rows_from_tensors(
        &access,
        &charge_density_source_feats,
        positions,
        &batch,
        true,
    )?;
    let mut energy_without_external_by_graph = atomic_energy_by_graph.clone();
    if energy_without_external_by_graph.is_empty() {
        return Err(invalid(
            "mace_polar.scalar_energy",
            "expected at least one graph for scalar energy assembly",
        ));
    }
    energy_without_external_by_graph[0] += handoff.local_backbone.interaction_energy;
    energy_without_external_by_graph[0] += local_electron_energy.electron_energy;
    for (energy, electrostatic) in energy_without_external_by_graph
        .iter_mut()
        .zip(&realspace_coulomb.electrostatic_energy_by_graph)
    {
        *energy += *electrostatic;
    }
    Ok(MacePolarFieldCoupledScfRuntimeSlice {
        handoff,
        atomic_energy_by_graph,
        step0_charge_map,
        step0_update,
        step1_charge_map,
        step1_update,
        local_electron_energy,
        charge_density_outputs,
        charge_density_source_feats,
        realspace_coulomb,
        energy_without_external_by_graph,
    })
}

