#[allow(dead_code)]
fn polar_mace_realspace_scf_runtime_slice(
    runtime: &MacePolarRuntimeState,
    species: &[String],
    positions: &[[f64; 3]],
    fukui_activation_constant: f64,
    total_charge: f64,
    total_spin: f64,
    external_potential_by_graph: &[[f64; 4]],
) -> Result<MacePolarRealspaceScfRuntimeSlice, MacePolarError> {
    let constants = runtime.constants.as_ref().ok_or_else(|| {
        invalid(
            "mace_polar.runtime",
            "realspace SCF runtime slice requires retained runtime constants",
        )
    })?;
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    let handoff = polar_mace_scalar_energy_handoff_runtime_slice(
        runtime,
        species,
        positions,
        fukui_activation_constant,
        total_charge,
        total_spin,
    )?;
    mace_polar_trace_stage("scf_forward.scalar_handoff", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let batch = vec![0_usize; positions.len()];
    let access = MacePolarTensorAccess::new(&runtime.all_tensors.tensors);
    let half_external_field = polar_mace_half_external_field_rows_from_tensors(
        &access,
        positions,
        &batch,
        external_potential_by_graph,
    )?;
    let step0_alpha_source = polar_mace_rows_slice(
        &handoff.field_independent_spin_charge_density,
        0,
        4,
        "realspace_scf.step0_alpha_source",
    )?;
    let step0_beta_source = polar_mace_rows_slice(
        &handoff.field_independent_spin_charge_density,
        4,
        4,
        "realspace_scf.step0_beta_source",
    )?;
    let step0_alpha_descriptor = polar_mace_realspace_descriptor_forward_dynamic_rows_from_tensors(
        &access,
        &step0_alpha_source,
        positions,
        &batch,
        false,
    )?;
    let step0_beta_descriptor = polar_mace_realspace_descriptor_forward_dynamic_rows_from_tensors(
        &access,
        &step0_beta_source,
        positions,
        &batch,
        false,
    )?;
    let step0_alpha_field_features = polar_mace_normalized_field_feature_rows(
        &step0_alpha_descriptor.final_rows,
        &half_external_field,
        &constants.field_feature_norms,
    )?;
    let step0_beta_field_features = polar_mace_normalized_field_feature_rows(
        &step0_beta_descriptor.final_rows,
        &half_external_field,
        &constants.field_feature_norms,
    )?;
    let step0_potential_features = polar_mace_potential_feature_rows_from_normalized_fields(
        &step0_alpha_field_features,
        &step0_beta_field_features,
    )?;
    mace_polar_trace_stage("scf_forward.step0_fields", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let node_attrs = polar_mace_node_attr_rows_from_atomic_numbers(&atomic_numbers)?;
    let step0_charge_map = polar_mace_field_dependent_charge_map_rows_from_tensors(
        &access,
        0,
        &handoff.features_mixed,
        &step0_potential_features,
        &handoff.field_independent_spin_charge_density,
        &node_attrs,
    )?;
    let step0_update = polar_mace_scf_charge_update_rows(
        &handoff.field_independent_spin_charge_density,
        &step0_charge_map.charge_sources_out,
        total_charge,
        total_spin,
        &batch,
    )?;
    mace_polar_trace_stage("scf_forward.step0_charge_update", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let step1_alpha_source = polar_mace_rows_slice(
        &step0_update.spin_charge_density_after_correction,
        0,
        4,
        "realspace_scf.step1_alpha_source",
    )?;
    let step1_beta_source = polar_mace_rows_slice(
        &step0_update.spin_charge_density_after_correction,
        4,
        4,
        "realspace_scf.step1_beta_source",
    )?;
    let step1_alpha_descriptor = polar_mace_realspace_descriptor_forward_dynamic_rows_from_tensors(
        &access,
        &step1_alpha_source,
        positions,
        &batch,
        false,
    )?;
    let step1_beta_descriptor = polar_mace_realspace_descriptor_forward_dynamic_rows_from_tensors(
        &access,
        &step1_beta_source,
        positions,
        &batch,
        false,
    )?;
    let step1_alpha_field_features = polar_mace_normalized_field_feature_rows(
        &step1_alpha_descriptor.final_rows,
        &half_external_field,
        &constants.field_feature_norms,
    )?;
    let step1_beta_field_features = polar_mace_normalized_field_feature_rows(
        &step1_beta_descriptor.final_rows,
        &half_external_field,
        &constants.field_feature_norms,
    )?;
    let step1_potential_features = polar_mace_potential_feature_rows_from_normalized_fields(
        &step1_alpha_field_features,
        &step1_beta_field_features,
    )?;
    mace_polar_trace_stage("scf_forward.step1_fields", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let scf = polar_mace_field_coupled_scf_runtime_slice_from_handoff(
        runtime,
        species,
        positions,
        handoff,
        total_charge,
        total_spin,
        &step0_potential_features,
        &step1_potential_features,
    )?;
    mace_polar_trace_stage("scf_forward.field_coupled_scf", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let external_dipole_energy_by_graph = polar_mace_external_dipole_energy_by_graph(
        external_potential_by_graph,
        &scf.charge_density_outputs.total_dipole_by_graph,
    )?;
    let total_energy_by_graph = scf
        .energy_without_external_by_graph
        .iter()
        .zip(&external_dipole_energy_by_graph)
        .map(|(energy, external)| energy + external)
        .collect();
    mace_polar_trace_stage("scf_forward.total_energy_tail", stage_start);
    mace_polar_trace_stage("scf_forward.total", total_start);

    Ok(MacePolarRealspaceScfRuntimeSlice {
        step0_alpha_descriptor,
        step0_beta_descriptor,
        step0_potential_features,
        step1_alpha_descriptor,
        step1_beta_descriptor,
        step1_potential_features,
        scf,
        external_dipole_energy_by_graph,
        total_energy_by_graph,
    })
}

