fn polar_mace_conv_tp_plans_from_execution_plan_and_tensors(
    execution_plan: &MacePolarRuntimeExecutionPlan,
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
) -> Result<Vec<e3nn_core::TensorProductPlan>, MacePolarError> {
    (0..execution_plan.layers.len())
        .map(|layer| {
            let mut plan =
                polar_mace_layer_conv_tp_plan_from_execution_plan(execution_plan, layer)?;
            polar_mace_apply_upstream_compiled_wigner_buffers_to_conv_tp_plan(
                layer, &mut plan, tensors,
            )?;
            Ok(plan)
        })
        .collect()
}

fn polar_mace_apply_upstream_compiled_wigner_buffers_to_conv_tp_plan(
    layer: usize,
    plan: &mut e3nn_core::TensorProductPlan,
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
) -> Result<(), MacePolarError> {
    let layouts = plan
        .checked_layouts()
        .map_err(|err| invalid("conv_tp_plan.layout", err.to_string()))?;
    for instruction in &plan.instructions {
        let in1_l = layouts
            .in1
            .get(instruction.in1_segment)
            .ok_or_else(|| {
                invalid(
                    "conv_tp_plan.instruction_in1_segment",
                    format!(
                        "layer {layer} segment {} is out of range",
                        instruction.in1_segment
                    ),
                )
            })?
            .irrep
            .l;
        let in2_l = layouts
            .in2
            .get(instruction.in2_segment)
            .ok_or_else(|| {
                invalid(
                    "conv_tp_plan.instruction_in2_segment",
                    format!(
                        "layer {layer} segment {} is out of range",
                        instruction.in2_segment
                    ),
                )
            })?
            .irrep
            .l;
        let out_l = layouts
            .out
            .get(instruction.out_segment)
            .ok_or_else(|| {
                invalid(
                    "conv_tp_plan.instruction_out_segment",
                    format!(
                        "layer {layer} segment {} is out of range",
                        instruction.out_segment
                    ),
                )
            })?
            .irrep
            .l;
        let wigner_name = format!(
            "interactions.{layer}.conv_tp._compiled_main_left_right._w3j_{in1_l}_{in2_l}_{out_l}"
        );
        if !tensors.contains_key(&wigner_name) {
            continue;
        }
        let cg_end = instruction
            .cg_offset
            .checked_add(instruction.cg_len)
            .ok_or_else(|| invalid("conv_tp_plan.cg_range", "cg range overflows usize"))?;
        if cg_end > plan.cg_entries.len() {
            return Err(invalid(
                "conv_tp_plan.cg_range",
                format!(
                    "layer {layer} cg range {}..{} exceeds {} entries",
                    instruction.cg_offset,
                    cg_end,
                    plan.cg_entries.len()
                ),
            ));
        }
        for entry in &mut plan.cg_entries[instruction.cg_offset..cg_end] {
            entry.value = f64::from(entry.value as f32);
        }
    }
    Ok(())
}

#[cfg(test)]
mod polar_mace_conv_tp_plan_tests {
    use super::*;

    fn single_wigner_path_plan() -> Result<e3nn_core::TensorProductPlan, MacePolarError> {
        e3nn_core::TensorProductPlan::new(
            "1x1o"
                .parse()
                .map_err(|err| invalid("test.irreps_in1", format!("{err}")))?,
            "1x2e"
                .parse()
                .map_err(|err| invalid("test.irreps_in2", format!("{err}")))?,
            "1x1o"
                .parse()
                .map_err(|err| invalid("test.irreps_out", format!("{err}")))?,
            vec![e3nn_core::TensorProductInstruction {
                in1_segment: 0,
                in2_segment: 0,
                out_segment: 0,
                cg_offset: 0,
                cg_len: 1,
                weight_offset: Some(0),
                path_weight: 1.0,
            }],
            vec![e3nn_core::CgEntry {
                i_m: 0,
                j_m: 0,
                k_m: 0,
                value: 0.316_227_766_016_838_2,
            }],
            1,
        )
        .map_err(|err| invalid("test.conv_tp_plan", err.to_string()))
    }

    fn dummy_wigner_tensors() -> BTreeMap<String, MacePolarExternalTensor> {
        BTreeMap::from([(
            "interactions.1.conv_tp._compiled_main_left_right._w3j_1_2_1".to_owned(),
            MacePolarExternalTensor {
                shape: vec![3, 5, 3],
                values: MacePolarExternalTensorValues::F64(vec![0.0; 45]),
            },
        )])
    }

    #[test]
    fn compiled_wigner_tensor_presence_f32_rounds_matching_conv_tp_cg_values(
    ) -> Result<(), MacePolarError> {
        let original = 0.316_227_766_016_838_2;
        let mut plan = single_wigner_path_plan()?;
        polar_mace_apply_upstream_compiled_wigner_buffers_to_conv_tp_plan(
            1,
            &mut plan,
            &dummy_wigner_tensors(),
        )?;

        assert_eq!(plan.cg_entries[0].value, f64::from(original as f32));
        Ok(())
    }

    #[test]
    fn compiled_wigner_rounding_leaves_paths_without_state_buffers_unchanged(
    ) -> Result<(), MacePolarError> {
        let original = 0.316_227_766_016_838_2;
        let mut plan = single_wigner_path_plan()?;
        polar_mace_apply_upstream_compiled_wigner_buffers_to_conv_tp_plan(
            1,
            &mut plan,
            &BTreeMap::new(),
        )?;

        assert_eq!(plan.cg_entries[0].value, original);
        Ok(())
    }
}

