#[allow(dead_code)]
fn polar_mace_split_charge_sources_out_rows(
    charge_sources_out: &[Vec<f64>],
) -> Result<(MacePolarRows, MacePolarRows), MacePolarError> {
    let mut charge_sources = Vec::with_capacity(charge_sources_out.len());
    let mut current_fukui_sources_raw = Vec::with_capacity(charge_sources_out.len());
    for (row_index, row) in charge_sources_out.iter().enumerate() {
        require_usize(
            &format!("scf_charge_update.charge_sources_out[{row_index}].len"),
            row.len(),
            10,
        )?;
        charge_sources.push(row[0..8].to_vec());
        current_fukui_sources_raw.push(row[8..10].to_vec());
    }
    Ok((charge_sources, current_fukui_sources_raw))
}

#[allow(dead_code)]
fn polar_mace_add_spin_charge_source_rows(
    spin_charge_density: &[Vec<f64>],
    charge_sources: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        "scf_charge_update.charge_sources.len",
        charge_sources.len(),
        spin_charge_density.len(),
    )?;
    spin_charge_density
        .iter()
        .zip(charge_sources)
        .enumerate()
        .map(|(row_index, (density, source))| {
            require_usize(
                &format!("scf_charge_update.spin_charge_density[{row_index}].len"),
                density.len(),
                8,
            )?;
            require_usize(
                &format!("scf_charge_update.charge_sources[{row_index}].len"),
                source.len(),
                8,
            )?;
            Ok(density
                .iter()
                .zip(source)
                .map(|(density_value, source_value)| density_value + source_value)
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_scf_charge_update_rows(
    spin_charge_density: &[Vec<f64>],
    charge_sources_out: &[Vec<f64>],
    total_charge: f64,
    total_spin: f64,
    batch: &[usize],
) -> Result<MacePolarScfChargeUpdate, MacePolarError> {
    if !total_charge.is_finite() || !total_spin.is_finite() {
        return Err(invalid(
            "scf_charge_update",
            "total_charge and total_spin must be finite",
        ));
    }
    let graph_count = batch.iter().copied().max().map_or(0, |graph| graph + 1);
    let total_charges = vec![total_charge; graph_count];
    let total_spins = vec![total_spin; graph_count];
    polar_mace_scf_charge_update_rows_for_graph_targets(
        spin_charge_density,
        charge_sources_out,
        &total_charges,
        &total_spins,
        batch,
    )
}

#[allow(dead_code)]
fn polar_mace_scf_charge_update_rows_for_graph_targets(
    spin_charge_density: &[Vec<f64>],
    charge_sources_out: &[Vec<f64>],
    total_charges: &[f64],
    total_spins: &[f64],
    batch: &[usize],
) -> Result<MacePolarScfChargeUpdate, MacePolarError> {
    let (charge_sources, current_fukui_sources_raw) =
        polar_mace_split_charge_sources_out_rows(charge_sources_out)?;
    let spin_charge_density_before_correction =
        polar_mace_add_spin_charge_source_rows(spin_charge_density, &charge_sources)?;
    let current_fukui_norm = polar_mace_fukui_norm_rows(&current_fukui_sources_raw, batch)?;
    let current_fukui_sources_normalized =
        polar_mace_normalize_fukui_source_rows(&current_fukui_sources_raw, &current_fukui_norm)?;
    let correction = polar_mace_fukui_charge_correction_rows_for_graph_targets(
        &spin_charge_density_before_correction,
        &current_fukui_sources_normalized,
        total_charges,
        total_spins,
        batch,
    )?;
    Ok(MacePolarScfChargeUpdate {
        charge_sources,
        current_fukui_sources_raw,
        current_fukui_sources_normalized,
        spin_charge_density_before_correction,
        spin_charge_density_after_correction: correction.corrected_spin_charge_density,
        predicted_total_charges: correction.predicted_total_charges,
    })
}

#[allow(dead_code)]
fn polar_mace_scf_charge_update_rows_vjp(
    output_cotangent: &[Vec<f64>],
    predicted_total_charges_cotangent: Option<&[Vec<f64>]>,
    spin_charge_density: &[Vec<f64>],
    charge_sources_out: &[Vec<f64>],
    total_charges: &[f64],
    total_spins: &[f64],
    batch: &[usize],
) -> Result<MacePolarScfChargeUpdateCotangents, MacePolarError> {
    let (charge_sources, current_fukui_sources_raw) =
        polar_mace_split_charge_sources_out_rows(charge_sources_out)?;
    let spin_charge_density_before_correction =
        polar_mace_add_spin_charge_source_rows(spin_charge_density, &charge_sources)?;
    let current_fukui_norm = polar_mace_fukui_norm_rows(&current_fukui_sources_raw, batch)?;
    let current_fukui_sources_normalized =
        polar_mace_normalize_fukui_source_rows(&current_fukui_sources_raw, &current_fukui_norm)?;
    let correction_cotangents = polar_mace_fukui_charge_correction_rows_vjp(
        output_cotangent,
        predicted_total_charges_cotangent,
        &spin_charge_density_before_correction,
        &current_fukui_sources_normalized,
        total_charges,
        total_spins,
        batch,
    )?;
    let (mut raw_cotangent, norm_cotangent) = polar_mace_normalize_fukui_source_rows_vjp(
        &correction_cotangents.fukui_sources_normalized,
        &current_fukui_sources_raw,
        &current_fukui_norm,
    )?;
    let norm_raw_cotangent =
        polar_mace_fukui_norm_rows_vjp(&norm_cotangent, &current_fukui_sources_raw, batch)?;
    polar_mace_add_rows_in_place(
        &mut raw_cotangent,
        &norm_raw_cotangent,
        "scf_charge_update_vjp.current_fukui_sources_raw",
    )?;

    require_usize(
        "scf_charge_update_vjp.spin_charge_density.len",
        spin_charge_density.len(),
        spin_charge_density_before_correction.len(),
    )?;
    require_usize(
        "scf_charge_update_vjp.charge_sources.len",
        charge_sources.len(),
        spin_charge_density.len(),
    )?;
    require_usize(
        "scf_charge_update_vjp.charge_sources_out.len",
        charge_sources_out.len(),
        spin_charge_density.len(),
    )?;
    let mut spin_cotangent = polar_mace_zero_rows_like(spin_charge_density);
    let mut charge_sources_out_cotangent = polar_mace_zero_rows_like(charge_sources_out);
    for row_index in 0..spin_charge_density.len() {
        require_usize(
            &format!("scf_charge_update_vjp.spin_charge_density[{row_index}].len"),
            spin_charge_density[row_index].len(),
            8,
        )?;
        require_usize(
            &format!("scf_charge_update_vjp.charge_sources_out[{row_index}].len"),
            charge_sources_out[row_index].len(),
            10,
        )?;
        require_usize(
            &format!("scf_charge_update_vjp.before_correction[{row_index}].len"),
            correction_cotangents.spin_charge_density_accumulated[row_index].len(),
            8,
        )?;
        require_usize(
            &format!("scf_charge_update_vjp.raw_cotangent[{row_index}].len"),
            raw_cotangent[row_index].len(),
            2,
        )?;
        for component in 0..8 {
            let bar = correction_cotangents.spin_charge_density_accumulated[row_index][component];
            spin_cotangent[row_index][component] += bar;
            charge_sources_out_cotangent[row_index][component] += bar;
        }
        charge_sources_out_cotangent[row_index][8] += raw_cotangent[row_index][0];
        charge_sources_out_cotangent[row_index][9] += raw_cotangent[row_index][1];
    }
    Ok(MacePolarScfChargeUpdateCotangents {
        spin_charge_density: spin_cotangent,
        charge_sources_out: charge_sources_out_cotangent,
    })
}

#[allow(dead_code)]
fn polar_mace_require_hot_len(
    name: &str,
    suffix: &str,
    actual: usize,
    expected: usize,
) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        require_usize(&format!("{name}.{suffix}"), actual, expected)
    }
}

#[allow(dead_code)]
fn polar_mace_require_hot_row_len(
    name: &str,
    rows_name: &str,
    row_index: usize,
    actual: usize,
    expected: usize,
) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        require_usize(
            &format!("{name}.{rows_name}[{row_index}].len"),
            actual,
            expected,
        )
    }
}

#[allow(dead_code)]
fn polar_mace_torch_linear_rows(
    input_rows: &[Vec<f64>],
    weight: &[f64],
    bias: &[f64],
    input_dim: usize,
    output_dim: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_require_hot_len(name, "weight.len", weight.len(), input_dim * output_dim)?;
    polar_mace_require_hot_len(name, "bias.len", bias.len(), output_dim)?;
    for (row_index, input) in input_rows.iter().enumerate() {
        polar_mace_require_hot_row_len(name, "input_rows", row_index, input.len(), input_dim)?;
    }

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    {
        let row_count = input_rows.len();
        if row_count == 0 {
            return Ok(Vec::new());
        }
        let mut input_flat = vec![0.0_f64; row_count * input_dim];
        for (row_index, input) in input_rows.iter().enumerate() {
            let start = row_index * input_dim;
            input_flat[start..start + input_dim].copy_from_slice(input);
        }
        let mut output_flat = vec![0.0_f64; row_count * output_dim];
        blas_backend::dense_forward_output_major_weight(
            &input_flat,
            row_count,
            input_dim,
            weight,
            &mut output_flat,
            output_dim,
            1.0,
            0.0,
        );
        for row in 0..row_count {
            let start = row * output_dim;
            for out in 0..output_dim {
                output_flat[start + out] += bias[out];
            }
        }
        Ok(output_flat
            .chunks_exact(output_dim)
            .map(|row| row.to_vec())
            .collect())
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    {
        input_rows
            .iter()
            .enumerate()
            .map(|(row_index, input)| {
                require_usize(
                    &format!("{name}.input_rows[{row_index}].len"),
                    input.len(),
                    input_dim,
                )?;
                let mut output = vec![0.0; output_dim];
                for out in 0..output_dim {
                    let mut value = bias[out];
                    for input_index in 0..input_dim {
                        value = weight[out * input_dim + input_index]
                            .mul_add(input[input_index], value);
                    }
                    output[out] = value;
                }
                Ok(output)
            })
            .collect()
    }
}

#[allow(dead_code)]
fn polar_mace_torch_linear_rows_vjp(
    output_cotangent: &[Vec<f64>],
    weight: &[f64],
    input_dim: usize,
    output_dim: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_require_hot_len(name, "weight.len", weight.len(), input_dim * output_dim)?;
    for (row_index, bar_output) in output_cotangent.iter().enumerate() {
        polar_mace_require_hot_row_len(
            name,
            "output_cotangent",
            row_index,
            bar_output.len(),
            output_dim,
        )?;
    }

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    {
        let row_count = output_cotangent.len();
        if row_count == 0 {
            return Ok(Vec::new());
        }
        let mut bar_output_flat = vec![0.0_f64; row_count * output_dim];
        for (row_index, bar_output) in output_cotangent.iter().enumerate() {
            let start = row_index * output_dim;
            bar_output_flat[start..start + output_dim].copy_from_slice(bar_output);
        }
        let mut bar_input_flat = vec![0.0_f64; row_count * input_dim];
        blas_backend::dense_vjp_input_output_major_weight(
            row_count,
            input_dim,
            output_dim,
            weight,
            &bar_output_flat,
            &mut bar_input_flat,
            1.0,
            0.0,
        );
        Ok(bar_input_flat
            .chunks_exact(input_dim)
            .map(|row| row.to_vec())
            .collect())
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    {
        output_cotangent
            .iter()
            .enumerate()
            .map(|(row_index, bar_output)| {
                require_usize(
                    &format!("{name}.output_cotangent[{row_index}].len"),
                    bar_output.len(),
                    output_dim,
                )?;
                let mut bar_input = vec![0.0; input_dim];
                for out in 0..output_dim {
                    for input_index in 0..input_dim {
                        bar_input[input_index] +=
                            weight[out * input_dim + input_index] * bar_output[out];
                    }
                }
                Ok(bar_input)
            })
            .collect()
    }
}

#[allow(dead_code)]
fn polar_mace_layer_norm_rows(
    input_rows: &[Vec<f64>],
    weight: &[f64],
    bias: &[f64],
    eps: f64,
    width: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_require_hot_len(name, "weight.len", weight.len(), width)?;
    polar_mace_require_hot_len(name, "bias.len", bias.len(), width)?;
    input_rows
        .iter()
        .enumerate()
        .map(|(row_index, input)| {
            polar_mace_require_hot_row_len(name, "input_rows", row_index, input.len(), width)?;
            let mean = input.iter().sum::<f64>() / width as f64;
            let variance = input
                .iter()
                .map(|value| {
                    let delta = value - mean;
                    delta * delta
                })
                .sum::<f64>()
                / width as f64;
            let denom = (variance + eps).sqrt();
            Ok(input
                .iter()
                .enumerate()
                .map(|(index, value)| ((value - mean) / denom) * weight[index] + bias[index])
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_layer_norm_rows_vjp(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    weight: &[f64],
    eps: f64,
    width: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_require_hot_len(name, "weight.len", weight.len(), width)?;
    polar_mace_require_hot_len(
        name,
        "output_cotangent.len",
        output_cotangent.len(),
        input_rows.len(),
    )?;
    input_rows
        .iter()
        .zip(output_cotangent)
        .enumerate()
        .map(|(row_index, (input, bar_output))| {
            polar_mace_require_hot_row_len(name, "input_rows", row_index, input.len(), width)?;
            polar_mace_require_hot_row_len(
                name,
                "output_cotangent",
                row_index,
                bar_output.len(),
                width,
            )?;
            let mean = input.iter().sum::<f64>() / width as f64;
            let variance = input
                .iter()
                .map(|value| {
                    let delta = value - mean;
                    delta * delta
                })
                .sum::<f64>()
                / width as f64;
            let inv_denom = 1.0 / (variance + eps).sqrt();
            let mut bar_normalized = vec![0.0; width];
            let mut normalized = vec![0.0; width];
            for index in 0..width {
                normalized[index] = (input[index] - mean) * inv_denom;
                bar_normalized[index] = bar_output[index] * weight[index];
            }
            let bar_sum = bar_normalized.iter().sum::<f64>();
            let bar_dot_normalized = bar_normalized
                .iter()
                .zip(&normalized)
                .map(|(bar, value)| bar * value)
                .sum::<f64>();
            Ok((0..width)
                .map(|index| {
                    inv_denom
                        * (bar_normalized[index]
                            - bar_sum / width as f64
                            - normalized[index] * bar_dot_normalized / width as f64)
                })
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_silu_rows(rows: &[Vec<f64>]) -> MacePolarRows {
    rows.iter()
        .map(|row| {
            row.iter()
                .map(|value| value / (1.0 + (-value).exp()))
                .collect()
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_silu_rows_vjp(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    polar_mace_require_hot_len(
        name,
        "output_cotangent.len",
        output_cotangent.len(),
        input_rows.len(),
    )?;
    input_rows
        .iter()
        .zip(output_cotangent)
        .enumerate()
        .map(|(row_index, (input, bar_output))| {
            polar_mace_require_hot_row_len(
                name,
                "output_cotangent",
                row_index,
                bar_output.len(),
                input.len(),
            )?;
            Ok(input
                .iter()
                .zip(bar_output)
                .map(|(value, bar)| {
                    let sigmoid = 1.0 / (1.0 + (-value).exp());
                    bar * (sigmoid + value * sigmoid * (1.0 - sigmoid))
                })
                .collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_flatten_rows(
    rows: &[Vec<f64>],
    width: usize,
    name: &str,
) -> Result<Vec<f64>, MacePolarError> {
    let mut flat = Vec::with_capacity(rows.len() * width);
    for (row_index, row) in rows.iter().enumerate() {
        polar_mace_require_hot_row_len(name, "rows", row_index, row.len(), width)?;
        flat.extend_from_slice(row);
    }
    Ok(flat)
}

