#[allow(dead_code, clippy::too_many_arguments)]
fn polar_mace_dense_forward_output_major_weight_f32(
    input: &[f32],
    rows: usize,
    in_dim: usize,
    weight: &[f32],
    out: &mut [f32],
    out_dim: usize,
    alpha: f32,
    beta: f32,
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    {
        blas_backend::dense_forward_output_major_weight_f32(
            input, rows, in_dim, weight, out, out_dim, alpha, beta,
        );
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )))]
    {
        debug_assert!(input.len() >= rows * in_dim);
        debug_assert!(weight.len() >= out_dim * in_dim);
        debug_assert!(out.len() >= rows * out_dim);
        for row in 0..rows {
            let input_start = row * in_dim;
            let out_start = row * out_dim;
            for output in 0..out_dim {
                let weight_start = output * in_dim;
                let mut sum = 0.0_f32;
                for input_index in 0..in_dim {
                    sum += input[input_start + input_index] * weight[weight_start + input_index];
                }
                out[out_start + output] = alpha * sum + beta * out[out_start + output];
            }
        }
    }
}

