#[allow(dead_code)]
fn polar_mace_density_fn_edge_density_cutoff_applied_rows_flat_f32_with_trace_for_layer_from_flat(
    tensors: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    layer: usize,
    edge_aug_flat: &[f32],
    row_count: usize,
    cutoffs: &[f32],
) -> Result<(Vec<Vec<f32>>, MacePolarDensityFnFlatTraceF32), MacePolarError> {
    require_usize("density_fn_f32.cutoffs.len", cutoffs.len(), row_count)?;
    let access = MacePolarTensorAccessF32::new(tensors);
    let hidden = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim;
    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim;
    let prefix = format!("interactions.{layer}.density_fn.net");
    polar_mace_require_hot_len(
        "density_fn_f32.edge_aug_flat",
        "len",
        edge_aug_flat.len(),
        row_count * input_dim,
    )?;
    if row_count == 0 {
        return Ok((
            Vec::new(),
            MacePolarDensityFnFlatTraceF32 {
                row_count: 0,
                linear_0: Vec::new(),
                norm_1: Vec::new(),
                raw: Vec::new(),
            },
        ));
    }

    let mut linear_0 = vec![0.0_f32; row_count * hidden];
    polar_mace_dense_forward_output_major_weight_f32(
        edge_aug_flat,
        row_count,
        input_dim,
        access.f32(&format!("{prefix}.0.weight"), &[hidden, input_dim])?,
        &mut linear_0,
        hidden,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat_f32(
        &mut linear_0,
        row_count,
        hidden,
        access.f32(&format!("{prefix}.0.bias"), &[hidden])?,
    );
    let norm_1 = polar_mace_layer_norm_flat_f32(
        &linear_0,
        row_count,
        hidden,
        access.f32(&format!("{prefix}.1.weight"), &[hidden])?,
        access.f32(&format!("{prefix}.1.bias"), &[hidden])?,
        1.0e-5_f32,
        "density_fn_f32.net.1.flat",
    )?;
    let silu_1 = polar_mace_silu_flat_f32(&norm_1);

    let mut raw = vec![0.0_f32; row_count];
    polar_mace_dense_forward_output_major_weight_f32(
        &silu_1,
        row_count,
        hidden,
        access.f32(&format!("{prefix}.3.weight"), &[1, hidden])?,
        &mut raw,
        1,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat_f32(
        &mut raw,
        row_count,
        1,
        access.f32(&format!("{prefix}.3.bias"), &[1])?,
    );

    let rows = raw
        .iter()
        .zip(cutoffs)
        .map(|(value, cutoff)| vec![(value * value).tanh() * *cutoff])
        .collect();
    let trace = MacePolarDensityFnFlatTraceF32 {
        row_count,
        linear_0,
        norm_1,
        raw,
    };
    Ok((rows, trace))
}

#[allow(dead_code)]
fn polar_mace_density_fn_edge_density_cutoff_applied_rows_vjp_flat_f32_from_trace_for_layer(
    tensors: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    layer: usize,
    output_cotangent: &[Vec<f32>],
    cutoffs: &[f32],
    trace: &MacePolarDensityFnFlatTraceF32,
) -> Result<MacePolarDensityFnCotangentsF32, MacePolarError> {
    let access = MacePolarTensorAccessF32::new(tensors);
    let hidden = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim;
    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim;
    let row_count = trace.row_count;
    let prefix = format!("interactions.{layer}.density_fn.net");
    let trace_timings = mace_polar_trace_timings_enabled();
    let mut stage_start = trace_timings.then(Instant::now);

    require_usize(
        "density_fn_vjp_f32.trace.output_cotangent.len",
        output_cotangent.len(),
        row_count,
    )?;
    require_usize(
        "density_fn_vjp_f32.trace.cutoffs.len",
        cutoffs.len(),
        row_count,
    )?;
    polar_mace_require_hot_len(
        "density_fn_vjp_f32.trace",
        "linear_0.len",
        trace.linear_0.len(),
        row_count * hidden,
    )?;
    polar_mace_require_hot_len(
        "density_fn_vjp_f32.trace",
        "norm_1.len",
        trace.norm_1.len(),
        row_count * hidden,
    )?;
    polar_mace_require_hot_len(
        "density_fn_vjp_f32.trace",
        "raw.len",
        trace.raw.len(),
        row_count,
    )?;
    if row_count == 0 {
        return Ok(MacePolarDensityFnCotangentsF32 {
            edge_aug: Vec::new(),
            cutoffs: Vec::new(),
        });
    }

    let weight_0 = access.f32(&format!("{prefix}.0.weight"), &[hidden, input_dim])?;
    let norm_1_weight = access.f32(&format!("{prefix}.1.weight"), &[hidden])?;
    let weight_3 = access.f32(&format!("{prefix}.3.weight"), &[1, hidden])?;

    let mut raw_cotangent = vec![0.0_f32; row_count];
    let mut cutoff_cotangent = vec![0.0_f32; cutoffs.len()];
    for (row_index, ((bar_output, raw_value), cutoff)) in output_cotangent
        .iter()
        .zip(&trace.raw)
        .zip(cutoffs)
        .enumerate()
    {
        polar_mace_require_hot_row_len(
            "density_fn_vjp_f32.trace",
            "output_cotangent",
            row_index,
            bar_output.len(),
            1,
        )?;
        let squared = *raw_value * *raw_value;
        let tanh_squared = squared.tanh();
        let sech_squared = 1.0_f32 - tanh_squared * tanh_squared;
        raw_cotangent[row_index] = bar_output[0] * *cutoff * sech_squared * 2.0_f32 * *raw_value;
        cutoff_cotangent[row_index] += bar_output[0] * tanh_squared;
    }
    mace_polar_trace_stage("density_fn_vjp_f32.trace.raw_cotangent", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let mut silu_cotangent = vec![0.0_f32; row_count * hidden];
    polar_mace_dense_vjp_input_output_major_weight_f32(
        row_count,
        hidden,
        1,
        weight_3,
        &raw_cotangent,
        &mut silu_cotangent,
        1.0,
        0.0,
    );
    mace_polar_trace_stage("density_fn_vjp_f32.trace.net3", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let norm_cotangent = polar_mace_silu_flat_vjp_f32(
        &silu_cotangent,
        &trace.norm_1,
        "density_fn_vjp_f32.trace.silu",
    )?;
    let linear_cotangent = polar_mace_layer_norm_flat_vjp_f32(
        &norm_cotangent,
        &trace.linear_0,
        row_count,
        hidden,
        norm_1_weight,
        1.0e-5_f32,
        "density_fn_vjp_f32.trace.net.1",
    )?;
    mace_polar_trace_stage("density_fn_vjp_f32.trace.silu_norm", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let mut edge_aug_cotangent = vec![0.0_f32; row_count * input_dim];
    polar_mace_dense_vjp_input_output_major_weight_f32(
        row_count,
        input_dim,
        hidden,
        weight_0,
        &linear_cotangent,
        &mut edge_aug_cotangent,
        1.0,
        0.0,
    );
    mace_polar_trace_stage("density_fn_vjp_f32.trace.net0", stage_start);
    Ok(MacePolarDensityFnCotangentsF32 {
        edge_aug: polar_mace_unflatten_rows_f32(edge_aug_cotangent, input_dim),
        cutoffs: cutoff_cotangent,
    })
}

