#[allow(dead_code)]
fn polar_mace_conv_tp_weights_cutoff_applied_rows_for_layer(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    edge_aug_rows: &[Vec<f64>],
    cutoffs: &[f64],
    output_dim: usize,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        "conv_tp_weights.cutoffs.len",
        cutoffs.len(),
        edge_aug_rows.len(),
    )?;

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    {
        polar_mace_conv_tp_weights_cutoff_applied_rows_flat_for_layer(
            tensors,
            layer,
            edge_aug_rows,
            cutoffs,
            output_dim,
        )
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    {
        let access = MacePolarTensorAccess::new(tensors);
        let hidden = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim;
        let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim;
        let prefix = format!("interactions.{layer}.conv_tp_weights.net");

        let mut rows = polar_mace_torch_linear_rows(
            edge_aug_rows,
            access.f64(&format!("{prefix}.0.weight"), &[hidden, input_dim])?,
            access.f64(&format!("{prefix}.0.bias"), &[hidden])?,
            input_dim,
            hidden,
            "conv_tp_weights.net.0",
        )?;
        rows = polar_mace_layer_norm_rows(
            &rows,
            access.f64(&format!("{prefix}.1.weight"), &[hidden])?,
            access.f64(&format!("{prefix}.1.bias"), &[hidden])?,
            1.0e-5,
            hidden,
            "conv_tp_weights.net.1",
        )?;
        rows = polar_mace_silu_rows(&rows);
        rows = polar_mace_torch_linear_rows(
            &rows,
            access.f64(&format!("{prefix}.3.weight"), &[hidden, hidden])?,
            access.f64(&format!("{prefix}.3.bias"), &[hidden])?,
            hidden,
            hidden,
            "conv_tp_weights.net.3",
        )?;
        rows = polar_mace_layer_norm_rows(
            &rows,
            access.f64(&format!("{prefix}.4.weight"), &[hidden])?,
            access.f64(&format!("{prefix}.4.bias"), &[hidden])?,
            1.0e-5,
            hidden,
            "conv_tp_weights.net.4",
        )?;
        rows = polar_mace_silu_rows(&rows);
        rows = polar_mace_torch_linear_rows(
            &rows,
            access.f64(&format!("{prefix}.6.weight"), &[hidden, hidden])?,
            access.f64(&format!("{prefix}.6.bias"), &[hidden])?,
            hidden,
            hidden,
            "conv_tp_weights.net.6",
        )?;
        rows = polar_mace_layer_norm_rows(
            &rows,
            access.f64(&format!("{prefix}.7.weight"), &[hidden])?,
            access.f64(&format!("{prefix}.7.bias"), &[hidden])?,
            1.0e-5,
            hidden,
            "conv_tp_weights.net.7",
        )?;
        rows = polar_mace_silu_rows(&rows);
        let raw = polar_mace_torch_linear_rows(
            &rows,
            access.f64(&format!("{prefix}.9.weight"), &[output_dim, hidden])?,
            access.f64(&format!("{prefix}.9.bias"), &[output_dim])?,
            hidden,
            output_dim,
            "conv_tp_weights.net.9",
        )?;
        Ok(raw
            .iter()
            .zip(cutoffs)
            .map(|(row, cutoff)| row.iter().map(|value| value * cutoff).collect())
            .collect())
    }
}

