#[allow(dead_code)]
fn polar_mace_conv_tp_weights_cutoff_applied_rows_flat_trace_for_layer(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    edge_aug_rows: &[Vec<f64>],
    cutoffs: &[f64],
    output_dim: usize,
) -> Result<(MacePolarRows, MacePolarConvTpWeightsFlatTrace), MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let hidden = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim;
    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim;
    let row_count = edge_aug_rows.len();
    let prefix = format!("interactions.{layer}.conv_tp_weights.net");
    if row_count == 0 {
        return Ok((
            Vec::new(),
            MacePolarConvTpWeightsFlatTrace {
                row_count: 0,
                output_dim,
                linear_0: Vec::new(),
                norm_1: Vec::new(),
                linear_3: Vec::new(),
                norm_4: Vec::new(),
                linear_6: Vec::new(),
                norm_7: Vec::new(),
                raw: Vec::new(),
            },
        ));
    }

    let input_flat = polar_mace_flatten_rows(edge_aug_rows, input_dim, "conv_tp_weights.edge_aug")?;
    let mut linear_0 = vec![0.0_f64; row_count * hidden];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &input_flat,
        row_count,
        input_dim,
        access.f64(&format!("{prefix}.0.weight"), &[hidden, input_dim])?,
        &mut linear_0,
        hidden,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut linear_0,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.0.bias"), &[hidden])?,
    );
    let norm_1 = polar_mace_layer_norm_flat(
        &linear_0,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.1.weight"), &[hidden])?,
        access.f64(&format!("{prefix}.1.bias"), &[hidden])?,
        1.0e-5,
        "conv_tp_weights.net.1.flat",
    )?;
    let silu_1 = polar_mace_silu_flat(&norm_1);

    let mut linear_3 = vec![0.0_f64; row_count * hidden];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &silu_1,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.3.weight"), &[hidden, hidden])?,
        &mut linear_3,
        hidden,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut linear_3,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.3.bias"), &[hidden])?,
    );
    let norm_4 = polar_mace_layer_norm_flat(
        &linear_3,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.4.weight"), &[hidden])?,
        access.f64(&format!("{prefix}.4.bias"), &[hidden])?,
        1.0e-5,
        "conv_tp_weights.net.4.flat",
    )?;
    let silu_4 = polar_mace_silu_flat(&norm_4);

    let mut linear_6 = vec![0.0_f64; row_count * hidden];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &silu_4,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.6.weight"), &[hidden, hidden])?,
        &mut linear_6,
        hidden,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut linear_6,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.6.bias"), &[hidden])?,
    );
    let norm_7 = polar_mace_layer_norm_flat(
        &linear_6,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.7.weight"), &[hidden])?,
        access.f64(&format!("{prefix}.7.bias"), &[hidden])?,
        1.0e-5,
        "conv_tp_weights.net.7.flat",
    )?;
    let silu_7 = polar_mace_silu_flat(&norm_7);

    let mut raw = vec![0.0_f64; row_count * output_dim];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &silu_7,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.9.weight"), &[output_dim, hidden])?,
        &mut raw,
        output_dim,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut raw,
        row_count,
        output_dim,
        access.f64(&format!("{prefix}.9.bias"), &[output_dim])?,
    );
    let cutoff_applied_rows;
    #[cfg(feature = "parallel")]
    {
        cutoff_applied_rows = if row_count >= 16 && rayon::current_num_threads() > 1 {
            (0..row_count)
                .into_par_iter()
                .map(|edge| {
                    let start = edge * output_dim;
                    let cutoff = cutoffs[edge];
                    let mut row = vec![0.0_f64; output_dim];
                    for output in 0..output_dim {
                        row[output] = raw[start + output] * cutoff;
                    }
                    row
                })
                .collect()
        } else {
            let mut rows = Vec::with_capacity(row_count);
            for (edge, cutoff) in cutoffs.iter().enumerate() {
                let start = edge * output_dim;
                let mut row = Vec::with_capacity(output_dim);
                for output in 0..output_dim {
                    row.push(raw[start + output] * *cutoff);
                }
                rows.push(row);
            }
            rows
        };
    }
    #[cfg(not(feature = "parallel"))]
    {
        let mut rows = Vec::with_capacity(row_count);
        for (edge, cutoff) in cutoffs.iter().enumerate() {
            let start = edge * output_dim;
            let mut row = Vec::with_capacity(output_dim);
            for output in 0..output_dim {
                row.push(raw[start + output] * *cutoff);
            }
            rows.push(row);
        }
        cutoff_applied_rows = rows;
    }
    let trace = MacePolarConvTpWeightsFlatTrace {
        row_count,
        output_dim,
        linear_0,
        norm_1,
        linear_3,
        norm_4,
        linear_6,
        norm_7,
        raw,
    };
    Ok((cutoff_applied_rows, trace))
}

