fn polar_mace_tensor_product_vjp_unmasked(
    plan: &e3nn_core::TensorProductPlan,
    layouts: &e3nn_core::tp::TensorProductLayouts,
    x: &[f64],
    y: &[f64],
    w_edge: &[f64],
    grad_out: &[f64],
    grad_x: &mut [f64],
    grad_y: &mut [f64],
    grad_w_edge: &mut [f64],
) {
    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out_segment = layouts.out[instruction.out_segment];
        let weight = instruction
            .weight_offset
            .map(|offset| w_edge[offset])
            .unwrap_or(1.0);
        let cg_end = instruction.cg_offset + instruction.cg_len;
        for cg in &plan.cg_entries[instruction.cg_offset..cg_end] {
            let x_index = in1.start + cg.i_m;
            let y_index = in2.start + cg.j_m;
            let out_index = out_segment.start + cg.k_m;
            let scale = instruction.path_weight * cg.value;
            let bar_out = grad_out[out_index];

            grad_x[x_index] += scale * weight * y[y_index] * bar_out;
            grad_y[y_index] += scale * weight * x[x_index] * bar_out;
            if let Some(weight_offset) = instruction.weight_offset {
                grad_w_edge[weight_offset] += scale * x[x_index] * y[y_index] * bar_out;
            }
        }
    }
}

