#[allow(dead_code)]
fn polar_mace_conv_tp_scalar_l0123_plan_supported(
    plan: &e3nn_core::TensorProductPlan,
    output_mask: &[f64],
) -> bool {
    const CHANNELS: usize = 512;
    const EDGE_ATTR_DIM: usize = 16;
    const OUTPUT_DIM: usize = 8_192;
    const WEIGHT_NUMEL: usize = 2_048;
    const SH_BASES: [usize; 4] = [0, 1, 4, 9];
    const DIMS: [usize; 4] = [1, 3, 5, 7];
    if plan.input1_dim() != CHANNELS
        || plan.input2_dim() != EDGE_ATTR_DIM
        || plan.output_dim() != OUTPUT_DIM
        || plan.weight_numel != WEIGHT_NUMEL
        || plan.instructions.len() != WEIGHT_NUMEL
        || plan.cg_entries.len() != EDGE_ATTR_DIM
        || output_mask.len() != OUTPUT_DIM
        || !output_mask.iter().all(|&value| value == 1.0)
    {
        return false;
    }
    for degree in 0..4 {
        let dim = DIMS[degree];
        let cg_offset = SH_BASES[degree];
        let path_weight = (dim as f64).sqrt();
        let cg_value = 1.0 / path_weight;
        for component in 0..dim {
            let cg = &plan.cg_entries[cg_offset + component];
            if cg.i_m != 0
                || cg.j_m != component
                || cg.k_m != component
                || (cg.value - cg_value).abs() > 1.0e-14
            {
                return false;
            }
        }
        for channel in 0..CHANNELS {
            let instruction_index = degree * CHANNELS + channel;
            let instruction = &plan.instructions[instruction_index];
            if instruction.in1_segment != channel
                || instruction.in2_segment != degree
                || instruction.out_segment != degree * CHANNELS + channel
                || instruction.weight_offset != Some(instruction_index)
                || instruction.cg_offset != cg_offset
                || instruction.cg_len != dim
                || (instruction.path_weight - path_weight).abs() > 1.0e-14
            {
                return false;
            }
        }
    }
    true
}

#[allow(dead_code)]
fn polar_mace_incoming_edges_by_target(
    edge_index: &[[usize; 2]],
    node_count: usize,
    name: &str,
) -> Result<Vec<Vec<usize>>, MacePolarError> {
    let mut incoming = vec![Vec::new(); node_count];
    for (edge, &[_, target]) in edge_index.iter().enumerate() {
        let target_edges = incoming.get_mut(target).ok_or_else(|| {
            invalid(
                name,
                format!("edge {edge} target node {target} out of range"),
            )
        })?;
        target_edges.push(edge);
    }
    Ok(incoming)
}

#[allow(dead_code)]
#[inline(always)]
fn polar_mace_conv_tp_scalar_l0123_accumulate_edge(
    source_row: &[f64],
    edge_attr: &[f64],
    weight: &[f64],
    target_row: &mut [f64],
) {
    const CHANNELS: usize = 512;
    const L0_OUT: usize = 0;
    const L1_OUT: usize = 512;
    const L2_OUT: usize = 2_048;
    const L3_OUT: usize = 4_608;
    const W0: usize = 0;
    const W1: usize = 512;
    const W2: usize = 1_024;
    const W3: usize = 1_536;
    let y0 = edge_attr[0];
    let y1 = &edge_attr[1..4];
    let y2 = &edge_attr[4..9];
    let y3 = &edge_attr[9..16];
    for channel in 0..CHANNELS {
        let x = source_row[channel];
        target_row[L0_OUT + channel] += x * weight[W0 + channel] * y0;

        let scale1 = x * weight[W1 + channel];
        let out1 = L1_OUT + channel * 3;
        target_row[out1] += scale1 * y1[0];
        target_row[out1 + 1] += scale1 * y1[1];
        target_row[out1 + 2] += scale1 * y1[2];

        let scale2 = x * weight[W2 + channel];
        let out2 = L2_OUT + channel * 5;
        target_row[out2] += scale2 * y2[0];
        target_row[out2 + 1] += scale2 * y2[1];
        target_row[out2 + 2] += scale2 * y2[2];
        target_row[out2 + 3] += scale2 * y2[3];
        target_row[out2 + 4] += scale2 * y2[4];

        let scale3 = x * weight[W3 + channel];
        let out3 = L3_OUT + channel * 7;
        target_row[out3] += scale3 * y3[0];
        target_row[out3 + 1] += scale3 * y3[1];
        target_row[out3 + 2] += scale3 * y3[2];
        target_row[out3 + 3] += scale3 * y3[3];
        target_row[out3 + 4] += scale3 * y3[4];
        target_row[out3 + 5] += scale3 * y3[5];
        target_row[out3 + 6] += scale3 * y3[6];
    }
}

#[allow(dead_code)]
#[inline(always)]
fn polar_mace_conv_tp_scalar_l0123_accumulate_edge_raw_cutoff(
    source_row: &[f64],
    edge_attr: &[f64],
    raw_weight: &[f64],
    cutoff: f64,
    target_row: &mut [f64],
) {
    const CHANNELS: usize = 512;
    const L0_OUT: usize = 0;
    const L1_OUT: usize = 512;
    const L2_OUT: usize = 2_048;
    const L3_OUT: usize = 4_608;
    const W0: usize = 0;
    const W1: usize = 512;
    const W2: usize = 1_024;
    const W3: usize = 1_536;
    let y0 = edge_attr[0];
    let y1 = &edge_attr[1..4];
    let y2 = &edge_attr[4..9];
    let y3 = &edge_attr[9..16];
    for channel in 0..CHANNELS {
        let x = source_row[channel];
        target_row[L0_OUT + channel] += x * raw_weight[W0 + channel] * cutoff * y0;

        let scale1 = x * raw_weight[W1 + channel] * cutoff;
        let out1 = L1_OUT + channel * 3;
        target_row[out1] += scale1 * y1[0];
        target_row[out1 + 1] += scale1 * y1[1];
        target_row[out1 + 2] += scale1 * y1[2];

        let scale2 = x * raw_weight[W2 + channel] * cutoff;
        let out2 = L2_OUT + channel * 5;
        target_row[out2] += scale2 * y2[0];
        target_row[out2 + 1] += scale2 * y2[1];
        target_row[out2 + 2] += scale2 * y2[2];
        target_row[out2 + 3] += scale2 * y2[3];
        target_row[out2 + 4] += scale2 * y2[4];

        let scale3 = x * raw_weight[W3 + channel] * cutoff;
        let out3 = L3_OUT + channel * 7;
        target_row[out3] += scale3 * y3[0];
        target_row[out3 + 1] += scale3 * y3[1];
        target_row[out3 + 2] += scale3 * y3[2];
        target_row[out3 + 3] += scale3 * y3[3];
        target_row[out3 + 4] += scale3 * y3[4];
        target_row[out3 + 5] += scale3 * y3[5];
        target_row[out3 + 6] += scale3 * y3[6];
    }
}

#[allow(dead_code)]
fn polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows_raw_cutoff(
    edge_index: &[[usize; 2]],
    linear_up: &[Vec<f64>],
    edge_attrs: &[Vec<f64>],
    raw_weights_flat: &[f64],
    cutoffs: &[f64],
    node_count: usize,
) -> Result<MacePolarRows, MacePolarError> {
    const INPUT_DIM: usize = 512;
    const EDGE_ATTR_DIM: usize = 16;
    const WEIGHT_NUMEL: usize = 2_048;
    const OUTPUT_DIM: usize = 8_192;
    require_usize(
        "conv_tp.raw_cutoff.edge_attrs.len",
        edge_attrs.len(),
        edge_index.len(),
    )?;
    require_usize(
        "conv_tp.raw_cutoff.cutoffs.len",
        cutoffs.len(),
        edge_index.len(),
    )?;
    polar_mace_require_hot_len(
        "conv_tp.raw_cutoff",
        "raw_weights_flat.len",
        raw_weights_flat.len(),
        edge_index.len() * WEIGHT_NUMEL,
    )?;
    require_usize(
        "conv_tp.raw_cutoff.linear_up.len",
        linear_up.len(),
        node_count,
    )?;
    for (node, row) in linear_up.iter().enumerate() {
        polar_mace_require_hot_row_len(
            "conv_tp.raw_cutoff",
            "linear_up",
            node,
            row.len(),
            INPUT_DIM,
        )?;
    }
    for (edge, edge_attr) in edge_attrs.iter().enumerate() {
        polar_mace_require_hot_row_len(
            "conv_tp.raw_cutoff",
            "edge_attrs",
            edge,
            edge_attr.len(),
            EDGE_ATTR_DIM,
        )?;
    }

    let mut scatter = vec![vec![0.0_f64; OUTPUT_DIM]; node_count];
    #[cfg(feature = "parallel")]
    if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
        let incoming =
            polar_mace_incoming_edges_by_target(edge_index, node_count, "conv_tp.raw_cutoff")?;
        scatter.par_iter_mut().enumerate().try_for_each(
            |(target, target_row)| -> Result<(), MacePolarError> {
                for &edge in &incoming[target] {
                    let [source, _] = edge_index[edge];
                    let source_row = linear_up.get(source).ok_or_else(|| {
                        invalid(
                            "conv_tp.raw_cutoff",
                            format!("source node {source} out of range"),
                        )
                    })?;
                    let weight_start = edge * WEIGHT_NUMEL;
                    polar_mace_conv_tp_scalar_l0123_accumulate_edge_raw_cutoff(
                        source_row,
                        &edge_attrs[edge],
                        &raw_weights_flat[weight_start..weight_start + WEIGHT_NUMEL],
                        cutoffs[edge],
                        target_row,
                    );
                }
                Ok(())
            },
        )?;
        return Ok(scatter);
    }

    for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
        let source_row = linear_up.get(source).ok_or_else(|| {
            invalid(
                "conv_tp.raw_cutoff",
                format!("source node {source} out of range"),
            )
        })?;
        let target_row = scatter.get_mut(target).ok_or_else(|| {
            invalid(
                "conv_tp.raw_cutoff",
                format!("target node {target} out of range"),
            )
        })?;
        let weight_start = edge * WEIGHT_NUMEL;
        polar_mace_conv_tp_scalar_l0123_accumulate_edge_raw_cutoff(
            source_row,
            &edge_attrs[edge],
            &raw_weights_flat[weight_start..weight_start + WEIGHT_NUMEL],
            cutoffs[edge],
            target_row,
        );
    }
    Ok(scatter)
}

