#[allow(dead_code)]
fn polar_mace_conv_tp_message_and_scatter_rows_generic_f32_for_layer(
    plan: &e3nn_core::TensorProductPlan,
    output_mask: &[f64],
    edge_index: &[[usize; 2]],
    linear_up: &[Vec<f32>],
    edge_attrs: &[Vec<f32>],
    weights: &[Vec<f32>],
    node_count: usize,
) -> Result<Vec<Vec<f32>>, MacePolarError> {
    let layouts = plan
        .checked_layouts()
        .map_err(|err| invalid("conv_tp_f32.layouts", err.to_string()))?;
    let output_mask_all_one = output_mask.iter().all(|&value| value == 1.0);
    require_usize(
        "conv_tp_f32.edge_attrs.len",
        edge_attrs.len(),
        edge_index.len(),
    )?;
    require_usize("conv_tp_f32.weights.len", weights.len(), edge_index.len())?;
    require_usize("conv_tp_f32.linear_up.len", linear_up.len(), node_count)?;
    require_usize(
        "conv_tp_f32.output_mask.len",
        output_mask.len(),
        plan.output_dim(),
    )?;

    let mut scatter = vec![vec![0.0_f32; plan.output_dim()]; node_count];
    #[cfg(feature = "parallel")]
    if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
        let incoming = polar_mace_incoming_edges_by_target(edge_index, node_count, "conv_tp_f32")?;
        scatter.par_iter_mut().enumerate().try_for_each(
            |(target, target_row)| -> Result<(), MacePolarError> {
                for &edge in &incoming[target] {
                    let [source, _] = edge_index[edge];
                    let source_row = linear_up.get(source).ok_or_else(|| {
                        invalid("conv_tp_f32", format!("source node {source} out of range"))
                    })?;
                    require_usize(
                        "conv_tp_f32.source_width",
                        source_row.len(),
                        plan.input1_dim(),
                    )?;
                    require_usize(
                        "conv_tp_f32.edge_attr_width",
                        edge_attrs[edge].len(),
                        plan.input2_dim(),
                    )?;
                    require_usize(
                        "conv_tp_f32.weight_width",
                        weights[edge].len(),
                        plan.weight_numel,
                    )?;
                    if output_mask_all_one {
                        polar_mace_tensor_product_forward_unmasked_f32(
                            plan,
                            &layouts,
                            source_row,
                            &edge_attrs[edge],
                            &weights[edge],
                            target_row,
                        );
                    } else {
                        polar_mace_tensor_product_forward_masked_f32(
                            plan,
                            &layouts,
                            source_row,
                            &edge_attrs[edge],
                            &weights[edge],
                            output_mask,
                            target_row,
                        );
                    }
                }
                Ok(())
            },
        )?;
        return Ok(scatter);
    }

    for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
        let source_row = linear_up
            .get(source)
            .ok_or_else(|| invalid("conv_tp_f32", format!("source node {source} out of range")))?;
        let target_row = scatter.get_mut(target).ok_or_else(|| {
            invalid(
                "conv_tp_f32.scatter",
                format!("target node {target} out of range"),
            )
        })?;
        require_usize(
            "conv_tp_f32.source_width",
            source_row.len(),
            plan.input1_dim(),
        )?;
        require_usize(
            "conv_tp_f32.edge_attr_width",
            edge_attrs[edge].len(),
            plan.input2_dim(),
        )?;
        require_usize(
            "conv_tp_f32.weight_width",
            weights[edge].len(),
            plan.weight_numel,
        )?;
        if output_mask_all_one {
            polar_mace_tensor_product_forward_unmasked_f32(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                target_row,
            );
        } else {
            polar_mace_tensor_product_forward_masked_f32(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                output_mask,
                target_row,
            );
        }
    }
    Ok(scatter)
}

