        let bar22 = target_cotangent[out2 + 2];
        let bar23 = target_cotangent[out2 + 3];
        let bar24 = target_cotangent[out2 + 4];
        let dot2 = edge_attr[4] * bar20
            + edge_attr[5] * bar21
            + edge_attr[6] * bar22
            + edge_attr[7] * bar23
            + edge_attr[8] * bar24;
        let w2 = raw_weight[W2 + channel] * cutoff;
        bar_x += w2 * dot2;
        weight_cotangent[W2 + channel] += x * dot2;
        let scale2 = x * w2;
        edge_attr_cotangent[4] += scale2 * bar20;
        edge_attr_cotangent[5] += scale2 * bar21;
        edge_attr_cotangent[6] += scale2 * bar22;
        edge_attr_cotangent[7] += scale2 * bar23;
        edge_attr_cotangent[8] += scale2 * bar24;

        let out3 = L3_OUT + channel * 7;
        let bar30 = target_cotangent[out3];
        let bar31 = target_cotangent[out3 + 1];
        let bar32 = target_cotangent[out3 + 2];
        let bar33 = target_cotangent[out3 + 3];
        let bar34 = target_cotangent[out3 + 4];
        let bar35 = target_cotangent[out3 + 5];
        let bar36 = target_cotangent[out3 + 6];
        let dot3 = edge_attr[9] * bar30
            + edge_attr[10] * bar31
            + edge_attr[11] * bar32
            + edge_attr[12] * bar33
            + edge_attr[13] * bar34
            + edge_attr[14] * bar35
            + edge_attr[15] * bar36;
        let w3 = raw_weight[W3 + channel] * cutoff;
        bar_x += w3 * dot3;
        weight_cotangent[W3 + channel] += x * dot3;
        let scale3 = x * w3;
        edge_attr_cotangent[9] += scale3 * bar30;
        edge_attr_cotangent[10] += scale3 * bar31;
        edge_attr_cotangent[11] += scale3 * bar32;
        edge_attr_cotangent[12] += scale3 * bar33;
        edge_attr_cotangent[13] += scale3 * bar34;
        edge_attr_cotangent[14] += scale3 * bar35;
