#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_conv_tp_message_and_scatter_rows_for_layer(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    plan: &e3nn_core::TensorProductPlan,
    edge_index: &[[usize; 2]],
    linear_up: &[Vec<f64>],
    edge_attrs: &[Vec<f64>],
    weights: &[Vec<f64>],
    node_count: usize,
    retain_edge_messages: bool,
) -> Result<(MacePolarRows, MacePolarRows), MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let output_mask = access.f64(
        &format!("interactions.{layer}.conv_tp.output_mask"),
        &[plan.output_dim()],
    )?;
    let layouts = plan
        .checked_layouts()
        .map_err(|err| invalid("conv_tp.layouts", err.to_string()))?;
    let output_mask_all_one = output_mask.iter().all(|&value| value == 1.0);
    require_usize("conv_tp.edge_attrs.len", edge_attrs.len(), edge_index.len())?;
    require_usize("conv_tp.weights.len", weights.len(), edge_index.len())?;

    if !retain_edge_messages {
        if polar_mace_conv_tp_scalar_l0123_plan_supported(plan, output_mask) {
            let scatter = polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows(
                edge_index, linear_up, edge_attrs, weights, node_count,
            )?;
            return Ok((Vec::new(), scatter));
        }

        let mut scatter = vec![vec![0.0_f64; plan.output_dim()]; node_count];
        #[cfg(feature = "parallel")]
        if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
            scatter.par_iter_mut().enumerate().try_for_each(
                |(target, target_row)| -> Result<(), MacePolarError> {
                    for (edge, [source, edge_target]) in edge_index.iter().copied().enumerate() {
                        if edge_target != target {
                            continue;
                        }
                        let source_row = linear_up.get(source).ok_or_else(|| {
                            invalid("conv_tp", format!("source node {source} out of range"))
                        })?;
                        require_usize("conv_tp.source_width", source_row.len(), plan.input1_dim())?;
                        require_usize(
                            "conv_tp.edge_attr_width",
                            edge_attrs[edge].len(),
                            plan.input2_dim(),
                        )?;
                        require_usize(
                            "conv_tp.weight_width",
                            weights[edge].len(),
                            plan.weight_numel,
                        )?;
                        if output_mask_all_one {
                            polar_mace_tensor_product_forward_unmasked(
                                plan,
                                &layouts,
                                source_row,
                                &edge_attrs[edge],
                                &weights[edge],
                                target_row,
                            );
                        } else {
                            polar_mace_tensor_product_forward_masked(
                                plan,
                                &layouts,
                                source_row,
                                &edge_attrs[edge],
                                &weights[edge],
                                output_mask,
                                target_row,
                            );
                        }
                    }
                    Ok(())
                },
            )?;
            return Ok((Vec::new(), scatter));
        }

        for (target, target_row) in scatter.iter_mut().enumerate() {
            for (edge, [source, edge_target]) in edge_index.iter().copied().enumerate() {
                if edge_target != target {
                    continue;
                }
                let source_row = linear_up.get(source).ok_or_else(|| {
                    invalid("conv_tp", format!("source node {source} out of range"))
                })?;
                require_usize("conv_tp.source_width", source_row.len(), plan.input1_dim())?;
                require_usize(
                    "conv_tp.edge_attr_width",
                    edge_attrs[edge].len(),
                    plan.input2_dim(),
                )?;
                require_usize(
                    "conv_tp.weight_width",
                    weights[edge].len(),
                    plan.weight_numel,
                )?;
                if output_mask_all_one {
                    polar_mace_tensor_product_forward_unmasked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        target_row,
                    );
                } else {
                    polar_mace_tensor_product_forward_masked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        output_mask,
                        target_row,
                    );
                }
            }
        }
        return Ok((Vec::new(), scatter));
    }

    #[cfg(feature = "parallel")]
    if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
        let edge_messages = (0..edge_index.len())
            .into_par_iter()
            .map(|edge| {
                let [source, _target] = edge_index[edge];
                let source_row = linear_up.get(source).ok_or_else(|| {
                    invalid("conv_tp", format!("source node {source} out of range"))
                })?;
                require_usize("conv_tp.source_width", source_row.len(), plan.input1_dim())?;
                require_usize(
                    "conv_tp.edge_attr_width",
                    edge_attrs[edge].len(),
                    plan.input2_dim(),
                )?;
                require_usize(
                    "conv_tp.weight_width",
                    weights[edge].len(),
                    plan.weight_numel,
                )?;

                let mut message = vec![0.0_f64; plan.output_dim()];
                if output_mask_all_one {
                    polar_mace_tensor_product_forward_unmasked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        &mut message,
                    );
                } else {
                    polar_mace_tensor_product_forward_masked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        output_mask,
                        &mut message,
                    );
                }
                Ok(message)
            })
            .collect::<Result<Vec<_>, MacePolarError>>()?;

        let mut scatter = vec![vec![0.0_f64; plan.output_dim()]; node_count];
        for (edge, [_, target]) in edge_index.iter().copied().enumerate() {
            let target_row = scatter.get_mut(target).ok_or_else(|| {
                invalid(
                    "conv_tp.scatter",
                    format!("target node {target} out of range"),
                )
            })?;
            for (value, message) in target_row.iter_mut().zip(&edge_messages[edge]) {
                *value += *message;
            }
        }
        return Ok((edge_messages, scatter));
    }

    let mut edge_messages = Vec::with_capacity(edge_index.len());
    for (edge, [source, _target]) in edge_index.iter().copied().enumerate() {
        let source_row = linear_up
            .get(source)
            .ok_or_else(|| invalid("conv_tp", format!("source node {source} out of range")))?;
        require_usize("conv_tp.source_width", source_row.len(), plan.input1_dim())?;
        require_usize(
            "conv_tp.edge_attr_width",
            edge_attrs[edge].len(),
            plan.input2_dim(),
        )?;
        require_usize(
            "conv_tp.weight_width",
            weights[edge].len(),
            plan.weight_numel,
        )?;

        let mut message = vec![0.0_f64; plan.output_dim()];
        if output_mask_all_one {
            polar_mace_tensor_product_forward_unmasked(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                &mut message,
            );
        } else {
            polar_mace_tensor_product_forward_masked(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                output_mask,
                &mut message,
            );
        }
        edge_messages.push(message);
    }

    let mut scatter = vec![vec![0.0_f64; plan.output_dim()]; node_count];
    for (edge, [_, target]) in edge_index.iter().copied().enumerate() {
        let target_row = scatter.get_mut(target).ok_or_else(|| {
            invalid(
                "conv_tp.scatter",
                format!("target node {target} out of range"),
            )
        })?;
        for (value, message) in target_row.iter_mut().zip(&edge_messages[edge]) {
            *value += *message;
        }
    }
    Ok((edge_messages, scatter))
}

