        let dot1 = edge_attr[1] * bar10 + edge_attr[2] * bar11 + edge_attr[3] * bar12;
        let w1 = weight[W1 + channel];
        bar_x += w1 * dot1;
        weight_cotangent[W1 + channel] += x * dot1;
        let scale1 = x * w1;
        edge_attr_cotangent[1] += scale1 * bar10;
        edge_attr_cotangent[2] += scale1 * bar11;
        edge_attr_cotangent[3] += scale1 * bar12;

        let out2 = L2_OUT + channel * 5;
