#[allow(dead_code)]
fn polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows_vjp_raw_cutoff(
    edge_index: &[[usize; 2]],
    linear_up: &[Vec<f64>],
    edge_attrs: &[Vec<f64>],
    raw_weights_flat: &[f64],
    cutoffs: &[f64],
    scatter_cotangent: &[Vec<f64>],
    node_count: usize,
) -> Result<MacePolarConvTpCotangents, MacePolarError> {
    const INPUT_DIM: usize = 512;
    const EDGE_ATTR_DIM: usize = 16;
    const WEIGHT_NUMEL: usize = 2_048;
    const OUTPUT_DIM: usize = 8_192;
    require_usize(
        "conv_tp_vjp.raw_cutoff.edge_attrs.len",
        edge_attrs.len(),
        edge_index.len(),
    )?;
    require_usize(
        "conv_tp_vjp.raw_cutoff.cutoffs.len",
        cutoffs.len(),
        edge_index.len(),
    )?;
    polar_mace_require_hot_len(
        "conv_tp_vjp.raw_cutoff",
        "raw_weights_flat.len",
        raw_weights_flat.len(),
        edge_index.len() * WEIGHT_NUMEL,
    )?;
    require_usize(
        "conv_tp_vjp.raw_cutoff.scatter_cotangent.len",
        scatter_cotangent.len(),
        node_count,
    )?;
    require_usize(
        "conv_tp_vjp.raw_cutoff.linear_up.len",
        linear_up.len(),
        node_count,
    )?;
    for (node, row) in linear_up.iter().enumerate() {
        polar_mace_require_hot_row_len(
            "conv_tp_vjp.raw_cutoff",
            "linear_up",
            node,
            row.len(),
            INPUT_DIM,
        )?;
    }
    for (node, row) in scatter_cotangent.iter().enumerate() {
        polar_mace_require_hot_row_len(
            "conv_tp_vjp.raw_cutoff",
            "scatter_cotangent",
            node,
            row.len(),
            OUTPUT_DIM,
        )?;
    }
    for (edge, edge_attr) in edge_attrs.iter().enumerate() {
        polar_mace_require_hot_row_len(
            "conv_tp_vjp.raw_cutoff",
            "edge_attrs",
            edge,
            edge_attr.len(),
            EDGE_ATTR_DIM,
        )?;
    }
    for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
        if source >= linear_up.len() {
            return Err(invalid(
                "conv_tp_vjp.raw_cutoff",
                format!("edge {edge} source node {source} out of range"),
            ));
        }
        if target >= scatter_cotangent.len() {
            return Err(invalid(
                "conv_tp_vjp.raw_cutoff",
                format!("edge {edge} target node {target} out of range"),
            ));
        }
    }

    let mut edge_attrs_cotangent = polar_mace_zero_rows_like(edge_attrs);
    let mut weights_cotangent = vec![vec![0.0_f64; WEIGHT_NUMEL]; edge_index.len()];
    #[cfg(feature = "parallel")]
    let linear_up_cotangent = if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
        let flat_len = node_count * INPUT_DIM;
        let chunk_size = edge_index
            .len()
            .div_ceil(rayon::current_num_threads().saturating_mul(2))
            .max(1);
        let flat_linear_up_cotangent = edge_attrs_cotangent
            .par_chunks_mut(chunk_size)
            .zip(weights_cotangent.par_chunks_mut(chunk_size))
            .enumerate()
            .map(|(chunk_index, (edge_attr_chunk, weight_chunk))| {
                let mut local_linear_up_cotangent = vec![0.0_f64; flat_len];
                for (offset, (edge_attr_cotangent, weight_cotangent)) in
                    edge_attr_chunk.iter_mut().zip(weight_chunk).enumerate()
                {
                    let edge = chunk_index * chunk_size + offset;
                    let [source, target] = edge_index[edge];
                    let source_start = source * INPUT_DIM;
                    let weight_start = edge * WEIGHT_NUMEL;
                    polar_mace_conv_tp_scalar_l0123_edge_vjp_raw_cutoff(
                        &linear_up[source],
                        &edge_attrs[edge],
                        &raw_weights_flat[weight_start..weight_start + WEIGHT_NUMEL],
                        cutoffs[edge],
                        &scatter_cotangent[target],
                        &mut local_linear_up_cotangent[source_start..source_start + INPUT_DIM],
                        edge_attr_cotangent,
                        weight_cotangent,
                    );
                }
                local_linear_up_cotangent
            })
            .reduce(
                || vec![0.0_f64; flat_len],
                |mut left, right| {
                    for (target, value) in left.iter_mut().zip(right) {
                        *target += value;
                    }
                    left
                },
            );
        flat_linear_up_cotangent
            .chunks_exact(INPUT_DIM)
            .map(<[f64]>::to_vec)
            .collect()
    } else {
        let mut linear_up_cotangent = polar_mace_zero_rows_like(linear_up);
        for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
            let weight_start = edge * WEIGHT_NUMEL;
            polar_mace_conv_tp_scalar_l0123_edge_vjp_raw_cutoff(
                &linear_up[source],
                &edge_attrs[edge],
                &raw_weights_flat[weight_start..weight_start + WEIGHT_NUMEL],
                cutoffs[edge],
                &scatter_cotangent[target],
                &mut linear_up_cotangent[source],
                &mut edge_attrs_cotangent[edge],
                &mut weights_cotangent[edge],
            );
        }
        linear_up_cotangent
    };
    #[cfg(not(feature = "parallel"))]
    let linear_up_cotangent = {
        let mut linear_up_cotangent = polar_mace_zero_rows_like(linear_up);
        for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
            let weight_start = edge * WEIGHT_NUMEL;
            polar_mace_conv_tp_scalar_l0123_edge_vjp_raw_cutoff(
                &linear_up[source],
                &edge_attrs[edge],
                &raw_weights_flat[weight_start..weight_start + WEIGHT_NUMEL],
                cutoffs[edge],
                &scatter_cotangent[target],
                &mut linear_up_cotangent[source],
                &mut edge_attrs_cotangent[edge],
                &mut weights_cotangent[edge],
            );
        }
        linear_up_cotangent
    };
    Ok(MacePolarConvTpCotangents {
        linear_up: linear_up_cotangent,
        edge_attrs: edge_attrs_cotangent,
        weights: weights_cotangent,
    })
}

