#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_conv_tp_message_and_scatter_rows_vjp_for_layer(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    plan: &e3nn_core::TensorProductPlan,
    edge_index: &[[usize; 2]],
    linear_up: &[Vec<f64>],
    edge_attrs: &[Vec<f64>],
    weights: &[Vec<f64>],
    scatter_cotangent: &[Vec<f64>],
    node_count: usize,
) -> Result<MacePolarConvTpCotangents, MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let output_mask = access.f64(
        &format!("interactions.{layer}.conv_tp.output_mask"),
        &[plan.output_dim()],
    )?;
    let layouts = plan
        .checked_layouts()
        .map_err(|err| invalid("conv_tp_vjp.layouts", err.to_string()))?;
    let output_mask_all_one = output_mask.iter().all(|&value| value == 1.0);
    require_usize(
        "conv_tp_vjp.edge_attrs.len",
        edge_attrs.len(),
        edge_index.len(),
    )?;
    require_usize("conv_tp_vjp.weights.len", weights.len(), edge_index.len())?;
    require_usize(
        "conv_tp_vjp.scatter_cotangent.len",
        scatter_cotangent.len(),
        node_count,
    )?;
    require_usize("conv_tp_vjp.linear_up.len", linear_up.len(), node_count)?;

    if polar_mace_conv_tp_scalar_l0123_plan_supported(plan, output_mask) {
        return polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows_vjp(
            edge_index,
            linear_up,
            edge_attrs,
            weights,
            scatter_cotangent,
            node_count,
        );
    }

    let mut linear_up_cotangent = polar_mace_zero_rows_like(linear_up);
    let mut edge_attrs_cotangent = polar_mace_zero_rows_like(edge_attrs);
    let mut weights_cotangent = polar_mace_zero_rows_like(weights);
    #[cfg(feature = "parallel")]
    if edge_index.len() >= 16 && rayon::current_num_threads() > 1 {
        let edge_linear_cotangents = edge_attrs_cotangent
            .par_iter_mut()
            .zip(weights_cotangent.par_iter_mut())
            .enumerate()
            .map(|(edge, (edge_attr_cotangent, edge_weight_cotangent))| {
                let [source, target] = edge_index[edge];
                let source_row = linear_up.get(source).ok_or_else(|| {
                    invalid("conv_tp_vjp", format!("source node {source} out of range"))
                })?;
                let target_cotangent = scatter_cotangent.get(target).ok_or_else(|| {
                    invalid(
                        "conv_tp_vjp.scatter",
                        format!("target node {target} out of range"),
                    )
                })?;
                require_usize(
                    "conv_tp_vjp.source_width",
                    source_row.len(),
                    plan.input1_dim(),
                )?;
                require_usize(
                    "conv_tp_vjp.edge_attr_width",
                    edge_attrs[edge].len(),
                    plan.input2_dim(),
                )?;
                require_usize(
                    "conv_tp_vjp.weight_width",
                    weights[edge].len(),
                    plan.weight_numel,
                )?;
                require_usize(
                    &format!("conv_tp_vjp.scatter_cotangent[{target}].len"),
                    target_cotangent.len(),
                    plan.output_dim(),
                )?;
                let mut edge_linear_up_cotangent = vec![0.0_f64; plan.input1_dim()];
                if output_mask_all_one {
                    polar_mace_tensor_product_vjp_unmasked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        target_cotangent,
                        &mut edge_linear_up_cotangent,
                        edge_attr_cotangent,
                        edge_weight_cotangent,
                    );
                } else {
                    polar_mace_tensor_product_vjp_masked(
                        plan,
                        &layouts,
                        source_row,
                        &edge_attrs[edge],
                        &weights[edge],
                        target_cotangent,
                        output_mask,
                        &mut edge_linear_up_cotangent,
                        edge_attr_cotangent,
                        edge_weight_cotangent,
                    );
                }
                Ok((source, edge_linear_up_cotangent))
            })
            .collect::<Result<Vec<_>, MacePolarError>>()?;
        for (source, edge_linear_up_cotangent) in edge_linear_cotangents {
            for component in 0..plan.input1_dim() {
                linear_up_cotangent[source][component] += edge_linear_up_cotangent[component];
            }
        }
        return Ok(MacePolarConvTpCotangents {
            linear_up: linear_up_cotangent,
            edge_attrs: edge_attrs_cotangent,
            weights: weights_cotangent,
        });
    }
    for (edge, [source, target]) in edge_index.iter().copied().enumerate() {
        let source_row = linear_up
            .get(source)
            .ok_or_else(|| invalid("conv_tp_vjp", format!("source node {source} out of range")))?;
        let target_cotangent = scatter_cotangent.get(target).ok_or_else(|| {
            invalid(
                "conv_tp_vjp.scatter",
                format!("target node {target} out of range"),
            )
        })?;
        require_usize(
            "conv_tp_vjp.source_width",
            source_row.len(),
            plan.input1_dim(),
        )?;
        require_usize(
            "conv_tp_vjp.edge_attr_width",
            edge_attrs[edge].len(),
            plan.input2_dim(),
        )?;
        require_usize(
            "conv_tp_vjp.weight_width",
            weights[edge].len(),
            plan.weight_numel,
        )?;
        require_usize(
            &format!("conv_tp_vjp.scatter_cotangent[{target}].len"),
            target_cotangent.len(),
            plan.output_dim(),
        )?;
        let mut edge_linear_up_cotangent = vec![0.0_f64; plan.input1_dim()];
        let mut edge_attr_cotangent = vec![0.0_f64; plan.input2_dim()];
        let mut edge_weight_cotangent = vec![0.0_f64; plan.weight_numel];
        if output_mask_all_one {
            polar_mace_tensor_product_vjp_unmasked(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                target_cotangent,
                &mut edge_linear_up_cotangent,
                &mut edge_attr_cotangent,
                &mut edge_weight_cotangent,
            );
        } else {
            polar_mace_tensor_product_vjp_masked(
                plan,
                &layouts,
                source_row,
                &edge_attrs[edge],
                &weights[edge],
                target_cotangent,
                output_mask,
                &mut edge_linear_up_cotangent,
                &mut edge_attr_cotangent,
                &mut edge_weight_cotangent,
            );
        }
        for component in 0..plan.input1_dim() {
            linear_up_cotangent[source][component] += edge_linear_up_cotangent[component];
        }
        for component in 0..plan.input2_dim() {
            edge_attrs_cotangent[edge][component] += edge_attr_cotangent[component];
        }
        for component in 0..plan.weight_numel {
            weights_cotangent[edge][component] += edge_weight_cotangent[component];
        }
    }
    Ok(MacePolarConvTpCotangents {
        linear_up: linear_up_cotangent,
        edge_attrs: edge_attrs_cotangent,
        weights: weights_cotangent,
    })
}

#[allow(dead_code)]
fn polar_mace_e3nn_block_linear_rows(
    input_rows: &[Vec<f64>],
    spec: MacePolarBlockLinearSpec<'_>,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{}.output_mask.len", spec.name),
        spec.output_mask.len(),
        spec.output_dim,
    )?;
    if !spec.bias.is_empty() && spec.bias.len() != spec.output_dim {
        return Err(invalid(
            spec.name,
            format!(
                "expected bias length 0 or {}, got {}",
                spec.output_dim,
                spec.bias.len()
            ),
        ));
    }
    let expected_weight_len = spec
        .instructions
        .iter()
        .map(|instruction| {
            instruction.weight_offset + instruction.input_mul * instruction.output_mul
        })
        .max()
        .unwrap_or(0);
    require_usize(
        &format!("{}.weight.len", spec.name),
        spec.weight.len(),
        expected_weight_len,
    )?;
    if let Some(path_weights) = spec.instruction_path_weights {
        require_usize(
            &format!("{}.instruction_path_weights.len", spec.name),
            path_weights.len(),
            spec.instructions.len(),
        )?;
    }
    for (row_index, input_row) in input_rows.iter().enumerate() {
        require_usize(
            &format!("{}.input_rows[{row_index}].len", spec.name),
            input_row.len(),
            spec.input_dim,
        )?;
    }
    for instruction in spec.instructions {
        let input_end = instruction.input_start + instruction.input_mul * instruction.irrep_dim;
        let output_end = instruction.output_start + instruction.output_mul * instruction.irrep_dim;
        if input_end > spec.input_dim || output_end > spec.output_dim {
            return Err(invalid(
                spec.name,
                format!(
                    "block instruction exceeds dimensions: input_end={input_end} input_dim={} output_end={output_end} output_dim={}",
                    spec.input_dim, spec.output_dim
                ),
            ));
        }
        if instruction.input_mul == 0 {
            return Err(invalid(
                spec.name,
                "block instruction input multiplicity must be non-zero",
            ));
        }
    }

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    {
        Ok(polar_mace_e3nn_block_linear_rows_accelerate(
            input_rows, &spec,
        ))
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    {
        let mut output_rows = Vec::with_capacity(input_rows.len());
        for (row_index, input_row) in input_rows.iter().enumerate() {
            require_usize(
                &format!("{}.input_rows[{row_index}].len", spec.name),
                input_row.len(),
                spec.input_dim,
            )?;
            let mut output = vec![0.0_f64; spec.output_dim];
            for (index, value) in spec.bias.iter().enumerate() {
                output[index] = *value;
            }

            for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
                let input_end =
                    instruction.input_start + instruction.input_mul * instruction.irrep_dim;
                let output_end =
                    instruction.output_start + instruction.output_mul * instruction.irrep_dim;
                if input_end > spec.input_dim || output_end > spec.output_dim {
                    return Err(invalid(
                        spec.name,
                        format!(
                            "block instruction exceeds dimensions: input_end={input_end} input_dim={} output_end={output_end} output_dim={}",
                            spec.input_dim, spec.output_dim
                        ),
                    ));
                }
                if instruction.input_mul == 0 {
                    return Err(invalid(
                        spec.name,
                        "block instruction input multiplicity must be non-zero",
                    ));
                }
                let path_weight = spec.instruction_path_weights.map_or_else(
                    || 1.0 / (instruction.input_mul as f64).sqrt(),
                    |path_weights| path_weights[instruction_index],
                );
                for output_mul in 0..instruction.output_mul {
                    for input_mul in 0..instruction.input_mul {
                        let weight_value = spec.weight[instruction.weight_offset
                            + input_mul * instruction.output_mul
                            + output_mul];
                        for component in 0..instruction.irrep_dim {
                            let input_index = instruction.input_start
                                + input_mul * instruction.irrep_dim
                                + component;
                            let output_index = instruction.output_start
                                + output_mul * instruction.irrep_dim
                                + component;
                            output[output_index] = (path_weight * input_row[input_index])
                                .mul_add(weight_value, output[output_index]);
                        }
                    }
                }
            }
            for (value, mask) in output.iter_mut().zip(spec.output_mask) {
                *value *= *mask;
            }
            output_rows.push(output);
        }
        Ok(output_rows)
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(feature = "openblas", target_os = "linux", target_arch = "aarch64"),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn polar_mace_e3nn_block_linear_rows_accelerate(
    input_rows: &[Vec<f64>],
    spec: &MacePolarBlockLinearSpec<'_>,
) -> MacePolarRows {
    let row_count = input_rows.len();
    if row_count == 0 {
        return Vec::new();
    }

    let mut input_flat = vec![0.0_f64; row_count * spec.input_dim];
    for (row_index, input_row) in input_rows.iter().enumerate() {
        let start = row_index * spec.input_dim;
        input_flat[start..start + spec.input_dim].copy_from_slice(input_row);
    }

    let output_mask_all_one = spec.output_mask.iter().all(|&value| value == 1.0);
    let mut output_flat = vec![0.0_f64; row_count * spec.output_dim];
    if !spec.bias.is_empty() {
        for row in 0..row_count {
            let start = row * spec.output_dim;
            output_flat[start..start + spec.output_dim].copy_from_slice(spec.bias);
        }
    }

    for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
        let path_weight = spec.instruction_path_weights.map_or_else(
            || 1.0 / (instruction.input_mul as f64).sqrt(),
            |path_weights| path_weights[instruction_index],
        );
        if instruction.irrep_dim == 1 {
            let weight_start = instruction.weight_offset;
            let weight_end = weight_start + instruction.input_mul * instruction.output_mul;
            blas_backend::dense_forward_strided_row_parallel_f64(
                &input_flat[instruction.input_start..],
                row_count,
                instruction.input_mul,
                spec.input_dim,
                &spec.weight[weight_start..weight_end],
                &mut output_flat[instruction.output_start..],
                instruction.output_mul,
                spec.output_dim,
                path_weight,
                1.0,
            );
            continue;
        }

        let weight_start = instruction.weight_offset;
        let weight_end = weight_start + instruction.input_mul * instruction.output_mul;
        let weight_slice = &spec.weight[weight_start..weight_end];
        let packed_rows = row_count * instruction.irrep_dim;
        let mut packed_input = vec![0.0_f64; packed_rows * instruction.input_mul];
        let mut packed_output = vec![0.0_f64; packed_rows * instruction.output_mul];
        for row in 0..row_count {
            let input_base = row * spec.input_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base = (row * instruction.irrep_dim + component) * instruction.input_mul;
                for input_mul in 0..instruction.input_mul {
                    packed_input[packed_base + input_mul] = input_flat[input_base
                        + instruction.input_start
                        + input_mul * instruction.irrep_dim
                        + component];
                }
            }
        }
        blas_backend::dense_forward_strided_row_parallel_f64(
            &packed_input,
            packed_rows,
            instruction.input_mul,
            instruction.input_mul,
            weight_slice,
            &mut packed_output,
            instruction.output_mul,
            instruction.output_mul,
            path_weight,
            0.0,
        );
        for row in 0..row_count {
            let output_base = row * spec.output_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base =
                    (row * instruction.irrep_dim + component) * instruction.output_mul;
                for output_mul in 0..instruction.output_mul {
                    output_flat[output_base
                        + instruction.output_start
                        + output_mul * instruction.irrep_dim
                        + component] += packed_output[packed_base + output_mul];
                }
            }
        }
    }

    if !output_mask_all_one {
        for row in 0..row_count {
            let start = row * spec.output_dim;
            for output in 0..spec.output_dim {
                output_flat[start + output] *= spec.output_mask[output];
            }
        }
    }

    output_flat
        .chunks_exact(spec.output_dim)
        .map(|row| row.to_vec())
        .collect()
}

#[allow(dead_code)]
fn polar_mace_e3nn_block_linear_rows_vjp(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    spec: MacePolarBlockLinearSpec<'_>,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{}.output_mask.len", spec.name),
        spec.output_mask.len(),
        spec.output_dim,
    )?;
    let expected_weight_len = spec
        .instructions
        .iter()
        .map(|instruction| {
            instruction.weight_offset + instruction.input_mul * instruction.output_mul
        })
        .max()
        .unwrap_or(0);
    require_usize(
        &format!("{}.weight.len", spec.name),
        spec.weight.len(),
        expected_weight_len,
    )?;
    if let Some(path_weights) = spec.instruction_path_weights {
        require_usize(
            &format!("{}.instruction_path_weights.len", spec.name),
            path_weights.len(),
            spec.instructions.len(),
        )?;
    }
    require_usize(
        &format!("{}.output_cotangent.len", spec.name),
        output_cotangent.len(),
        input_rows.len(),
    )?;
    for (row_index, (input_row, bar_output_row)) in
        input_rows.iter().zip(output_cotangent).enumerate()
    {
        require_usize(
            &format!("{}.input_rows[{row_index}].len", spec.name),
            input_row.len(),
            spec.input_dim,
        )?;
        require_usize(
            &format!("{}.output_cotangent[{row_index}].len", spec.name),
            bar_output_row.len(),
            spec.output_dim,
        )?;
    }
    for instruction in spec.instructions {
        let input_end = instruction.input_start + instruction.input_mul * instruction.irrep_dim;
        let output_end = instruction.output_start + instruction.output_mul * instruction.irrep_dim;
        if input_end > spec.input_dim || output_end > spec.output_dim {
            return Err(invalid(
                spec.name,
                format!(
                    "block instruction exceeds dimensions: input_end={input_end} input_dim={} output_end={output_end} output_dim={}",
                    spec.input_dim, spec.output_dim
                ),
            ));
        }
        if instruction.input_mul == 0 {
            return Err(invalid(
                spec.name,
                "block instruction input multiplicity must be non-zero",
            ));
        }
    }

    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    ))]
    {
        Ok(polar_mace_e3nn_block_linear_rows_vjp_accelerate(
            output_cotangent,
            input_rows,
            &spec,
        ))
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    {
        let mut input_cotangent_rows = Vec::with_capacity(input_rows.len());
        for (row_index, (input_row, bar_output_row)) in
            input_rows.iter().zip(output_cotangent).enumerate()
        {
            require_usize(
                &format!("{}.input_rows[{row_index}].len", spec.name),
                input_row.len(),
                spec.input_dim,
            )?;
            require_usize(
                &format!("{}.output_cotangent[{row_index}].len", spec.name),
                bar_output_row.len(),
                spec.output_dim,
            )?;
            let mut bar_output_masked = vec![0.0_f64; spec.output_dim];
            for output_index in 0..spec.output_dim {
                bar_output_masked[output_index] =
                    bar_output_row[output_index] * spec.output_mask[output_index];
            }
            let mut bar_input = vec![0.0_f64; spec.input_dim];
            for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
                let input_end =
                    instruction.input_start + instruction.input_mul * instruction.irrep_dim;
                let output_end =
                    instruction.output_start + instruction.output_mul * instruction.irrep_dim;
                if input_end > spec.input_dim || output_end > spec.output_dim {
                    return Err(invalid(
                        spec.name,
                        format!(
                            "block instruction exceeds dimensions: input_end={input_end} input_dim={} output_end={output_end} output_dim={}",
                            spec.input_dim, spec.output_dim
                        ),
                    ));
                }
                if instruction.input_mul == 0 {
                    return Err(invalid(
                        spec.name,
                        "block instruction input multiplicity must be non-zero",
                    ));
                }
                let path_weight = spec.instruction_path_weights.map_or_else(
                    || 1.0 / (instruction.input_mul as f64).sqrt(),
                    |path_weights| path_weights[instruction_index],
                );
                for output_mul in 0..instruction.output_mul {
                    for input_mul in 0..instruction.input_mul {
                        let weight_value = spec.weight[instruction.weight_offset
                            + input_mul * instruction.output_mul
                            + output_mul];
                        for component in 0..instruction.irrep_dim {
                            let input_index = instruction.input_start
                                + input_mul * instruction.irrep_dim
                                + component;
                            let output_index = instruction.output_start
                                + output_mul * instruction.irrep_dim
                                + component;
                            bar_input[input_index] +=
                                path_weight * weight_value * bar_output_masked[output_index];
                        }
                    }
                }
            }
            input_cotangent_rows.push(bar_input);
        }
        Ok(input_cotangent_rows)
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(feature = "openblas", target_os = "linux", target_arch = "aarch64"),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn polar_mace_e3nn_block_linear_rows_vjp_accelerate(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
    spec: &MacePolarBlockLinearSpec<'_>,
) -> MacePolarRows {
    let row_count = input_rows.len();
    if row_count == 0 {
        return Vec::new();
    }

    let output_mask_all_one = spec.output_mask.iter().all(|&value| value == 1.0);
    let mut bar_output_masked_flat = vec![0.0_f64; row_count * spec.output_dim];
    if output_mask_all_one {
        for (row_index, bar_output_row) in output_cotangent.iter().enumerate() {
            let start = row_index * spec.output_dim;
            bar_output_masked_flat[start..start + spec.output_dim].copy_from_slice(bar_output_row);
        }
    } else {
        for (row_index, bar_output_row) in output_cotangent.iter().enumerate() {
            let start = row_index * spec.output_dim;
            for output_index in 0..spec.output_dim {
                bar_output_masked_flat[start + output_index] =
                    bar_output_row[output_index] * spec.output_mask[output_index];
            }
        }
    }

    let mut bar_input_flat = vec![0.0_f64; row_count * spec.input_dim];
    for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
        let path_weight = spec.instruction_path_weights.map_or_else(
            || 1.0 / (instruction.input_mul as f64).sqrt(),
            |path_weights| path_weights[instruction_index],
        );
        if instruction.irrep_dim == 1 {
            let weight_start = instruction.weight_offset;
            let weight_end = weight_start + instruction.input_mul * instruction.output_mul;
            blas_backend::dense_vjp_input_strided_row_parallel_f64(
                row_count,
                instruction.input_mul,
                &spec.weight[weight_start..weight_end],
                instruction.output_mul,
                &bar_output_masked_flat[instruction.output_start..],
                spec.output_dim,
                &mut bar_input_flat[instruction.input_start..],
                spec.input_dim,
                path_weight,
                1.0,
            );
            continue;
        }

        let weight_start = instruction.weight_offset;
        let weight_end = weight_start + instruction.input_mul * instruction.output_mul;
        let weight_slice = &spec.weight[weight_start..weight_end];
        let packed_rows = row_count * instruction.irrep_dim;
        let mut packed_bar_output = vec![0.0_f64; packed_rows * instruction.output_mul];
        let mut packed_bar_input = vec![0.0_f64; packed_rows * instruction.input_mul];
        for row in 0..row_count {
            let output_base = row * spec.output_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base =
                    (row * instruction.irrep_dim + component) * instruction.output_mul;
                for output_mul in 0..instruction.output_mul {
                    packed_bar_output[packed_base + output_mul] = bar_output_masked_flat[output_base
                        + instruction.output_start
                        + output_mul * instruction.irrep_dim
                        + component];
                }
            }
        }
        blas_backend::dense_vjp_input_strided_row_parallel_f64(
            packed_rows,
            instruction.input_mul,
            weight_slice,
            instruction.output_mul,
            &packed_bar_output,
            instruction.output_mul,
            &mut packed_bar_input,
            instruction.input_mul,
            path_weight,
            0.0,
        );
        for row in 0..row_count {
            let input_base = row * spec.input_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base = (row * instruction.irrep_dim + component) * instruction.input_mul;
                for input_mul in 0..instruction.input_mul {
                    bar_input_flat[input_base
                        + instruction.input_start
                        + input_mul * instruction.irrep_dim
                        + component] += packed_bar_input[packed_base + input_mul];
                }
            }
        }
    }

    bar_input_flat
        .chunks_exact(spec.input_dim)
        .map(<[f64]>::to_vec)
        .collect()
}

