#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
))]
fn polar_mace_e3nn_block_linear_rows_accelerate_f32(
    input_rows: &[Vec<f32>],
    spec: &MacePolarBlockLinearSpecF32<'_>,
) -> MacePolarRowsF32 {
    let row_count = input_rows.len();
    if row_count == 0 {
        return Vec::new();
    }

    let mut input_flat = vec![0.0_f32; row_count * spec.input_dim];
    for (row_index, input_row) in input_rows.iter().enumerate() {
        let start = row_index * spec.input_dim;
        input_flat[start..start + spec.input_dim].copy_from_slice(input_row);
    }

    let output_mask_all_one = spec.output_mask.iter().all(|&value| value == 1.0);
    let mut output_flat = vec![0.0_f32; row_count * spec.output_dim];
    if !spec.bias.is_empty() {
        for row in 0..row_count {
            let start = row * spec.output_dim;
            output_flat[start..start + spec.output_dim].copy_from_slice(spec.bias);
        }
    }

    for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
        let path_weight = spec.instruction_path_weights.map_or_else(
            || (1.0 / (instruction.input_mul as f64).sqrt()) as f32,
            |path_weights| path_weights[instruction_index] as f32,
        );
        let weight_start = instruction.weight_offset;
        let weight_end = weight_start + instruction.input_mul * instruction.output_mul;
        let weight_slice = &spec.weight[weight_start..weight_end];
        if instruction.irrep_dim == 1 {
            blas_backend::dense_forward_strided_f32(
                &input_flat[instruction.input_start..],
                row_count,
                instruction.input_mul,
                spec.input_dim,
                weight_slice,
                &mut output_flat[instruction.output_start..],
                instruction.output_mul,
                spec.output_dim,
                path_weight,
                1.0,
            );
            continue;
        }

        let packed_rows = row_count * instruction.irrep_dim;
        let mut packed_input = vec![0.0_f32; packed_rows * instruction.input_mul];
        let mut packed_output = vec![0.0_f32; packed_rows * instruction.output_mul];
        for row in 0..row_count {
            let input_base = row * spec.input_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base = (row * instruction.irrep_dim + component) * instruction.input_mul;
                for input_mul in 0..instruction.input_mul {
                    packed_input[packed_base + input_mul] = input_flat[input_base
                        + instruction.input_start
                        + input_mul * instruction.irrep_dim
                        + component];
                }
            }
        }
        blas_backend::dense_forward_strided_f32(
            &packed_input,
            packed_rows,
            instruction.input_mul,
            instruction.input_mul,
            weight_slice,
            &mut packed_output,
            instruction.output_mul,
            instruction.output_mul,
            path_weight,
            0.0,
        );
        for row in 0..row_count {
            let output_base = row * spec.output_dim;
            for component in 0..instruction.irrep_dim {
                let packed_base =
                    (row * instruction.irrep_dim + component) * instruction.output_mul;
                for output_mul in 0..instruction.output_mul {
                    output_flat[output_base
                        + instruction.output_start
                        + output_mul * instruction.irrep_dim
                        + component] += packed_output[packed_base + output_mul];
                }
            }
        }
    }

    if !output_mask_all_one {
        for row in 0..row_count {
            let start = row * spec.output_dim;
            for output in 0..spec.output_dim {
                output_flat[start + output] *= spec.output_mask[output];
            }
        }
    }

    output_flat
        .chunks_exact(spec.output_dim)
        .map(|row| row.to_vec())
        .collect()
}

#[cfg(not(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        target_arch = "x86_64"
    ),
    all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
)))]
fn polar_mace_e3nn_block_linear_rows_scalar_f32(
    input_rows: &[Vec<f32>],
    spec: &MacePolarBlockLinearSpecF32<'_>,
) -> Result<MacePolarRowsF32, MacePolarError> {
    let mut output_rows = Vec::with_capacity(input_rows.len());
    for input_row in input_rows {
        let mut output = vec![0.0_f32; spec.output_dim];
        for (index, value) in spec.bias.iter().enumerate() {
            output[index] = *value;
        }

        for (instruction_index, instruction) in spec.instructions.iter().enumerate() {
            let path_weight = spec.instruction_path_weights.map_or_else(
                || (1.0 / (instruction.input_mul as f64).sqrt()) as f32,
                |path_weights| path_weights[instruction_index] as f32,
            );
            for output_mul in 0..instruction.output_mul {
                for input_mul in 0..instruction.input_mul {
                    let weight_value = spec.weight[instruction.weight_offset
                        + input_mul * instruction.output_mul
                        + output_mul];
                    for component in 0..instruction.irrep_dim {
                        let input_index =
                            instruction.input_start + input_mul * instruction.irrep_dim + component;
                        let output_index = instruction.output_start
                            + output_mul * instruction.irrep_dim
                            + component;
                        output[output_index] = (path_weight * input_row[input_index])
                            .mul_add(weight_value, output[output_index]);
                    }
                }
            }
        }
        for (value, mask) in output.iter_mut().zip(spec.output_mask) {
            *value *= *mask;
        }
        output_rows.push(output);
    }
    Ok(output_rows)
}

#[allow(dead_code)]
fn polar_mace_e3nn_linear_input_major_rows_f32(
    input_rows: &[Vec<f32>],
    weight: &[f32],
    bias: &[f32],
    output_mask: &[f32],
    input_dim: usize,
    output_dim: usize,
    connected_input_multiplicity: usize,
) -> Result<MacePolarRowsF32, MacePolarError> {
    require_usize(
        "e3nn_linear_f32.weight.len",
        weight.len(),
        input_dim * output_dim,
    )?;
    if !bias.is_empty() && bias.len() != output_dim {
        return Err(invalid(
            "e3nn_linear_f32.bias",
            format!("expected length 0 or {output_dim}, got {}", bias.len()),
        ));
    }
    require_usize(
        "e3nn_linear_f32.output_mask.len",
        output_mask.len(),
        output_dim,
    )?;
    if connected_input_multiplicity == 0 {
        return Err(invalid(
            "e3nn_linear_f32.connected_input_multiplicity",
            "must be non-zero",
        ));
    }

    let instructions = [MacePolarBlockLinearInstruction {
        input_start: 0,
        output_start: 0,
        input_mul: input_dim,
        output_mul: output_dim,
        irrep_dim: 1,
        weight_offset: 0,
    }];
    let path_weight = [polar_mace_scalar_path_weight(connected_input_multiplicity)];
    polar_mace_e3nn_block_linear_rows_f32(
        input_rows,
        MacePolarBlockLinearSpecF32 {
            weight,
            bias,
            output_mask,
            instructions: &instructions,
            instruction_path_weights: Some(&path_weight),
            input_dim,
            output_dim,
            name: "e3nn_linear_f32",
        },
    )
}

