#[allow(dead_code)]
fn polar_mace_scalar_path_weight(mul: usize) -> f64 {
    1.0 / (mul as f64).sqrt()
}

#[allow(dead_code)]
fn polar_mace_product_irrep_dims(product_width: usize) -> Result<Vec<usize>, MacePolarError> {
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    match product_width / hidden_dim {
        1 => Ok(vec![1]),
        4 => Ok(vec![1, 3]),
        9 => Ok(vec![1, 3, 5]),
        _ => Err(invalid(
            "local_backbone.product_width",
            format!("unsupported product feature width {product_width}"),
        )),
    }
}

#[allow(dead_code)]
fn polar_mace_runtime_linear_up_plan(
    layer: usize,
    input_dim: usize,
) -> Result<MacePolarRuntimeLinearPlan, MacePolarError> {
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    if layer == 0 {
        return Ok(MacePolarRuntimeLinearPlan {
            input_dim,
            output_dim: hidden_dim,
            weight_len: hidden_dim * hidden_dim,
            instructions: vec![MacePolarBlockLinearInstruction {
                input_start: 0,
                output_start: 0,
                input_mul: hidden_dim,
                output_mul: hidden_dim,
                irrep_dim: 1,
                weight_offset: 0,
            }],
            path_weights: vec![polar_mace_scalar_path_weight(hidden_dim)],
        });
    }
    let dims = polar_mace_product_irrep_dims(input_dim)?;
    let output_mul = 128_usize;
    let mut instructions = Vec::with_capacity(dims.len());
    let mut path_weights = Vec::with_capacity(dims.len());
    let mut input_start = 0_usize;
    let mut output_start = 0_usize;
    let mut weight_offset = 0_usize;
    for irrep_dim in dims {
        instructions.push(MacePolarBlockLinearInstruction {
            input_start,
            output_start,
            input_mul: hidden_dim,
            output_mul,
            irrep_dim,
            weight_offset,
        });
        path_weights.push(polar_mace_scalar_path_weight(hidden_dim));
        input_start += hidden_dim * irrep_dim;
        output_start += output_mul * irrep_dim;
        weight_offset += hidden_dim * output_mul;
    }
    Ok(MacePolarRuntimeLinearPlan {
        input_dim,
        output_dim: output_start,
        weight_len: weight_offset,
        instructions,
        path_weights,
    })
}

