#[allow(dead_code)]
fn polar_mace_runtime_skip_tp_plan(
    input_dim: usize,
    output_dim: usize,
) -> Result<MacePolarRuntimeLinearPlan, MacePolarError> {
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let dims = polar_mace_product_irrep_dims(output_dim)?;
    let mut instructions = Vec::new();
    let mut path_weights = Vec::new();
    let mut offset = 0_usize;
    let mut weight_offset = 0_usize;
    for irrep_dim in dims {
        if offset + hidden_dim * irrep_dim > input_dim {
            break;
        }
        instructions.push(MacePolarBlockLinearInstruction {
            input_start: offset,
            output_start: offset,
            input_mul: hidden_dim,
            output_mul: hidden_dim,
            irrep_dim,
            weight_offset,
        });
        path_weights.push(polar_mace_scalar_path_weight(hidden_dim));
        offset += hidden_dim * irrep_dim;
        weight_offset += hidden_dim * hidden_dim;
    }
    if instructions.is_empty() {
        return Err(invalid(
            "interactions.skip_tp",
            format!("no skip path for input_dim={input_dim} output_dim={output_dim}"),
        ));
    }
    Ok(MacePolarRuntimeLinearPlan {
        input_dim,
        output_dim,
        weight_len: weight_offset,
        instructions,
        path_weights,
    })
}

