#[allow(dead_code)]
fn polar_mace_density_fn_edge_density_cutoff_applied_rows_flat_trace_for_layer(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    edge_aug_rows: &[Vec<f64>],
    cutoffs: &[f64],
) -> Result<(MacePolarRows, MacePolarDensityFnFlatTrace), MacePolarError> {
    let access = MacePolarTensorAccess::new(tensors);
    let hidden = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_hidden_dim;
    let input_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim;
    let row_count = edge_aug_rows.len();
    let prefix = format!("interactions.{layer}.density_fn.net");
    require_usize("density_fn.cutoffs.len", cutoffs.len(), row_count)?;
    if row_count == 0 {
        return Ok((
            Vec::new(),
            MacePolarDensityFnFlatTrace {
                row_count: 0,
                linear_0: Vec::new(),
                norm_1: Vec::new(),
                raw: Vec::new(),
            },
        ));
    }

    let input_flat = polar_mace_flatten_rows(edge_aug_rows, input_dim, "density_fn.edge_aug")?;

    let mut linear_0 = vec![0.0_f64; row_count * hidden];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &input_flat,
        row_count,
        input_dim,
        access.f64(&format!("{prefix}.0.weight"), &[hidden, input_dim])?,
        &mut linear_0,
        hidden,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut linear_0,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.0.bias"), &[hidden])?,
    );
    let norm_1 = polar_mace_layer_norm_flat(
        &linear_0,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.1.weight"), &[hidden])?,
        access.f64(&format!("{prefix}.1.bias"), &[hidden])?,
        1.0e-5,
        "density_fn.net.1.flat",
    )?;
    let silu_1 = polar_mace_silu_flat(&norm_1);

    let mut raw = vec![0.0_f64; row_count];
    blas_backend::dense_forward_output_major_weight_row_parallel_f64(
        &silu_1,
        row_count,
        hidden,
        access.f64(&format!("{prefix}.3.weight"), &[1, hidden])?,
        &mut raw,
        1,
        1.0,
        0.0,
    );
    polar_mace_add_bias_flat(
        &mut raw,
        row_count,
        1,
        access.f64(&format!("{prefix}.3.bias"), &[1])?,
    );
    let rows = raw
        .iter()
        .zip(cutoffs)
        .map(|(value, cutoff)| vec![(*value * *value).tanh() * *cutoff])
        .collect();
    let trace = MacePolarDensityFnFlatTrace {
        row_count,
        linear_0,
        norm_1,
        raw,
    };
    Ok((rows, trace))
}

