#[allow(dead_code)]
fn polar_mace_scatter_scalar_to_targets(
    edge_index: &[[usize; 2]],
    edge_rows: &[Vec<f64>],
    node_count: usize,
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{name}.edge_rows.len"),
        edge_rows.len(),
        edge_index.len(),
    )?;
    let mut node_rows = vec![vec![0.0_f64; 1]; node_count];
    for (edge, ([_, target], row)) in edge_index.iter().zip(edge_rows).enumerate() {
        require_usize(&format!("{name}.edge_rows[{edge}].len"), row.len(), 1)?;
        let target_row = node_rows.get_mut(*target).ok_or_else(|| {
            invalid(
                name,
                format!("edge {edge} target node {target} out of range"),
            )
        })?;
        target_row[0] += row[0];
    }
    Ok(node_rows)
}

