#[allow(dead_code)]
fn polar_mace_density_normalize_rows(
    rows: &[Vec<f64>],
    denominator: &[Vec<f64>],
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(
        &format!("{name}.denominator.len"),
        denominator.len(),
        rows.len(),
    )?;
    rows.iter()
        .zip(denominator)
        .enumerate()
        .map(|(row_index, (row, denom))| {
            require_usize(
                &format!("{name}.denominator[{row_index}].len"),
                denom.len(),
                1,
            )?;
            if denom[0] == 0.0 {
                return Err(invalid(
                    name,
                    format!("zero denominator at row {row_index}"),
                ));
            }
            Ok(row.iter().map(|value| value / denom[0]).collect())
        })
        .collect()
}

#[allow(dead_code)]
fn polar_mace_density_normalize_rows_vjp(
    output_cotangent: &[Vec<f64>],
    rows: &[Vec<f64>],
    denominator: &[Vec<f64>],
    name: &str,
) -> Result<(MacePolarRows, MacePolarRows), MacePolarError> {
    require_usize(
        &format!("{name}.output_cotangent.len"),
        output_cotangent.len(),
        rows.len(),
    )?;
    require_usize(
        &format!("{name}.denominator.len"),
        denominator.len(),
        rows.len(),
    )?;
    let mut row_cotangent = polar_mace_zero_rows_like(rows);
    let mut denominator_cotangent = polar_mace_zero_rows_like(denominator);
    for (row_index, ((bar_output, row), denom)) in output_cotangent
        .iter()
        .zip(rows)
        .zip(denominator)
        .enumerate()
    {
        require_usize(
            &format!("{name}.output_cotangent[{row_index}].len"),
            bar_output.len(),
            row.len(),
        )?;
        require_usize(
            &format!("{name}.denominator[{row_index}].len"),
            denom.len(),
            1,
        )?;
        if denom[0] == 0.0 {
            return Err(invalid(
                name,
                format!("zero denominator at row {row_index}"),
            ));
        }
        for component in 0..row.len() {
            row_cotangent[row_index][component] += bar_output[component] / denom[0];
            denominator_cotangent[row_index][0] -=
                bar_output[component] * row[component] / (denom[0] * denom[0]);
        }
    }
    Ok((row_cotangent, denominator_cotangent))
}

