fn polar_mace_add_rows(
    left: &[Vec<f64>],
    right: &[Vec<f64>],
    name: &str,
) -> Result<MacePolarRows, MacePolarError> {
    require_usize(&format!("{name}.right.len"), right.len(), left.len())?;
    left.iter()
        .zip(right)
        .enumerate()
        .map(|(row_index, (left_row, right_row))| {
            require_usize(
                &format!("{name}.right[{row_index}].len"),
                right_row.len(),
                left_row.len(),
            )?;
            Ok(left_row
                .iter()
                .zip(right_row)
                .map(|(left_value, right_value)| left_value + right_value)
                .collect())
        })
        .collect()
}

