#[allow(dead_code)]
fn polar_mace_gate_activation_partitions(
    gate_plan: &serde_json::Value,
    key: &str,
    input_partition_name: &str,
    constants_len: usize,
) -> Result<Vec<serde_json::Value>, MacePolarError> {
    if constants_len == 0 {
        return Err(invalid(
            "gate_plan.activation.constants",
            "expected at least one normalize2mom constant",
        ));
    }
    if let Some(partitions) = gate_plan
        .get("activation_input_partitions")
        .and_then(|partitions| partitions.get(key))
    {
        return Ok(polar_mace_json_array(
            partitions,
            &format!("gate_plan.activation_input_partitions.{key}"),
        )?
        .clone());
    }

    let input_partition =
        polar_mace_named_partition(&gate_plan["input_partitions"], input_partition_name)?;
    let subpartitions = polar_mace_json_array(
        &input_partition["subpartitions"],
        &format!("gate_plan.input_partitions.{input_partition_name}.subpartitions"),
    )?;
    if subpartitions.len() == constants_len {
        return Ok(subpartitions.clone());
    }
    if subpartitions.len() != 1 {
        return Err(invalid(
            &format!("gate_plan.activation_input_partitions.{key}"),
            format!(
                "cannot derive {constants_len} activation partition(s) from {} input subpartition(s)",
                subpartitions.len()
            ),
        ));
    }

    let subpartition = &subpartitions[0];
    let start = polar_mace_json_usize_field(subpartition, "start", "gate_plan.activation")?;
    let dim = polar_mace_json_usize_field(subpartition, "dim", "gate_plan.activation")?;
    let irrep_dim = polar_mace_json_usize_field(subpartition, "irrep_dim", "gate_plan.activation")?;
    if irrep_dim != 1 || dim % constants_len != 0 {
        return Err(invalid(
            &format!("gate_plan.activation_input_partitions.{key}"),
            format!(
                "cannot split dim={dim} irrep_dim={irrep_dim} into {constants_len} scalar activation partitions"
            ),
        ));
    }
    let chunk = dim / constants_len;
    let irrep = subpartition["irrep"].as_str().unwrap_or("0e");
    Ok((0..constants_len)
        .map(|index| {
            let chunk_start = start + index * chunk;
            serde_json::json!({
                "dim": chunk,
                "end": chunk_start + chunk,
                "index": index,
                "irrep": irrep,
                "irrep_dim": 1,
                "mul": chunk,
                "start": chunk_start
            })
        })
        .collect())
}

#[allow(dead_code)]
fn polar_mace_gate_mul_output_mask(
    access: &MacePolarTensorAccess<'_>,
    gate_plan: &serde_json::Value,
) -> Result<Vec<f64>, MacePolarError> {
    if !gate_plan["mul"]["output_mask"].is_null() {
        return polar_mace_json_f64_values(
            &gate_plan["mul"]["output_mask"],
            "gate_plan.mul.output_mask",
        );
    }
    let name = gate_plan["mul"]["state_tensor_refs"]["output_mask"]["name"]
        .as_str()
        .ok_or_else(|| {
            invalid(
                "gate_plan.mul.output_mask",
                "missing output_mask values or state tensor reference",
            )
        })?;
    Ok(access.f64(name, &[POLAR_1_S_MUL_OUTPUT_MASK_LEN])?.to_vec())
}
#[allow(dead_code)]
fn polar_mace_reshape_hidden_irreps_to_feature_major(
    rows: &[Vec<f64>],
) -> Result<Vec<f64>, MacePolarError> {
    let block_dims = [1_usize, 3, 5, 7];
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let sh_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.edge_attr_dim;
    let mut out = Vec::with_capacity(rows.len() * hidden_dim * sh_dim);
    for (row_index, row) in rows.iter().enumerate() {
        require_usize(
            &format!("reshaped_interaction_out.input[{row_index}].len"),
            row.len(),
            hidden_dim * sh_dim,
        )?;
        let mut row_out = vec![0.0; hidden_dim * sh_dim];
        let mut block_offset = 0_usize;
        let mut component_offset = 0_usize;
        for &component_dim in &block_dims {
            for feature in 0..hidden_dim {
                for component in 0..component_dim {
                    row_out[feature * sh_dim + component_offset + component] =
                        row[block_offset + feature * component_dim + component];
                }
            }
            block_offset += hidden_dim * component_dim;
            component_offset += component_dim;
        }
        out.extend(row_out);
    }
    Ok(out)
}

