#[allow(dead_code)]
fn polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer(
    access: &MacePolarTensorAccess<'_>,
    layer: usize,
    input: &[f64],
    node_count: usize,
) -> Result<MacePolarRows, MacePolarError> {
    let dynamic_prefix = format!("products.{layer}.symmetric_contractions.contractions.0");
    if layer != 0
        || access
            .tensors
            .contains_key(&format!("{dynamic_prefix}.U_matrix_1"))
    {
        return polar_mace_product_symmetric_contraction_rows_dynamic_from_tensors(
            access, layer, input, node_count,
        );
    }

    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let num_ell = LOCAL_BACKBONE_FORWARD_CONTRACT.edge_attr_dim;
    require_usize(
        "product.symmetric_contractions.input.len",
        input.len(),
        node_count * hidden_dim * num_ell,
    )?;

    let prefix = "products.0.symmetric_contractions.contractions.0";
    let u1 = access.f64(&format!("{prefix}.U_matrix_1"), &[16, 1])?;
    let u2 = access.f64(&format!("{prefix}.U_matrix_2"), &[16, 16, 4])?;
    let u3 = access.f64(&format!("{prefix}.U_matrix_3"), &[16, 16, 16, 23])?;
    let weights_u2 = access.f64(&format!("{prefix}.weights.0"), &[1, 4, hidden_dim])?;
    let weights_u1 = access.f64(&format!("{prefix}.weights.1"), &[1, 1, hidden_dim])?;
    let weights_u3 = access.f64(&format!("{prefix}.weights_max"), &[1, 23, hidden_dim])?;

    let contraction = crate::mace::MaceScalarSymmetricContraction {
        num_elements: 1,
        num_features: hidden_dim,
        num_ell,
        u1_params: 1,
        u2_params: 4,
        u3_params: 23,
        u1,
        u2,
        u3,
        weights_u2,
        weights_u1,
        weights_u3,
        entries: None,
    };
    let node_attrs = vec![1.0_f64; node_count];
    let mut output = vec![0.0_f64; node_count * hidden_dim];
    contraction
        .forward(input, &node_attrs, &mut output)
        .map_err(|err| invalid("product.symmetric_contractions.forward", err.to_string()))?;
    Ok(output
        .chunks_exact(hidden_dim)
        .map(<[f64]>::to_vec)
        .collect())
}

#[allow(dead_code)]
fn polar_mace_product_symmetric_contraction_rows_dynamic_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    layer: usize,
    input: &[f64],
    node_count: usize,
) -> Result<MacePolarRows, MacePolarError> {
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let num_ell = LOCAL_BACKBONE_FORWARD_CONTRACT.edge_attr_dim;
    require_usize(
        "product.symmetric_contractions.input.len",
        input.len(),
        node_count * hidden_dim * num_ell,
    )?;

    let node_attrs = vec![1.0_f64; node_count];
    let mut output_rows = vec![Vec::new(); node_count];
    let mut contraction_count = 0_usize;
    for contraction_index in 0.. {
        let prefix =
            format!("products.{layer}.symmetric_contractions.contractions.{contraction_index}");
        let u1_name = format!("{prefix}.U_matrix_1");
        if !access.tensors.contains_key(&u1_name) {
            break;
        }
        let (u1_shape, u1) = access.f64_dynamic(&u1_name)?;
        match u1_shape {
            [ell, u1_params] => {
                require_usize(
                    "product.symmetric_contractions.scalar.num_ell",
                    *ell,
                    num_ell,
                )?;
                let u2 = access.f64(&format!("{prefix}.U_matrix_2"), &[num_ell, num_ell, 4])?;
                let u3 = access.f64(
                    &format!("{prefix}.U_matrix_3"),
                    &[num_ell, num_ell, num_ell, 23],
                )?;
                let weights_u2 = access.f64(&format!("{prefix}.weights.0"), &[1, 4, hidden_dim])?;
                let weights_u1 =
                    access.f64(&format!("{prefix}.weights.1"), &[1, *u1_params, hidden_dim])?;
                let weights_u3 =
                    access.f64(&format!("{prefix}.weights_max"), &[1, 23, hidden_dim])?;
                let contraction = crate::mace::MaceScalarSymmetricContraction {
                    num_elements: 1,
                    num_features: hidden_dim,
                    num_ell,
                    u1_params: *u1_params,
                    u2_params: 4,
                    u3_params: 23,
                    u1,
                    u2,
                    u3,
                    weights_u2,
                    weights_u1,
                    weights_u3,
                    entries: None,
                };
                let mut flat_output = vec![0.0_f64; node_count * hidden_dim];
                contraction
                    .forward(input, &node_attrs, &mut flat_output)
                    .map_err(|err| {
                        invalid("product.symmetric_contractions.forward", err.to_string())
                    })?;
                for (row, chunk) in output_rows
                    .iter_mut()
                    .zip(flat_output.chunks_exact(hidden_dim))
                {
                    row.extend_from_slice(chunk);
                }
            }
            [num_equivariance, ell, u1_params] => {
                require_usize(
                    "product.symmetric_contractions.vector.num_ell",
                    *ell,
                    num_ell,
                )?;
                let (_, u2) = access.f64_dynamic(&format!("{prefix}.U_matrix_2"))?;
                let (_, u3) = access.f64_dynamic(&format!("{prefix}.U_matrix_3"))?;
                let u2_params = match access
                    .tensors
                    .get(&format!("{prefix}.U_matrix_2"))
                    .map(|tensor| tensor.shape.as_slice())
                {
                    Some([equiv, left, right, params])
                        if *equiv == *num_equivariance && *left == num_ell && *right == num_ell =>
                    {
                        *params
                    }
                    other => {
                        return Err(invalid(
                            "product.symmetric_contractions.U_matrix_2",
                            format!("unexpected vector U_matrix_2 shape {other:?}"),
                        ));
                    }
                };
                let u3_params = match access
                    .tensors
                    .get(&format!("{prefix}.U_matrix_3"))
                    .map(|tensor| tensor.shape.as_slice())
                {
                    Some([equiv, left, right, inner, params])
                        if *equiv == *num_equivariance
                            && *left == num_ell
                            && *right == num_ell
                            && *inner == num_ell =>
                    {
                        *params
                    }
                    other => {
                        return Err(invalid(
                            "product.symmetric_contractions.U_matrix_3",
                            format!("unexpected vector U_matrix_3 shape {other:?}"),
                        ));
                    }
                };
                let weights_u2 =
                    access.f64(&format!("{prefix}.weights.0"), &[1, u2_params, hidden_dim])?;
                let weights_u1 =
                    access.f64(&format!("{prefix}.weights.1"), &[1, *u1_params, hidden_dim])?;
                let weights_u3 = access.f64(
                    &format!("{prefix}.weights_max"),
                    &[1, u3_params, hidden_dim],
                )?;
                let contraction = crate::mace::MaceVectorSymmetricContraction {
                    num_elements: 1,
                    num_features: hidden_dim,
                    num_equivariance: *num_equivariance,
                    num_ell,
                    u1_params: *u1_params,
                    u2_params,
                    u3_params,
                    u1,
                    u2,
                    u3,
                    weights_u2,
                    weights_u1,
                    weights_u3,
                    entries: None,
                };
                let per_node = hidden_dim * *num_equivariance;
                let mut flat_output = vec![0.0_f64; node_count * per_node];
                contraction
                    .forward(input, &node_attrs, &mut flat_output)
                    .map_err(|err| {
                        invalid("product.symmetric_contractions.forward", err.to_string())
                    })?;
                for (row, chunk) in output_rows
                    .iter_mut()
                    .zip(flat_output.chunks_exact(per_node))
                {
                    row.extend_from_slice(chunk);
                }
            }
            other => {
                return Err(invalid(
                    "product.symmetric_contractions.U_matrix_1",
                    format!("unexpected U_matrix_1 shape {other:?}"),
                ));
            }
        }
        contraction_count += 1;
    }

    if contraction_count == 0 {
        return Err(invalid(
            "product.symmetric_contractions",
            format!("products.{layer} has no exported contraction tensors"),
        ));
    }
    Ok(output_rows)
}

