#[allow(dead_code)]
fn polar_mace_runtime_readout_normalized_silu_rows(
    rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    const READOUT_SILU_NORMALIZE2MOM: f64 = 1.679_176_792_398_941_8;
    Ok(rows
        .iter()
        .map(|row| {
            row.iter()
                .map(|value| READOUT_SILU_NORMALIZE2MOM * value / (1.0 + (-value).exp()))
                .collect()
        })
        .collect())
}

#[allow(dead_code)]
fn polar_mace_runtime_readout_normalized_silu_rows_vjp(
    output_cotangent: &[Vec<f64>],
    input_rows: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    const READOUT_SILU_NORMALIZE2MOM: f64 = 1.679_176_792_398_941_8;
    require_usize(
        "readout_normalized_silu_vjp.output_cotangent.len",
        output_cotangent.len(),
        input_rows.len(),
    )?;
    input_rows
        .iter()
        .zip(output_cotangent)
        .enumerate()
        .map(|(row_index, (input, bar_output))| {
            require_usize(
                &format!("readout_normalized_silu_vjp.output_cotangent[{row_index}].len"),
                bar_output.len(),
                input.len(),
            )?;
            Ok(input
                .iter()
                .zip(bar_output)
                .map(|(value, bar)| {
                    let sigmoid = 1.0 / (1.0 + (-value).exp());
                    bar * READOUT_SILU_NORMALIZE2MOM * (sigmoid + value * sigmoid * (1.0 - sigmoid))
                })
                .collect())
        })
        .collect()
}

