#[allow(dead_code)]
fn polar_mace_readout_raw_output_rows_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    product_out: &[Vec<f64>],
) -> Result<MacePolarRows, MacePolarError> {
    let hidden_dim = LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim;
    let output_dim = 1_usize;
    let weight = access.f64("readouts.0.linear.weight", &[hidden_dim * output_dim])?;
    let bias = access
        .f64("readouts.0.linear.bias", &[0])
        .or_else(|_| access.f64("readouts.0.linear.bias", &[output_dim]))
        .unwrap_or(&[]);
    let output_mask = access
        .f64("readouts.0.linear.output_mask", &[output_dim])
        .unwrap_or(&[]);
    let path_weight = 1.0 / (hidden_dim as f64).sqrt();
    product_out
        .iter()
        .enumerate()
        .map(|(row_index, row)| {
            require_usize(
                &format!("readout.product_out[{row_index}].len"),
                row.len(),
                hidden_dim,
            )?;
            let mut output_row = Vec::with_capacity(output_dim);
            for output in 0..output_dim {
                let mut value = bias.get(output).copied().unwrap_or(0.0);
                for input in 0..hidden_dim {
                    value += path_weight * row[input] * weight[input * output_dim + output];
                }
                output_row.push(value * output_mask.get(output).copied().unwrap_or(1.0));
            }
            Ok(output_row)
        })
        .collect()
}

