#[allow(dead_code)]
fn polar_mace_scale_shift_from_tensors(
    access: &MacePolarTensorAccess<'_>,
    node_inter_es_unscaled: &[f64],
    node_heads: &[i64],
) -> Result<MacePolarScaleShiftOutput, MacePolarError> {
    require_usize(
        "scale_shift.node_heads.len",
        node_heads.len(),
        node_inter_es_unscaled.len(),
    )?;
    let scale = access.f64("scale_shift.scale", &[1])?;
    let shift = access.f64("scale_shift.shift", &[1])?;
    let mut node_inter_es = Vec::with_capacity(node_inter_es_unscaled.len());
    for (index, (value, head)) in node_inter_es_unscaled.iter().zip(node_heads).enumerate() {
        let head = usize::try_from(*head).map_err(|_| {
            invalid(
                "scale_shift.node_heads",
                format!("node_heads[{index}] must be non-negative"),
            )
        })?;
        let scale = *scale
            .get(head)
            .ok_or_else(|| invalid("scale_shift.scale", format!("missing head {head}")))?;
        let shift = *shift
            .get(head)
            .ok_or_else(|| invalid("scale_shift.shift", format!("missing head {head}")))?;
        node_inter_es.push(value * scale + shift);
    }
    let interaction_energy = node_inter_es.iter().sum();
    Ok(MacePolarScaleShiftOutput {
        node_inter_es_unscaled: node_inter_es_unscaled.to_vec(),
        node_inter_es,
        interaction_energy,
    })
}

