#[allow(dead_code)]
fn polar_mace_local_backbone_product_readout_tail_f32(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    layer: usize,
    node_feats_input: &[Vec<f32>],
    reshaped_interaction_out: &[f32],
    product_width: usize,
    product_symmetric_forward_plan: Option<&MacePolarProductSymmetricForwardLayerPlan>,
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneProductReadoutTailF32, MacePolarError> {
    let node_count = node_feats_input.len();
    require_usize(
        "product_readout_tail.node_heads.len",
        node_heads.len(),
        node_count,
    )?;
    let access = MacePolarTensorAccess::new(tensors);
    let access_f32 = MacePolarTensorAccessF32::new(tensors_f32);
    let product_symmetric_contractions_output =
        if product_width == LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim {
            polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer_f32(
                &access,
                layer,
                reshaped_interaction_out,
                node_count,
            )?
        } else {
            let reshaped_interaction_out_f64 = polar_mace_slice_to_f64(reshaped_interaction_out);
            let product_symmetric_contractions_output_f64 =
                if let Some(plan) = product_symmetric_forward_plan {
                    plan.forward_rows(&reshaped_interaction_out_f64, node_count)?
                } else {
                    polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer(
                        &access,
                        layer,
                        &reshaped_interaction_out_f64,
                        node_count,
                    )?
                };
            polar_mace_rows_to_f32(&product_symmetric_contractions_output_f64)
        };
    let product_linear_output_rows = polar_mace_product_linear_rows_from_tensors_for_layer_f32(
        &access_f32,
        layer,
        &product_symmetric_contractions_output,
    )?;
    let input_dim = node_feats_input.first().map_or(0, Vec::len);
    let skip_plan = polar_mace_runtime_skip_tp_plan(input_dim, product_width)?;
    let product_skip_connection = polar_mace_runtime_block_linear_rows_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.skip_tp"),
        node_feats_input,
        &skip_plan,
    )?;
    let product_skip_added = polar_mace_add_rows_f32(
        &product_linear_output_rows,
        &product_skip_connection,
        "product.skip_added_f32",
    )?;
    let product_out = product_skip_added.clone();
    let readout_raw_output = if access_f32
        .tensors
        .contains_key(&format!("readouts.{layer}.linear.weight"))
    {
        polar_mace_runtime_readout_linear_rows_from_tensors_f32(
            &access_f32,
            layer,
            &product_out,
            product_width,
        )?
    } else {
        polar_mace_runtime_readout_nonlinear_rows_from_tensors_f32(
            &access_f32,
            layer,
            &product_out,
            product_width,
        )?
    };
    let readout_selected_node_es =
        polar_mace_selected_node_es_from_raw_output_f32(&readout_raw_output, node_heads)?;
    Ok(MacePolarLocalBackboneProductReadoutTailF32 {
        product_symmetric_contractions_output,
        product_linear_output_rows,
        product_skip_connection,
        product_skip_added,
        product_out,
        readout_raw_output,
        readout_selected_node_es,
    })
}

#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_local_backbone_product_readout_tail_vjp_f32(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    layer: usize,
    node_feats_input: &[Vec<f32>],
    reshaped_interaction_out: &[f32],
    tail: &MacePolarLocalBackboneProductReadoutTailF32,
    product_out_cotangent: &[Vec<f32>],
    interaction_energy_cotangent: f32,
    product_width: usize,
    product_symmetric_vjp_plan: Option<&MacePolarProductSymmetricVjpLayerPlan>,
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneThirdCotangentsF32, MacePolarError> {
    require_usize(
        "product_readout_tail_vjp_f32.node_heads.len",
        node_heads.len(),
        tail.product_out.len(),
    )?;
    let access = MacePolarTensorAccess::new(tensors);
    let access_f32 = MacePolarTensorAccessF32::new(tensors_f32);
    let mut product_cotangent = polar_mace_zero_rows_like_f32(&tail.product_out);
    polar_mace_add_rows_in_place_f32(
        &mut product_cotangent,
        product_out_cotangent,
        "product_readout_tail_vjp_f32.product_out.direct",
    )?;
    if interaction_energy_cotangent != 0.0 {
        let selected_cotangent = polar_mace_scale_shift_interaction_energy_vjp_from_tensors_f32(
            &access_f32,
            &tail.readout_selected_node_es,
            node_heads,
            interaction_energy_cotangent,
        )?;
        let raw_readout_cotangent = polar_mace_selected_node_es_from_raw_output_vjp_f32(
            &selected_cotangent,
            &tail.readout_raw_output,
            node_heads,
        )?;
        let readout_product_cotangent = if access_f32
            .tensors
            .contains_key(&format!("readouts.{layer}.linear.weight"))
        {
            polar_mace_runtime_readout_linear_rows_vjp_from_tensors_f32(
                &access_f32,
                layer,
                &raw_readout_cotangent,
                &tail.product_out,
                product_width,
            )?
        } else {
            polar_mace_runtime_readout_nonlinear_rows_vjp_from_tensors_f32(
                &access_f32,
                layer,
                &raw_readout_cotangent,
                &tail.product_out,
                product_width,
            )?
        };
        polar_mace_add_rows_in_place_f32(
            &mut product_cotangent,
            &readout_product_cotangent,
            "product_readout_tail_vjp_f32.product_out.readout",
        )?;
    }

    let product_linear_cotangent = product_cotangent.clone();
    let product_skip_cotangent = product_cotangent;
    let symmetric_output_cotangent = polar_mace_product_linear_rows_vjp_from_tensors_for_layer_f32(
        &access_f32,
        layer,
        &product_linear_cotangent,
        &tail.product_symmetric_contractions_output,
        product_width,
    )?;
    let reshaped_interaction_out = if product_width == LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim {
        polar_mace_product_symmetric_contraction_rows_vjp_from_tensors_f32(
            &access,
            reshaped_interaction_out,
            &symmetric_output_cotangent,
            tail.product_symmetric_contractions_output.len(),
        )?
    } else {
        let reshaped_interaction_out_f64 = polar_mace_slice_to_f64(reshaped_interaction_out);
        let symmetric_output_cotangent_f64 = polar_mace_rows_to_f64(&symmetric_output_cotangent);
        let reshaped_interaction_out_f64 = if let Some(plan) = product_symmetric_vjp_plan {
            plan.vjp_rows(
                &reshaped_interaction_out_f64,
                &symmetric_output_cotangent_f64,
                tail.product_symmetric_contractions_output.len(),
            )?
        } else {
            polar_mace_product_symmetric_contraction_rows_dynamic_vjp_from_tensors(
                &access,
                layer,
                &reshaped_interaction_out_f64,
                &symmetric_output_cotangent_f64,
                tail.product_symmetric_contractions_output.len(),
                product_symmetric_vjp_plan,
            )?
        };
        polar_mace_slice_to_f32(&reshaped_interaction_out_f64)
    };
    let skip_plan = polar_mace_runtime_skip_tp_plan(
        node_feats_input.first().map_or(0, Vec::len),
        product_width,
    )?;
    let node_feats_initial = polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.skip_tp"),
        &product_skip_cotangent,
        node_feats_input,
        &skip_plan,
    )?;
    Ok(MacePolarLocalBackboneThirdCotangentsF32 {
        reshaped_interaction_out,
        node_feats_initial,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_layer_runtime_slice_f32(
    runtime: &MacePolarRuntimeState,
    layer: usize,
    species: &[String],
    positions: &[[f64; 3]],
    node_feats_input: &[Vec<f32>],
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneRuntimeLayerSliceF32, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    let conv_tp_plan = runtime
        .local_backbone
        .conv_tp_plans
        .get(layer)
        .ok_or_else(|| {
            invalid(
                "local_backbone_f32.conv_tp_plans",
                format!("missing conv_tp plan for layer {layer}"),
            )
        })?;
    let gate_plan = runtime
        .local_backbone
        .gate_plans
        .get(layer)
        .ok_or_else(|| {
            invalid(
                "local_backbone_f32.gate_plans",
                format!("missing gate plan for layer {layer}"),
            )
        })?;
    let second = polar_mace_local_backbone_second_runtime_slice_for_layer_f32(
        &runtime.all_tensors.tensors,
        &runtime.all_tensors.float_tensors_f32,
        layer,
        species,
        positions,
        node_feats_input,
        conv_tp_plan,
        gate_plan,
    )?;
    mace_polar_trace_stage("local_backbone_f32.layer.second", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let product_width = runtime
        .all_tensors
        .float_tensors_f32
        .get(&format!("products.{layer}.linear.output_mask"))
        .map(|tensor| tensor.values.len())
        .unwrap_or(LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim);
    let tail = polar_mace_local_backbone_product_readout_tail_f32(
        &runtime.all_tensors.tensors,
        &runtime.all_tensors.float_tensors_f32,
        layer,
        node_feats_input,
        &second.reshaped_interaction_out,
        product_width,
        runtime
            .local_backbone
            .product_symmetric_forward_plans
            .get(layer),
        node_heads,
    )?;
    mace_polar_trace_stage("local_backbone_f32.layer.tail", stage_start);
    mace_polar_trace_stage("local_backbone_f32.layer.total", total_start);
    Ok(MacePolarLocalBackboneRuntimeLayerSliceF32 {
        layer,
        second,
        tail,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_runtime_slice_from_state_f32(
    runtime: &MacePolarRuntimeState,
    species: &[String],
    positions: &[[f64; 3]],
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneRuntimeSliceF32, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let constants = runtime.constants.as_ref().ok_or_else(|| {
        invalid(
            "mace_polar.runtime",
            "local backbone f32 runtime requires retained constants",
        )
    })?;
    let layer_count = usize::try_from(constants.num_interactions).map_err(|_| {
        invalid(
            "mace_polar.runtime.num_interactions",
            format!("invalid num_interactions {}", constants.num_interactions),
        )
    })?;
    require_usize(
        "local_backbone_f32.conv_tp_plans.len",
        runtime.local_backbone.conv_tp_plans.len(),
        layer_count,
    )?;
    require_usize(
        "local_backbone_f32.gate_plans.len",
        runtime.local_backbone.gate_plans.len(),
        layer_count,
    )?;
    require_usize(
        "local_backbone_f32.node_heads.len",
        node_heads.len(),
        positions.len(),
    )?;
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let mut node_feats = polar_mace_node_feats_initial_from_atomic_numbers_f32(
        &runtime.all_tensors.float_tensors_f32,
        &atomic_numbers,
    )?;
    let mut layers = Vec::with_capacity(layer_count);
    let mut product_out_by_layer = Vec::with_capacity(layer_count);
    let mut readout_sum = vec![0.0_f32; positions.len()];
    for layer in 0..layer_count {
        let layer_start = trace_timings.then(Instant::now);
        let slice = polar_mace_local_backbone_layer_runtime_slice_f32(
            runtime,
            layer,
            species,
            positions,
            &node_feats,
            node_heads,
        )?;
        require_usize(
            "local_backbone_f32.readout_selected_node_es.len",
            slice.tail.readout_selected_node_es.len(),
            readout_sum.len(),
        )?;
        for (target, value) in readout_sum
            .iter_mut()
            .zip(&slice.tail.readout_selected_node_es)
        {
            *target += *value;
        }
        node_feats = slice.tail.product_out.clone();
        product_out_by_layer.push(slice.tail.product_out.clone());
        layers.push(slice);
        mace_polar_trace_stage(
            &format!("local_backbone_f32.layer{layer}_forward"),
            layer_start,
        );
    }
    let product_out = product_out_by_layer.last().cloned().ok_or_else(|| {
        invalid(
            "local_backbone_f32.layers",
            "expected at least one interaction layer",
        )
    })?;
    let access_f32 = MacePolarTensorAccessF32::new(&runtime.all_tensors.float_tensors_f32);
    let scale_shift =
        polar_mace_scale_shift_from_tensors_f32(&access_f32, &readout_sum, node_heads)?;
    mace_polar_trace_stage("local_backbone_f32.total", total_start);
    Ok(MacePolarLocalBackboneRuntimeSliceF32 {
        layers,
        product_out,
        product_out_by_layer,
        scale_shift_node_inter_es_unscaled: scale_shift.node_inter_es_unscaled,
        scale_shift_node_inter_es: scale_shift.node_inter_es,
        interaction_energy: scale_shift.interaction_energy,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_runtime_slice_vjp_f32(
    runtime: &MacePolarRuntimeState,
    slice: &MacePolarLocalBackboneRuntimeSliceF32,
    product_out_by_layer_cotangent: &[MacePolarRows],
    interaction_energy_cotangent: f64,
    node_heads: &[i64],
) -> Result<MacePolarPositionCotangents, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    require_usize(
        "local_backbone_vjp_f32.product_out_by_layer_cotangent.len",
        product_out_by_layer_cotangent.len(),
        slice.layers.len(),
    )?;
    let mut positions_cotangent = MacePolarPositionCotangents::zeros(slice.product_out.len());
    let mut next_node_feats_cotangent: Option<MacePolarRowsF32> = None;
    for (layer_index, layer_slice) in slice.layers.iter().enumerate().rev() {
        let layer_start = trace_timings.then(Instant::now);
        let layer = layer_slice.layer;
        let mut layer_product_cotangent =
            polar_mace_rows_to_f32(&product_out_by_layer_cotangent[layer_index]);
        if let Some(next_cotangent) = next_node_feats_cotangent.take() {
            polar_mace_add_rows_in_place_f32(
                &mut layer_product_cotangent,
                &next_cotangent,
                "local_backbone_vjp_f32.next_layer",
            )?;
        }
        let product_width = layer_slice.tail.product_out.first().map_or(0, Vec::len);
        let third_cotangents = polar_mace_local_backbone_product_readout_tail_vjp_f32(
            &runtime.all_tensors.tensors,
            &runtime.all_tensors.float_tensors_f32,
            layer,
            &layer_slice.second.node_feats_initial,
            &layer_slice.second.reshaped_interaction_out,
            &layer_slice.tail,
            &layer_product_cotangent,
            interaction_energy_cotangent as f32,
            product_width,
            runtime
                .local_backbone
                .product_symmetric_vjp_plans
                .get(layer),
            node_heads,
        )?;
        mace_polar_trace_stage("local_backbone_vjp_f32.third", layer_start);
        let second_start = trace_timings.then(Instant::now);
        let gate_plan = runtime
            .local_backbone
            .gate_plans
            .get(layer)
            .ok_or_else(|| {
                invalid(
                    "local_backbone_vjp_f32.gate_plans",
                    format!("missing gate plan for layer {layer}"),
                )
            })?;
        let second_cotangents =
            polar_mace_local_backbone_second_runtime_slice_vjp_from_tensors_f32(
                &runtime.all_tensors.float_tensors_f32,
                &layer_slice.second,
                &third_cotangents,
                layer,
                product_width,
                gate_plan,
            )?;
        mace_polar_trace_stage("local_backbone_vjp_f32.second", second_start);
        let first_start = trace_timings.then(Instant::now);
        let conv_tp_plan = runtime
            .local_backbone
            .conv_tp_plans
            .get(layer)
            .ok_or_else(|| {
                invalid(
                    "local_backbone_vjp_f32.conv_tp_plans",
                    format!("missing conv_tp plan for layer {layer}"),
                )
            })?;
        let first_cotangents = polar_mace_local_backbone_first_runtime_slice_vjp_from_tensors_f32(
            &runtime.all_tensors.tensors,
            &runtime.all_tensors.float_tensors_f32,
            &layer_slice.second,
            &second_cotangents,
            layer,
            conv_tp_plan,
        )?;
        positions_cotangent.add_in_place(
            &first_cotangents.positions,
            "local_backbone_vjp_f32.positions",
        )?;
        next_node_feats_cotangent = Some(first_cotangents.node_feats_initial);
        mace_polar_trace_stage("local_backbone_vjp_f32.first", first_start);
        mace_polar_trace_stage(
            &format!("local_backbone_vjp_f32.layer{layer}_total"),
            layer_start,
        );
    }
    mace_polar_trace_stage("local_backbone_vjp_f32.total", total_start);
    Ok(positions_cotangent)
}

#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_local_backbone_second_runtime_slice_for_layer_f32(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    layer: usize,
    species: &[String],
    positions: &[[f64; 3]],
    node_feats_input: &[Vec<f32>],
    conv_tp_plan: &e3nn_core::TensorProductPlan,
    gate_plan: &MacePolarParsedGatePlan,
) -> Result<MacePolarLocalBackboneRuntimeSecondSliceF32, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    if species.len() != positions.len() {
        return Err(invalid(
            "local_backbone_f32.structure",
            format!(
                "species length {} does not match positions length {}",
                species.len(),
                positions.len()
            ),
        ));
    }
    require_usize(
        "local_backbone_f32.node_feats_input.len",
        node_feats_input.len(),
        positions.len(),
    )?;
    let access = MacePolarTensorAccess::new(tensors);
    let access_f32 = MacePolarTensorAccessF32::new(tensors_f32);
    let r_max = access.f64("radial_embedding.bessel_fn.r_max", &[])?[0];
    let cutoff_p = access.i32("radial_embedding.cutoff_fn.p", &[])?[0];
    let bessel_weights = access.f64(
        "radial_embedding.bessel_fn.bessel_weights",
        &[LOCAL_BACKBONE_FORWARD_CONTRACT.num_bessel],
    )?;
    let bessel_prefactor = access.f64("radial_embedding.bessel_fn.prefactor", &[])?[0];
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;

    let mut geometry = MacePolarLocalBackboneFirstSlice::non_pbc_from_positions(positions, r_max)?;
    geometry.cutoffs = geometry
        .lengths
        .iter()
        .map(|length| polar_mace_polynomial_cutoff(*length, r_max, cutoff_p))
        .collect();
    geometry.edge_feats = polar_mace_radial_edge_feats_from_weights(
        &geometry.lengths,
        bessel_prefactor,
        bessel_weights,
    );
    mace_polar_trace_stage("local_backbone_second_f32.setup", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let node_attrs = polar_mace_node_attr_rows_from_atomic_numbers(&atomic_numbers)?;
    let node_attrs_f32 = polar_mace_rows_to_f32(&node_attrs);
    let node_feats_initial = node_feats_input.to_vec();
    let source_embedding = polar_mace_e3nn_linear_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.source_embedding"),
        &node_attrs_f32,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
    )?;
    let target_embedding = polar_mace_e3nn_linear_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.target_embedding"),
        &node_attrs_f32,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
    )?;
    let linear_up_plan =
        polar_mace_runtime_linear_up_plan(layer, node_feats_initial.first().map_or(0, Vec::len))?;
    let linear_up = polar_mace_runtime_block_linear_rows_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.linear_up"),
        &node_feats_initial,
        &linear_up_plan,
    )?;
    mace_polar_trace_stage(
        "local_backbone_second_f32.embeddings_linear_up",
        stage_start,
    );
    stage_start = trace_timings.then(Instant::now);
    let edge_feats_f32 = polar_mace_rows_to_f32(&geometry.edge_feats);
    let edge_attrs_f32 = polar_mace_rows_to_f32(&geometry.edge_attrs);
    let cutoffs_f32 = polar_mace_slice_to_f32(&geometry.cutoffs);
    let edge_aug = polar_mace_edge_aug_rows_f32(
        &edge_feats_f32,
        &geometry.edge_index,
        &source_embedding,
        &target_embedding,
    )?;
    mace_polar_trace_stage("local_backbone_second_f32.edge_aug", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let share_edge_aug_flat = positions.len() >= POLAR_MACE_F32_REALSPACE_DESCRIPTOR_MIN_ATOMS;
    let edge_aug_flat = share_edge_aug_flat
        .then(|| {
            polar_mace_flatten_rows_f32(
                &edge_aug,
                LOCAL_BACKBONE_FORWARD_CONTRACT.radial_mlp_input_dim,
                "local_backbone_second_f32.edge_aug",
            )
        })
        .transpose()?;
    mace_polar_trace_stage("local_backbone_second_f32.edge_aug_flat", stage_start);
    let conv_tp_output_mask = access.f64(
        &format!("interactions.{layer}.conv_tp.output_mask"),
        &[conv_tp_plan.output_dim()],
    )?;
    // The raw-cutoff path improves the two-layer M export on this host but
    // regresses the one-layer S and three-layer L exports.
    let has_multiple_local_backbone_layers =
        tensors_f32.contains_key("interactions.1.conv_tp_weights.net.0.weight");
    let has_two_local_backbone_layers = has_multiple_local_backbone_layers
        && !tensors_f32.contains_key("interactions.2.conv_tp_weights.net.0.weight");
    let conv_tp_scalar_l0123_supported =
        polar_mace_conv_tp_scalar_l0123_plan_supported(conv_tp_plan, conv_tp_output_mask);
    let use_raw_cutoff_conv_tp =
        has_two_local_backbone_layers && edge_aug_flat.is_some() && conv_tp_scalar_l0123_supported;
    let compute_conv_tp = || -> Result<MacePolarConvTpForwardF32, MacePolarError> {
        let conv_weights_start = trace_timings.then(Instant::now);
        let (conv_tp_weights_cutoff_applied_output, conv_tp_weights_trace) =
            if use_raw_cutoff_conv_tp {
                let edge_aug_flat = edge_aug_flat.as_deref().ok_or_else(|| {
                    invalid(
                        "local_backbone_second_f32.conv_tp_weights",
                        "raw-cutoff conv-TP path requires flattened edge augmentation",
                    )
                })?;
                let trace = polar_mace_conv_tp_weights_raw_flat_f32_trace_for_layer_from_flat(
                    tensors_f32,
                    layer,
                    edge_aug_flat,
                    edge_aug.len(),
                    conv_tp_plan.weight_numel,
                )?;
                (Vec::new(), trace)
            } else if let Some(edge_aug_flat) = edge_aug_flat.as_deref() {
                let (rows, trace) =
                    polar_mace_conv_tp_weights_cutoff_applied_rows_flat_f32_with_trace_for_layer_from_flat(
                    tensors_f32,
                    layer,
                    edge_aug_flat,
                    edge_aug.len(),
                    &cutoffs_f32,
                    conv_tp_plan.weight_numel,
                )?;
                (rows, trace)
            } else {
                let (rows, trace) =
                    polar_mace_conv_tp_weights_cutoff_applied_rows_flat_f32_with_trace_for_layer(
                        tensors_f32,
                        layer,
                        &edge_aug,
                        &cutoffs_f32,
                        conv_tp_plan.weight_numel,
                    )?;
                (rows, trace)
            };
        mace_polar_trace_stage(
            "local_backbone_second_f32.conv_tp_weights",
            conv_weights_start,
        );
        let conv_scatter_start = trace_timings.then(Instant::now);
        let conv_tp_scatter_message = if use_raw_cutoff_conv_tp {
            polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows_raw_cutoff_f32(
                &geometry.edge_index,
                &linear_up,
                &edge_attrs_f32,
                &conv_tp_weights_trace.raw,
                &cutoffs_f32,
                positions.len(),
            )?
        } else {
            polar_mace_conv_tp_message_and_scatter_rows_f32_for_layer(
                conv_tp_plan,
                conv_tp_output_mask,
                &geometry.edge_index,
                &linear_up,
                &edge_attrs_f32,
                &conv_tp_weights_cutoff_applied_output,
                positions.len(),
            )?
        };
        mace_polar_trace_stage(
            "local_backbone_second_f32.conv_tp_scatter",
            conv_scatter_start,
        );
        Ok((
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_scatter_message,
        ))
    };
    let compute_density = || -> Result<MacePolarDensityForwardF32, MacePolarError> {
        let density_start = trace_timings.then(Instant::now);
        let (density_fn_edge_density_cutoff_applied, density_fn_trace) = if let Some(
            edge_aug_flat,
        ) =
            edge_aug_flat.as_deref()
        {
            polar_mace_density_fn_edge_density_cutoff_applied_rows_flat_f32_with_trace_for_layer_from_flat(
                    tensors_f32,
                    layer,
                    edge_aug_flat,
                    edge_aug.len(),
                    &cutoffs_f32,
                )?
        } else {
            polar_mace_density_fn_edge_density_cutoff_applied_rows_flat_f32_with_trace_for_layer(
                tensors_f32,
                layer,
                &edge_aug,
                &cutoffs_f32,
            )?
        };
        let density_fn_node_density = polar_mace_scatter_scalar_to_targets_f32(
            &geometry.edge_index,
            &density_fn_edge_density_cutoff_applied,
            positions.len(),
            "density_fn_f32.node_density",
        )?;
        mace_polar_trace_stage("local_backbone_second_f32.density_fn", density_start);
        Ok((
            density_fn_edge_density_cutoff_applied,
            density_fn_trace,
            density_fn_node_density,
        ))
    };
    #[cfg(feature = "parallel")]
    let (
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_scatter_message,
        density_fn_edge_density_cutoff_applied,
        density_fn_trace,
        density_fn_node_density,
    ) = if positions.len() >= POLAR_MACE_F32_REALSPACE_DESCRIPTOR_MIN_ATOMS
        && has_multiple_local_backbone_layers
        && rayon::current_num_threads() > 1
    {
        let (conv_result, density_result) = rayon::join(compute_conv_tp, compute_density);
        let (conv_tp_weights_cutoff_applied_output, conv_tp_weights_trace, conv_tp_scatter_message) =
            conv_result?;
        let (density_fn_edge_density_cutoff_applied, density_fn_trace, density_fn_node_density) =
            density_result?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_scatter_message,
            density_fn_edge_density_cutoff_applied,
            density_fn_trace,
            density_fn_node_density,
        )
    } else {
        let (conv_tp_weights_cutoff_applied_output, conv_tp_weights_trace, conv_tp_scatter_message) =
            compute_conv_tp()?;
        let (density_fn_edge_density_cutoff_applied, density_fn_trace, density_fn_node_density) =
            compute_density()?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_scatter_message,
            density_fn_edge_density_cutoff_applied,
            density_fn_trace,
            density_fn_node_density,
        )
    };
    #[cfg(not(feature = "parallel"))]
    let (
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_scatter_message,
        density_fn_edge_density_cutoff_applied,
        density_fn_trace,
        density_fn_node_density,
    ) = {
        let (conv_tp_weights_cutoff_applied_output, conv_tp_weights_trace, conv_tp_scatter_message) =
            compute_conv_tp()?;
        let (density_fn_edge_density_cutoff_applied, density_fn_trace, density_fn_node_density) =
            compute_density()?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_scatter_message,
            density_fn_edge_density_cutoff_applied,
            density_fn_trace,
            density_fn_node_density,
        )
    };
    stage_start = trace_timings.then(Instant::now);
    let product_width = access_f32
        .tensors
        .get(&format!("products.{layer}.linear.output_mask"))
        .map(|tensor| tensor.values.len())
        .unwrap_or(LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim);
    let linear_1_plan =
        polar_mace_runtime_linear_1_plan(layer, conv_tp_plan.output_dim(), product_width)?;
    let linear_res_plan = polar_mace_runtime_linear_res_plan(
        layer,
        linear_up.first().map_or(0, Vec::len),
        product_width,
    )?;
    let linear_1 = polar_mace_runtime_block_linear_rows_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.linear_1"),
        &conv_tp_scatter_message,
        &linear_1_plan,
    )?;
    let linear_res = polar_mace_runtime_block_linear_rows_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.linear_res"),
        &linear_up,
        &linear_res_plan,
    )?;
    mace_polar_trace_stage("local_backbone_second_f32.linear_1_res", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let alpha = access_f32.f32(&format!("interactions.{layer}.alpha"), &[])?[0];
    let beta = access_f32.f32(&format!("interactions.{layer}.beta"), &[])?[0];
    let density_denominator =
        polar_mace_density_denominator_rows_f32(&density_fn_node_density, alpha, beta)?;
    let message_after_density_norm = polar_mace_density_normalize_rows_f32(
        &linear_1,
        &density_denominator,
        "message_after_density_norm_f32",
    )?;
    let message_after_residual_add = polar_mace_add_rows_f32(
        &message_after_density_norm,
        &linear_res,
        "message_after_residual_add_f32",
    )?;
    let allow_parallel_gate_rows = message_after_residual_add.len()
        >= POLAR_MACE_F32_GATE_ROW_PAR_MIN_ROWS
        && mace_polar_f32_gate_row_parallel_benefits(tensors_f32, message_after_residual_add.len());
    let equivariant_nonlin_output_rows = if allow_parallel_gate_rows {
        polar_mace_equivariant_nonlin_gate_rows_f32_parallel_from_parsed_plan(
            &message_after_residual_add,
            gate_plan,
        )?
    } else {
        polar_mace_equivariant_nonlin_gate_rows_f32_from_parsed_plan(
            &message_after_residual_add,
            gate_plan,
        )?
    };
    mace_polar_trace_stage("local_backbone_second_f32.density_gate", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let linear_2_plan = polar_mace_runtime_linear_2_plan();
    let linear_2 = polar_mace_runtime_block_linear_rows_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.linear_2"),
        &equivariant_nonlin_output_rows,
        &linear_2_plan,
    )?;
    let reshaped_interaction_out =
        polar_mace_reshape_hidden_irreps_to_feature_major_f32(&linear_2)?;
    mace_polar_trace_stage("local_backbone_second_f32.linear_2", stage_start);
    mace_polar_trace_stage("local_backbone_second_f32.total", total_start);

    let retain_f32_geometry = positions.len() >= POLAR_MACE_F32_REALSPACE_DESCRIPTOR_MIN_ATOMS;
    Ok(MacePolarLocalBackboneRuntimeSecondSliceF32 {
        geometry,
        edge_feats_f32: retain_f32_geometry.then_some(edge_feats_f32),
        edge_attrs_f32: retain_f32_geometry.then_some(edge_attrs_f32),
        cutoffs_f32: retain_f32_geometry.then_some(cutoffs_f32),
        node_feats_initial,
        source_embedding,
        target_embedding,
        linear_up,
        edge_aug,
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_scatter_message,
        density_fn_edge_density_cutoff_applied,
        density_fn_trace,
        density_fn_node_density,
        linear_res,
        linear_1,
        density_denominator,
        message_after_density_norm,
        message_after_residual_add,
        equivariant_nonlin_output_rows,
        linear_2,
        reshaped_interaction_out,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_second_runtime_slice_f32(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    species: &[String],
    positions: &[[f64; 3]],
    conv_tp_plan: &e3nn_core::TensorProductPlan,
    gate_plan: &MacePolarParsedGatePlan,
) -> Result<MacePolarLocalBackboneRuntimeSecondSliceF32, MacePolarError> {
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let node_feats_initial =
        polar_mace_node_feats_initial_from_atomic_numbers_f32(tensors_f32, &atomic_numbers)?;
    polar_mace_local_backbone_second_runtime_slice_for_layer_f32(
        tensors,
        tensors_f32,
        0,
        species,
        positions,
        &node_feats_initial,
        conv_tp_plan,
        gate_plan,
    )
}

#[allow(dead_code)]
fn polar_mace_local_backbone_second_runtime_slice_vjp_from_tensors_f32(
    tensors_f32: &BTreeMap<String, MacePolarRuntimeFloatTensorF32>,
    slice: &MacePolarLocalBackboneRuntimeSecondSliceF32,
    cotangent: &MacePolarLocalBackboneThirdCotangentsF32,
    layer: usize,
    product_width: usize,
    gate_plan: &MacePolarParsedGatePlan,
) -> Result<MacePolarLocalBackboneSecondCotangentsF32, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    let access_f32 = MacePolarTensorAccessF32::new(tensors_f32);
    let mut node_feats_initial = cotangent.node_feats_initial.clone();
    let linear_2_cotangent = polar_mace_reshape_hidden_irreps_to_feature_major_vjp_f32(
        &cotangent.reshaped_interaction_out,
        &slice.linear_2,
    )?;
    let linear_2_plan = polar_mace_runtime_linear_2_plan();
    let equivariant_nonlin_cotangent = polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
        &access_f32,
        &format!("interactions.{layer}.linear_2"),
        &linear_2_cotangent,
        &slice.equivariant_nonlin_output_rows,
        &linear_2_plan,
    )?;
    let allow_parallel_gate_rows = slice.message_after_residual_add.len()
        >= POLAR_MACE_F32_GATE_ROW_PAR_MIN_ROWS
        && mace_polar_f32_gate_row_parallel_benefits(
            tensors_f32,
            slice.message_after_residual_add.len(),
        );
    let message_after_residual_add_cotangent = if allow_parallel_gate_rows {
        polar_mace_equivariant_nonlin_gate_rows_vjp_f32_parallel_from_parsed_plan(
            &equivariant_nonlin_cotangent,
            &slice.message_after_residual_add,
            gate_plan,
        )?
    } else {
        polar_mace_equivariant_nonlin_gate_rows_vjp_f32_from_parsed_plan(
            &equivariant_nonlin_cotangent,
            &slice.message_after_residual_add,
            gate_plan,
        )?
    };
    mace_polar_trace_stage("local_backbone_second_vjp_f32.linear2_gate", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let (message_after_density_norm_cotangent, linear_res_cotangent) = polar_mace_rows_add_vjp_f32(
        &message_after_residual_add_cotangent,
        &slice.message_after_density_norm,
        &slice.linear_res,
        "local_backbone_second_vjp_f32.residual_add",
    )?;
    let linear_res_plan = polar_mace_runtime_linear_res_plan(
        layer,
        slice.linear_up.first().map_or(0, Vec::len),
        product_width,
    )?;
    let linear_1_plan = polar_mace_runtime_linear_1_plan(
        layer,
        slice.conv_tp_scatter_message.first().map_or(0, Vec::len),
        product_width,
    )?;
    #[cfg(feature = "parallel")]
    let use_parallel_linear_vjp = {
        let has_second_layer = tensors_f32.contains_key("interactions.1.linear_res.weight");
        let has_third_layer = tensors_f32.contains_key("interactions.2.linear_res.weight");
        let node_count = slice.node_feats_initial.len();
        let model_size_benefits = has_third_layer || (has_second_layer && node_count >= 256);
        model_size_benefits && mace_polar_parallel_small_batch_linears_enabled(node_count)
    };
    #[cfg(feature = "parallel")]
    let (linear_up, conv_tp_scatter_message, density_denominator_cotangent) =
        if use_parallel_linear_vjp {
            let (linear_up_result, linear_1_result) = rayon::join(
                || {
                    polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
                        &access_f32,
                        &format!("interactions.{layer}.linear_res"),
                        &linear_res_cotangent,
                        &slice.linear_up,
                        &linear_res_plan,
                    )
                },
                || -> Result<(MacePolarRowsF32, MacePolarRowsF32), MacePolarError> {
                    let (linear_1_output_cotangent, density_denominator_cotangent) =
                        polar_mace_density_normalize_rows_vjp_f32(
                            &message_after_density_norm_cotangent,
                            &slice.linear_1,
                            &slice.density_denominator,
                            "local_backbone_second_vjp_f32.density_norm",
                        )?;
                    let conv_tp_scatter_message =
                        polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
                            &access_f32,
                            &format!("interactions.{layer}.linear_1"),
                            &linear_1_output_cotangent,
                            &slice.conv_tp_scatter_message,
                            &linear_1_plan,
                        )?;
                    Ok((conv_tp_scatter_message, density_denominator_cotangent))
                },
            );
            let (conv_tp_scatter_message, density_denominator_cotangent) = linear_1_result?;
            (
                linear_up_result?,
                conv_tp_scatter_message,
                density_denominator_cotangent,
            )
        } else {
            let linear_up = polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
                &access_f32,
                &format!("interactions.{layer}.linear_res"),
                &linear_res_cotangent,
                &slice.linear_up,
                &linear_res_plan,
            )?;
            let (linear_1_output_cotangent, density_denominator_cotangent) =
                polar_mace_density_normalize_rows_vjp_f32(
                    &message_after_density_norm_cotangent,
                    &slice.linear_1,
                    &slice.density_denominator,
                    "local_backbone_second_vjp_f32.density_norm",
                )?;
            let conv_tp_scatter_message =
                polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
                    &access_f32,
                    &format!("interactions.{layer}.linear_1"),
                    &linear_1_output_cotangent,
                    &slice.conv_tp_scatter_message,
                    &linear_1_plan,
                )?;
            (
                linear_up,
                conv_tp_scatter_message,
                density_denominator_cotangent,
            )
        };
    #[cfg(not(feature = "parallel"))]
    let (linear_up, conv_tp_scatter_message, density_denominator_cotangent) = {
        let linear_up = polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
            &access_f32,
            &format!("interactions.{layer}.linear_res"),
            &linear_res_cotangent,
            &slice.linear_up,
            &linear_res_plan,
        )?;
        let (linear_1_output_cotangent, density_denominator_cotangent) =
            polar_mace_density_normalize_rows_vjp_f32(
                &message_after_density_norm_cotangent,
                &slice.linear_1,
                &slice.density_denominator,
                "local_backbone_second_vjp_f32.density_norm",
            )?;
        let conv_tp_scatter_message = polar_mace_runtime_block_linear_rows_vjp_from_tensors_f32(
            &access_f32,
            &format!("interactions.{layer}.linear_1"),
            &linear_1_output_cotangent,
            &slice.conv_tp_scatter_message,
            &linear_1_plan,
        )?;
        (
            linear_up,
            conv_tp_scatter_message,
            density_denominator_cotangent,
        )
    };
    mace_polar_trace_stage("local_backbone_second_vjp_f32.linear_res_1", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let beta = access_f32.f32(&format!("interactions.{layer}.beta"), &[])?[0];
    let node_density_cotangent = polar_mace_density_denominator_rows_vjp_f32(
        &density_denominator_cotangent,
        &slice.density_fn_node_density,
        beta,
    )?;
    let density_edge_cotangent = polar_mace_scatter_scalar_to_targets_vjp_f32(
        &node_density_cotangent,
        &slice.geometry.edge_index,
        &slice.density_fn_edge_density_cutoff_applied,
        slice.node_feats_initial.len(),
        "local_backbone_second_vjp_f32.density_scatter",
    )?;
    let cutoffs_f32_storage;
    let cutoffs_f32 = if let Some(cutoffs_f32) = &slice.cutoffs_f32 {
        cutoffs_f32
    } else {
        cutoffs_f32_storage = polar_mace_slice_to_f32(&slice.geometry.cutoffs);
        &cutoffs_f32_storage
    };
    let use_edge_feat_density_vjp =
        slice.node_feats_initial.len() >= POLAR_MACE_F32_REALSPACE_DESCRIPTOR_MIN_ATOMS;
    let (density_edge_aug, density_edge_feats, density_cutoffs) = if use_edge_feat_density_vjp {
        let density_fn_cotangents =
            polar_mace_density_fn_edge_feats_vjp_flat_f32_from_trace_for_layer(
                tensors_f32,
                layer,
                &density_edge_cotangent,
                cutoffs_f32,
                &slice.density_fn_trace,
            )?;
        (
            Vec::new(),
            Some(density_fn_cotangents.edge_feats),
            density_fn_cotangents.cutoffs,
        )
    } else {
        let density_fn_cotangents =
            polar_mace_density_fn_edge_density_cutoff_applied_rows_vjp_flat_f32_from_trace_for_layer(
                tensors_f32,
                layer,
                &density_edge_cotangent,
                cutoffs_f32,
                &slice.density_fn_trace,
            )?;
        (
            density_fn_cotangents.edge_aug,
            None,
            density_fn_cotangents.cutoffs,
        )
    };
    mace_polar_trace_stage("local_backbone_second_vjp_f32.density", stage_start);
    if node_feats_initial.is_empty() {
        node_feats_initial = polar_mace_zero_rows_like_f32(&slice.node_feats_initial);
    }
    mace_polar_trace_stage("local_backbone_second_vjp_f32.total", total_start);
    Ok(MacePolarLocalBackboneSecondCotangentsF32 {
        node_feats_initial,
        linear_up,
        conv_tp_scatter_message,
        edge_aug: density_edge_aug,
        edge_feats: density_edge_feats,
        cutoffs: density_cutoffs,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_third_runtime_slice_vjp_from_tensors(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    slice: &MacePolarLocalBackboneRuntimeThirdSlice,
    product_out_cotangent: &[Vec<f64>],
    interaction_energy_cotangent: f64,
    product_symmetric_contraction_plan: Option<&MacePolarProductSymmetricContractionPlan>,
    product_symmetric_vjp_plan: Option<&MacePolarProductSymmetricVjpLayerPlan>,
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneThirdCotangents, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    let access = MacePolarTensorAccess::new(tensors);
    let product_width = slice.product_out.first().map_or(0, Vec::len);
    let mut product_cotangent = polar_mace_zero_rows_like(&slice.product_out);
    polar_mace_add_rows_in_place(
        &mut product_cotangent,
        product_out_cotangent,
        "local_backbone_third_vjp.product_out.direct",
    )?;
    if interaction_energy_cotangent != 0.0 {
        let selected_cotangent = polar_mace_scale_shift_interaction_energy_vjp_from_tensors(
            &access,
            &slice.scale_shift_node_inter_es_unscaled,
            node_heads,
            interaction_energy_cotangent,
        )?;
        let raw_readout_cotangent = polar_mace_selected_node_es_from_raw_output_vjp(
            &selected_cotangent,
            &slice.readout_raw_output,
            node_heads,
        )?;
        let readout_product_cotangent = if access
            .tensors
            .contains_key(&format!("readouts.{}.linear.weight", slice.layer))
        {
            polar_mace_runtime_readout_linear_rows_vjp_from_tensors(
                &access,
                slice.layer,
                &raw_readout_cotangent,
                &slice.product_out,
                product_width,
            )?
        } else {
            polar_mace_runtime_readout_nonlinear_rows_vjp_from_tensors(
                &access,
                slice.layer,
                &raw_readout_cotangent,
                &slice.product_out,
                product_width,
            )?
        };
        polar_mace_add_rows_in_place(
            &mut product_cotangent,
            &readout_product_cotangent,
            "local_backbone_third_vjp.product_out.readout",
        )?;
    }
    mace_polar_trace_stage("local_backbone_third_vjp.readout", stage_start);
    stage_start = trace_timings.then(Instant::now);

    let product_linear_cotangent = product_cotangent.clone();
    let product_skip_cotangent = product_cotangent;
    let symmetric_output_cotangent = polar_mace_product_linear_rows_vjp_from_tensors_for_layer(
        &access,
        slice.layer,
        &product_linear_cotangent,
        &slice.product_symmetric_contractions_output,
        product_width,
    )?;
    mace_polar_trace_stage("local_backbone_third_vjp.product_linear", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let reshaped_interaction_out = if product_width == LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim {
        if let Some(plan) = product_symmetric_contraction_plan {
            plan.vjp_rows(
                &slice.second.reshaped_interaction_out,
                &symmetric_output_cotangent,
                slice.product_symmetric_contractions_output.len(),
            )?
        } else {
            polar_mace_product_symmetric_contraction_rows_vjp_from_tensors(
                &access,
                &slice.second.reshaped_interaction_out,
                &symmetric_output_cotangent,
                slice.product_symmetric_contractions_output.len(),
            )?
        }
    } else if let Some(plan) = product_symmetric_vjp_plan {
        plan.vjp_rows(
            &slice.second.reshaped_interaction_out,
            &symmetric_output_cotangent,
            slice.product_symmetric_contractions_output.len(),
        )?
    } else {
        polar_mace_product_symmetric_contraction_rows_dynamic_vjp_from_tensors(
            &access,
            slice.layer,
            &slice.second.reshaped_interaction_out,
            &symmetric_output_cotangent,
            slice.product_symmetric_contractions_output.len(),
            product_symmetric_vjp_plan,
        )?
    };
    mace_polar_trace_stage("local_backbone_third_vjp.symmetric", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let node_feats_initial = polar_mace_interaction_skip_tp_rows_vjp_from_tensors_for_layer(
        &access,
        slice.layer,
        &product_skip_cotangent,
        &slice.second.first.node_feats_initial,
        product_width,
    )?;
    mace_polar_trace_stage("local_backbone_third_vjp.skip_tp", stage_start);
    mace_polar_trace_stage("local_backbone_third_vjp.total", total_start);

    Ok(MacePolarLocalBackboneThirdCotangents {
        reshaped_interaction_out,
        node_feats_initial,
    })
}

#[allow(dead_code)]
#[allow(clippy::too_many_arguments)]
fn polar_mace_local_backbone_layer_runtime_slice(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    layer: usize,
    species: &[String],
    positions: &[[f64; 3]],
    node_feats_input: &[Vec<f64>],
    conv_tp_plan: &e3nn_core::TensorProductPlan,
    gate_plan: &MacePolarParsedGatePlan,
    product_symmetric_forward_plan: Option<&MacePolarProductSymmetricForwardLayerPlan>,
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneRuntimeThirdSlice, MacePolarError> {
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let mut stage_start = trace_timings.then(Instant::now);
    let access = MacePolarTensorAccess::new(tensors);
    let r_max = access.f64("radial_embedding.bessel_fn.r_max", &[])?[0];
    let cutoff_p = access.i32("radial_embedding.cutoff_fn.p", &[])?[0];
    let bessel_weights = access.f64(
        "radial_embedding.bessel_fn.bessel_weights",
        &[LOCAL_BACKBONE_FORWARD_CONTRACT.num_bessel],
    )?;
    let bessel_prefactor = access.f64("radial_embedding.bessel_fn.prefactor", &[])?[0];
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let node_attrs = polar_mace_node_attr_rows_from_atomic_numbers(&atomic_numbers)?;

    let mut geometry = MacePolarLocalBackboneFirstSlice::non_pbc_from_positions(positions, r_max)?;
    geometry.cutoffs = geometry
        .lengths
        .iter()
        .map(|length| polar_mace_polynomial_cutoff(*length, r_max, cutoff_p))
        .collect();
    geometry.edge_feats = polar_mace_radial_edge_feats_from_weights(
        &geometry.lengths,
        bessel_prefactor,
        bessel_weights,
    );

    let source_embedding = polar_mace_e3nn_linear_from_tensors(
        &access,
        &format!("interactions.{layer}.source_embedding"),
        &node_attrs,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
    )?;
    let target_embedding = polar_mace_e3nn_linear_from_tensors(
        &access,
        &format!("interactions.{layer}.target_embedding"),
        &node_attrs,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.node_attr_dim,
    )?;
    let input_dim = node_feats_input.first().map_or(0, Vec::len);
    let linear_up_plan = polar_mace_runtime_linear_up_plan(layer, input_dim)?;
    let linear_up = polar_mace_runtime_block_linear_rows_from_tensors(
        &access,
        &format!("interactions.{layer}.linear_up"),
        node_feats_input,
        &linear_up_plan,
    )?;
    let edge_aug = polar_mace_edge_aug_rows(
        &geometry.edge_feats,
        &geometry.edge_index,
        &source_embedding,
        &target_embedding,
    )?;
    mace_polar_trace_stage("local_backbone_layer.forward_setup", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let has_multiple_local_backbone_layers =
        tensors.contains_key("interactions.1.conv_tp_weights.net.0.weight");
    let use_raw_cutoff_conv_tp = if positions.len() >= 128
        && (has_multiple_local_backbone_layers || positions.len() >= 256)
    {
        let conv_tp_output_mask = access.f64(
            &format!("interactions.{layer}.conv_tp.output_mask"),
            &[conv_tp_plan.output_dim()],
        )?;
        polar_mace_conv_tp_scalar_l0123_plan_supported(conv_tp_plan, conv_tp_output_mask)
    } else {
        false
    };
    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            target_arch = "x86_64"
        ),
        all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
    )))]
    let _ = use_raw_cutoff_conv_tp;
    let compute_conv_tp = || -> Result<_, MacePolarError> {
        #[cfg(any(
            all(feature = "accelerate-blas", target_os = "macos"),
            all(
                any(feature = "intel-mkl", feature = "openblas"),
                target_os = "linux",
                target_arch = "x86_64"
            ),
            all(feature = "openblas", target_os = "linux", target_arch = "aarch64")
        ))]
        if use_raw_cutoff_conv_tp {
            let trace = polar_mace_conv_tp_weights_raw_flat_trace_for_layer(
                tensors,
                layer,
                &edge_aug,
                conv_tp_plan.weight_numel,
            )?;
            let conv_tp_scatter_message =
                polar_mace_conv_tp_scalar_l0123_message_and_scatter_rows_raw_cutoff(
                    &geometry.edge_index,
                    &linear_up,
                    &geometry.edge_attrs,
                    &trace.raw,
                    &geometry.cutoffs,
                    positions.len(),
                )?;
            return Ok((Vec::new(), Some(trace), Vec::new(), conv_tp_scatter_message));
        }

        let (conv_tp_weights_cutoff_applied_output, conv_tp_weights_trace) =
            polar_mace_conv_tp_weights_cutoff_applied_rows_with_trace_for_layer(
                tensors,
                layer,
                &edge_aug,
                &geometry.cutoffs,
                conv_tp_plan.weight_numel,
            )?;
        let (conv_tp_edge_messages, conv_tp_scatter_message) =
            polar_mace_conv_tp_message_and_scatter_rows_for_layer(
                tensors,
                layer,
                conv_tp_plan,
                &geometry.edge_index,
                &linear_up,
                &geometry.edge_attrs,
                &conv_tp_weights_cutoff_applied_output,
                positions.len(),
                false,
            )?;
        Ok((
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
        ))
    };
    #[cfg(feature = "parallel")]
    let (
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_edge_messages,
        conv_tp_scatter_message,
        density_fn_precomputed,
    ) = if mace_polar_parallel_small_batch_linears_enabled(positions.len()) {
        let (conv_result, density_result) = rayon::join(compute_conv_tp, || {
            polar_mace_density_fn_edge_density_cutoff_applied_rows_with_trace_for_layer(
                tensors,
                layer,
                &edge_aug,
                &geometry.cutoffs,
            )
        });
        let (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
        ) = conv_result?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
            Some(density_result?),
        )
    } else {
        let (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
        ) = compute_conv_tp()?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
            None,
        )
    };
    #[cfg(not(feature = "parallel"))]
    let (
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_edge_messages,
        conv_tp_scatter_message,
        density_fn_precomputed,
    ) = {
        let (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
        ) = compute_conv_tp()?;
        (
            conv_tp_weights_cutoff_applied_output,
            conv_tp_weights_trace,
            conv_tp_edge_messages,
            conv_tp_scatter_message,
            None,
        )
    };
    mace_polar_trace_stage("local_backbone_layer.conv_tp", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let first = MacePolarLocalBackboneRuntimeFirstSlice {
        geometry,
        node_feats_initial: node_feats_input.to_vec(),
        source_embedding,
        target_embedding,
        linear_up,
        edge_aug,
        conv_tp_weights_cutoff_applied_output,
        conv_tp_weights_trace,
        conv_tp_edge_messages,
        conv_tp_scatter_message,
    };

    let mut density_stage_start = trace_timings.then(Instant::now);
    let (density_fn_edge_density_cutoff_applied, density_fn_trace) =
        if let Some(precomputed) = density_fn_precomputed {
            precomputed
        } else {
            polar_mace_density_fn_edge_density_cutoff_applied_rows_with_trace_for_layer(
                tensors,
                layer,
                &first.edge_aug,
                &first.geometry.cutoffs,
            )?
        };
    let density_fn_node_density = polar_mace_scatter_scalar_to_targets(
        &first.geometry.edge_index,
        &density_fn_edge_density_cutoff_applied,
        positions.len(),
        "density_fn.node_density",
    )?;
    mace_polar_trace_stage(
        "local_backbone_layer.density_gate.density_fn",
        density_stage_start,
    );
    density_stage_start = trace_timings.then(Instant::now);
    let product_width = access
        .f64_dynamic(&format!("products.{layer}.linear.output_mask"))?
        .1
        .len();
    let linear_1_plan =
        polar_mace_runtime_linear_1_plan(layer, conv_tp_plan.output_dim(), product_width)?;
    let linear_res_plan = polar_mace_runtime_linear_res_plan(
        layer,
        first.linear_up.first().map_or(0, Vec::len),
        product_width,
    )?;
    #[cfg(feature = "parallel")]
    let (linear_1, linear_res) = if mace_polar_parallel_small_batch_linears_enabled(positions.len())
    {
        let (linear_1_result, linear_res_result) = rayon::join(
            || {
                polar_mace_runtime_block_linear_rows_from_tensors(
                    &access,
                    &format!("interactions.{layer}.linear_1"),
                    &first.conv_tp_scatter_message,
                    &linear_1_plan,
                )
            },
            || {
                polar_mace_runtime_block_linear_rows_from_tensors(
                    &access,
                    &format!("interactions.{layer}.linear_res"),
                    &first.linear_up,
                    &linear_res_plan,
                )
            },
        );
        (linear_1_result?, linear_res_result?)
    } else {
        (
            polar_mace_runtime_block_linear_rows_from_tensors(
                &access,
                &format!("interactions.{layer}.linear_1"),
                &first.conv_tp_scatter_message,
                &linear_1_plan,
            )?,
            polar_mace_runtime_block_linear_rows_from_tensors(
                &access,
                &format!("interactions.{layer}.linear_res"),
                &first.linear_up,
                &linear_res_plan,
            )?,
        )
    };
    #[cfg(not(feature = "parallel"))]
    let (linear_1, linear_res) = (
        polar_mace_runtime_block_linear_rows_from_tensors(
            &access,
            &format!("interactions.{layer}.linear_1"),
            &first.conv_tp_scatter_message,
            &linear_1_plan,
        )?,
        polar_mace_runtime_block_linear_rows_from_tensors(
            &access,
            &format!("interactions.{layer}.linear_res"),
            &first.linear_up,
            &linear_res_plan,
        )?,
    );
    mace_polar_trace_stage(
        "local_backbone_layer.density_gate.linear_1_res",
        density_stage_start,
    );
    density_stage_start = trace_timings.then(Instant::now);
    let alpha = access.f64(&format!("interactions.{layer}.alpha"), &[])?[0];
    let beta = access.f64(&format!("interactions.{layer}.beta"), &[])?[0];
    let density_denominator =
        polar_mace_density_denominator_rows(&density_fn_node_density, alpha, beta)?;
    let message_after_density_norm = polar_mace_density_normalize_rows(
        &linear_1,
        &density_denominator,
        "message_after_density_norm",
    )?;
    let message_after_residual_add = polar_mace_add_rows(
        &message_after_density_norm,
        &linear_res,
        "message_after_residual_add",
    )?;
    let equivariant_nonlin_output_rows = polar_mace_equivariant_nonlin_gate_rows_from_parsed_plan(
        &message_after_residual_add,
        gate_plan,
    )?;
    mace_polar_trace_stage(
        "local_backbone_layer.density_gate.gate",
        density_stage_start,
    );
    density_stage_start = trace_timings.then(Instant::now);
    let linear_2_plan = polar_mace_runtime_linear_2_plan();
    let linear_2 = polar_mace_runtime_block_linear_rows_from_tensors(
        &access,
        &format!("interactions.{layer}.linear_2"),
        &equivariant_nonlin_output_rows,
        &linear_2_plan,
    )?;
    let reshaped_interaction_out = polar_mace_reshape_hidden_irreps_to_feature_major(&linear_2)?;
    mace_polar_trace_stage(
        "local_backbone_layer.density_gate.linear_2",
        density_stage_start,
    );
    mace_polar_trace_stage("local_backbone_layer.density_gate", stage_start);
    stage_start = trace_timings.then(Instant::now);
    let second = MacePolarLocalBackboneRuntimeSecondSlice {
        first,
        density_fn_edge_density_cutoff_applied,
        density_fn_trace,
        density_fn_node_density,
        linear_res,
        linear_1,
        density_denominator,
        message_after_density_norm,
        message_after_residual_add,
        equivariant_nonlin_output_rows,
        linear_2,
        reshaped_interaction_out,
    };

    let mut product_stage_start = trace_timings.then(Instant::now);
    let skip_plan = polar_mace_runtime_skip_tp_plan(input_dim, product_width)?;
    #[cfg(feature = "parallel")]
    let (
        product_symmetric_contractions_output,
        product_linear_output_rows,
        product_skip_connection,
    ) = if mace_polar_parallel_small_batch_linears_enabled(positions.len()) {
        let (product_result, skip_result) = rayon::join(
            || -> Result<_, MacePolarError> {
                let product_symmetric_contractions_output =
                    if let Some(plan) = product_symmetric_forward_plan {
                        plan.forward_rows(&second.reshaped_interaction_out, positions.len())?
                    } else {
                        polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer(
                            &access,
                            layer,
                            &second.reshaped_interaction_out,
                            positions.len(),
                        )?
                    };
                let product_linear_output_rows =
                    polar_mace_product_linear_rows_from_tensors_for_layer(
                        &access,
                        layer,
                        &product_symmetric_contractions_output,
                    )?;
                Ok((
                    product_symmetric_contractions_output,
                    product_linear_output_rows,
                ))
            },
            || {
                polar_mace_runtime_block_linear_rows_from_tensors(
                    &access,
                    &format!("interactions.{layer}.skip_tp"),
                    node_feats_input,
                    &skip_plan,
                )
            },
        );
        let (product_symmetric_contractions_output, product_linear_output_rows) = product_result?;
        (
            product_symmetric_contractions_output,
            product_linear_output_rows,
            skip_result?,
        )
    } else {
        let product_symmetric_contractions_output =
            if let Some(plan) = product_symmetric_forward_plan {
                plan.forward_rows(&second.reshaped_interaction_out, positions.len())?
            } else {
                polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer(
                    &access,
                    layer,
                    &second.reshaped_interaction_out,
                    positions.len(),
                )?
            };
        mace_polar_trace_stage(
            "local_backbone_layer.product_symmetric",
            product_stage_start,
        );
        product_stage_start = trace_timings.then(Instant::now);
        let product_linear_output_rows = polar_mace_product_linear_rows_from_tensors_for_layer(
            &access,
            layer,
            &product_symmetric_contractions_output,
        )?;
        mace_polar_trace_stage("local_backbone_layer.product_linear", product_stage_start);
        product_stage_start = trace_timings.then(Instant::now);
        let product_skip_connection = polar_mace_runtime_block_linear_rows_from_tensors(
            &access,
            &format!("interactions.{layer}.skip_tp"),
            node_feats_input,
            &skip_plan,
        )?;
        (
            product_symmetric_contractions_output,
            product_linear_output_rows,
            product_skip_connection,
        )
    };
    #[cfg(not(feature = "parallel"))]
    let (
        product_symmetric_contractions_output,
        product_linear_output_rows,
        product_skip_connection,
    ) = {
        let product_symmetric_contractions_output =
            if let Some(plan) = product_symmetric_forward_plan {
                plan.forward_rows(&second.reshaped_interaction_out, positions.len())?
            } else {
                polar_mace_product_symmetric_contraction_rows_from_tensors_for_layer(
                    &access,
                    layer,
                    &second.reshaped_interaction_out,
                    positions.len(),
                )?
            };
        mace_polar_trace_stage(
            "local_backbone_layer.product_symmetric",
            product_stage_start,
        );
        product_stage_start = trace_timings.then(Instant::now);
        let product_linear_output_rows = polar_mace_product_linear_rows_from_tensors_for_layer(
            &access,
            layer,
            &product_symmetric_contractions_output,
        )?;
        mace_polar_trace_stage("local_backbone_layer.product_linear", product_stage_start);
        product_stage_start = trace_timings.then(Instant::now);
        let product_skip_connection = polar_mace_runtime_block_linear_rows_from_tensors(
            &access,
            &format!("interactions.{layer}.skip_tp"),
            node_feats_input,
            &skip_plan,
        )?;
        (
            product_symmetric_contractions_output,
            product_linear_output_rows,
            product_skip_connection,
        )
    };
    #[cfg(feature = "parallel")]
    if mace_polar_parallel_small_batch_linears_enabled(positions.len()) {
        mace_polar_trace_stage("local_backbone_layer.product_parallel", product_stage_start);
        product_stage_start = trace_timings.then(Instant::now);
    }
    let product_skip_added =
        polar_mace_product_skip_added_rows(&product_linear_output_rows, &product_skip_connection)?;
    let product_out = product_skip_added.clone();
    mace_polar_trace_stage("local_backbone_layer.product_skip", product_stage_start);
    product_stage_start = trace_timings.then(Instant::now);
    let readout_raw_output = if access
        .tensors
        .contains_key(&format!("readouts.{layer}.linear.weight"))
    {
        polar_mace_runtime_readout_linear_rows_from_tensors(
            &access,
            layer,
            &product_out,
            product_width,
        )?
    } else {
        polar_mace_runtime_readout_nonlinear_rows_from_tensors(
            &access,
            layer,
            &product_out,
            product_width,
        )?
    };
    let readout_selected_node_es =
        polar_mace_selected_node_es_from_raw_output(&readout_raw_output, node_heads)?;
    mace_polar_trace_stage(
        "local_backbone_layer.product_readout_tail",
        product_stage_start,
    );
    mace_polar_trace_stage("local_backbone_layer.product_readout", stage_start);
    mace_polar_trace_stage("local_backbone_layer.total", total_start);

    Ok(MacePolarLocalBackboneRuntimeThirdSlice {
        layer,
        previous_layers: Vec::new(),
        second,
        product_symmetric_contractions_output,
        product_linear_output_rows,
        product_skip_added,
        product_out: product_out.clone(),
        product_out_by_layer: vec![product_out],
        readout_raw_output,
        readout_selected_node_es: readout_selected_node_es.clone(),
        scale_shift_node_inter_es_unscaled: readout_selected_node_es.clone(),
        scale_shift_node_inter_es: readout_selected_node_es,
        interaction_energy: 0.0,
    })
}

#[allow(dead_code)]
fn polar_mace_local_backbone_runtime_slice_from_state(
    runtime: &MacePolarRuntimeState,
    species: &[String],
    positions: &[[f64; 3]],
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneRuntimeThirdSlice, MacePolarError> {
    let constants = runtime.constants.as_ref().ok_or_else(|| {
        invalid(
            "mace_polar.runtime",
            "local backbone runtime requires retained constants",
        )
    })?;
    let layer_count = usize::try_from(constants.num_interactions).map_err(|_| {
        invalid(
            "mace_polar.runtime.num_interactions",
            format!("invalid num_interactions {}", constants.num_interactions),
        )
    })?;
    require_usize(
        "local_backbone.conv_tp_plans.len",
        runtime.local_backbone.conv_tp_plans.len(),
        layer_count,
    )?;
    require_usize(
        "local_backbone.gate_plans.len",
        runtime.local_backbone.gate_plans.len(),
        layer_count,
    )?;
    let atomic_numbers = species
        .iter()
        .map(|symbol| polar_mace_atomic_number_from_species(symbol))
        .collect::<Result<Vec<_>, _>>()?;
    let mut node_feats = polar_mace_node_feats_initial_from_atomic_numbers(
        &runtime.local_backbone.tensors,
        &atomic_numbers,
    )?;
    let mut layers = Vec::with_capacity(layer_count);
    let mut product_out_by_layer = Vec::with_capacity(layer_count);
    let mut readout_sum = vec![0.0_f64; positions.len()];
    let trace_timings = mace_polar_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    for layer in 0..layer_count {
        let layer_start = trace_timings.then(Instant::now);
        let slice = polar_mace_local_backbone_layer_runtime_slice(
            &runtime.local_backbone.tensors,
            layer,
            species,
            positions,
            &node_feats,
            &runtime.local_backbone.conv_tp_plans[layer],
            &runtime.local_backbone.gate_plans[layer],
            runtime
                .local_backbone
                .product_symmetric_forward_plans
                .get(layer),
            node_heads,
        )?;
        mace_polar_trace_stage(&format!("local_backbone.layer{layer}_forward"), layer_start);
        for (target, value) in readout_sum.iter_mut().zip(&slice.readout_selected_node_es) {
            *target += *value;
        }
        node_feats = slice.product_out.clone();
        product_out_by_layer.push(slice.product_out.clone());
        layers.push(slice);
    }
    let mut output = layers.pop().ok_or_else(|| {
        invalid(
            "local_backbone.layers",
            "expected at least one interaction layer",
        )
    })?;
    let access = MacePolarTensorAccess::new(&runtime.all_tensors.tensors);
    let scale_shift = polar_mace_scale_shift_from_tensors(&access, &readout_sum, node_heads)?;
    output.scale_shift_node_inter_es_unscaled = scale_shift.node_inter_es_unscaled;
    output.scale_shift_node_inter_es = scale_shift.node_inter_es;
    output.interaction_energy = scale_shift.interaction_energy;
    output.previous_layers = layers;
    output.product_out_by_layer = product_out_by_layer;
    mace_polar_trace_stage("local_backbone.total", total_start);
    Ok(output)
}

#[allow(dead_code)]
fn polar_mace_local_backbone_third_runtime_slice(
    tensors: &BTreeMap<String, MacePolarExternalTensor>,
    species: &[String],
    positions: &[[f64; 3]],
    conv_tp_plan: &e3nn_core::TensorProductPlan,
    gate_plan: &MacePolarParsedGatePlan,
    product_symmetric_contraction_plan: Option<&MacePolarProductSymmetricContractionPlan>,
    node_heads: &[i64],
) -> Result<MacePolarLocalBackboneRuntimeThirdSlice, MacePolarError> {
    let second = polar_mace_local_backbone_second_runtime_slice(
        tensors,
        species,
        positions,
        conv_tp_plan,
        gate_plan,
    )?;
    require_usize(
        "local_backbone.node_heads.len",
        node_heads.len(),
        positions.len(),
    )?;
    let access = MacePolarTensorAccess::new(tensors);
    let product_symmetric_contractions_output =
        if let Some(plan) = product_symmetric_contraction_plan {
            plan.forward_rows(&second.reshaped_interaction_out, positions.len())?
        } else {
            polar_mace_product_symmetric_contraction_rows_from_tensors(
                &access,
                &second.reshaped_interaction_out,
                positions.len(),
            )?
        };
    let product_linear_output_rows = polar_mace_product_linear_rows_from_tensors(
        &access,
        &product_symmetric_contractions_output,
    )?;
    let product_skip_connection = polar_mace_e3nn_linear_from_tensors(
        &access,
        "interactions.0.skip_tp",
        &second.first.node_feats_initial,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
        LOCAL_BACKBONE_FORWARD_CONTRACT.hidden_dim,
    )?;
    let product_skip_added =
        polar_mace_product_skip_added_rows(&product_linear_output_rows, &product_skip_connection)?;
    let product_out = product_skip_added.clone();
    let readout_raw_output =
        polar_mace_readout_raw_output_rows_from_tensors(&access, &product_out)?;
    let readout_selected_node_es =
        polar_mace_selected_node_es_from_raw_output(&readout_raw_output, node_heads)?;
    let scale_shift =
        polar_mace_scale_shift_from_tensors(&access, &readout_selected_node_es, node_heads)?;

    Ok(MacePolarLocalBackboneRuntimeThirdSlice {
        layer: 0,
        previous_layers: Vec::new(),
        second,
        product_symmetric_contractions_output,
        product_linear_output_rows,
        product_skip_added,
        product_out: product_out.clone(),
        product_out_by_layer: vec![product_out],
        readout_raw_output,
        readout_selected_node_es,
        scale_shift_node_inter_es_unscaled: scale_shift.node_inter_es_unscaled,
        scale_shift_node_inter_es: scale_shift.node_inter_es,
        interaction_energy: scale_shift.interaction_energy,
    })
}

fn external_tensor<'a>(
    external_tensors: &'a BTreeMap<String, MacePolarExternalTensor>,
    name: &str,
) -> Result<&'a MacePolarExternalTensor, MacePolarError> {
    external_tensors.get(name).ok_or_else(|| {
        invalid(
            "runtime_state",
            format!("missing validated external tensor `{name}`"),
        )
    })
}

fn f64_scalar(
    external_tensors: &BTreeMap<String, MacePolarExternalTensor>,
    name: &str,
) -> Result<f64, MacePolarError> {
    match &external_tensor(external_tensors, name)?.values {
        MacePolarExternalTensorValues::F64(values) if values.len() == 1 => Ok(values[0]),
        _ => Err(invalid(
            "runtime_state",
            format!("tensor `{name}` must be a scalar f64 tensor"),
        )),
    }
}

fn i64_scalar(
    external_tensors: &BTreeMap<String, MacePolarExternalTensor>,
    name: &str,
) -> Result<i64, MacePolarError> {
    match &external_tensor(external_tensors, name)?.values {
        MacePolarExternalTensorValues::I64(values) if values.len() == 1 => Ok(values[0]),
        _ => Err(invalid(
            "runtime_state",
            format!("tensor `{name}` must be a scalar i64 tensor"),
        )),
    }
}

fn f64_vector(
    external_tensors: &BTreeMap<String, MacePolarExternalTensor>,
    name: &str,
    expected_len: usize,
) -> Result<Vec<f64>, MacePolarError> {
    match &external_tensor(external_tensors, name)?.values {
        MacePolarExternalTensorValues::F64(values) if values.len() == expected_len => {
            Ok(values.clone())
        }
        _ => Err(invalid(
            "runtime_state",
            format!("tensor `{name}` must be an f64 vector of length {expected_len}"),
        )),
    }
}

fn i64_vector(
    external_tensors: &BTreeMap<String, MacePolarExternalTensor>,
    name: &str,
    expected_len: usize,
) -> Result<Vec<i64>, MacePolarError> {
    match &external_tensor(external_tensors, name)?.values {
        MacePolarExternalTensorValues::I64(values) if values.len() == expected_len => {
            Ok(values.clone())
        }
        _ => Err(invalid(
            "runtime_state",
            format!("tensor `{name}` must be an i64 vector of length {expected_len}"),
        )),
    }
}

impl MacePolarMetadata {
    fn validate(&self) -> Result<(), MacePolarError> {
        require_eq("schema_version", &self.schema_version, SCHEMA_VERSION)?;
        require_eq("architecture", &self.architecture, ARCHITECTURE)?;
        require_eq("runtime_status", &self.runtime_status, RUNTIME_STATUS)?;
        require_eq("selected_model", &self.selected_model, SELECTED_MODEL)?;

        require_eq("reference.package", &self.reference.package, "mace")?;
        require_eq("reference.version", &self.reference.version, "0.3.16")?;
        require_eq("reference.commit", &self.reference.commit, REFERENCE_COMMIT)?;
        require_eq(
            "reference.repository",
            &self.reference.repository,
            "https://github.com/ACEsuit/mace",
        )?;

        require_eq(
            "artifact.filename",
            &self.artifact.filename,
            "MACE-POLAR-1-S.model",
        )?;
        require_eq(
            "artifact.source_url",
            &self.artifact.source_url,
            ARTIFACT_URL,
        )?;
        require_eq("artifact.sha256", &self.artifact.sha256, ARTIFACT_SHA256)?;
        require_usize(
            "artifact.byte_size",
            self.artifact.byte_size,
            ARTIFACT_SIZE_BYTES,
        )?;
        require_bool(
            "artifact.tracked_in_git",
            self.artifact.tracked_in_git,
            false,
        )?;

        if !self
            .type_names
            .iter()
            .map(String::as_str)
            .eq(EXPECTED_TYPE_NAMES.iter().copied())
        {
            return Err(invalid("type_names", "expected atomic symbols H..Bi"));
        }
        if !self.atomic_numbers.iter().copied().eq(1_u8..=83) {
            return Err(invalid("atomic_numbers", "expected atomic numbers 1..83"));
        }
        require_f64("cutoff", self.cutoff, 6.0)?;

        if self.heads.len() != 1 {
            return Err(invalid("heads", "expected exactly one Default head"));
        }
        require_eq("heads[0].raw", &self.heads[0].raw, "Default")?;
        require_eq("heads[0].canonical", &self.heads[0].canonical, "Default")?;

        self.attributes.validate()?;
        self.inspection.validate()?;

        if !self
            .required_inputs
            .iter()
            .map(String::as_str)
            .eq(EXPECTED_REQUIRED_INPUTS.iter().copied())
        {
            return Err(invalid(
                "required_inputs",
                "expected pinned PolarMACE input contract",
            ));
        }

        require_eq(
            "reference_fixture.path",
            &self.reference_fixture.path,
            "../../polarmace_polar_1_s_reference_20plus_f32.json",
        )?;
        require_usize(
            "reference_fixture.structure_count",
            self.reference_fixture.structure_count,
            24,
        )?;
        require_bool("reference_fixture.pbc", self.reference_fixture.pbc, false)?;
        if self.reference_fixture.charge != 0 {
            return Err(invalid(
                "reference_fixture.charge",
                "expected neutral structures",
            ));
        }
        if self.reference_fixture.spin != 1 {
            return Err(invalid(
                "reference_fixture.spin",
                "expected singlet spin setting",
            ));
        }
        if self.reference_fixture.external_field != [0.0, 0.0, 0.0] {
            return Err(invalid(
                "reference_fixture.external_field",
                "expected zero external field",
            ));
        }

        Ok(())
    }
}

