fn validate_torch_state_dict_layout<'a>(
    field: &str,
    count: usize,
    numel: usize,
    dtype_counts: &BTreeMap<String, usize>,
    names: impl Iterator<Item = &'a str>,
    spec: &MacePolarModelSpec,
) -> Result<(), MacePolarError> {
    require_usize(
        &format!("{field}.count"),
        count,
        spec.state_dict_tensor_count,
    )?;
    require_usize(&format!("{field}.numel"), numel, spec.state_dict_numel)?;
    require_usize(&format!("{field}.dtype_counts.len"), dtype_counts.len(), 4)?;
    require_dtype_count(dtype_counts, "torch.bool", spec.bool_tensor_count)?;
    require_dtype_count(dtype_counts, "torch.float32", spec.f32_tensor_count)?;
    require_dtype_count(dtype_counts, "torch.int32", 1)?;
    require_dtype_count(dtype_counts, "torch.int64", 13)?;
    validate_state_layout_prefix_counts(field, names, spec)
}

fn validate_state_export_tensors(
    tensors: &[StateExportTensor],
    spec: &MacePolarModelSpec,
) -> Result<(), MacePolarError> {
    let mut total_numel = 0_usize;
    let mut total_bytes = 0_usize;
    for tensor in tensors {
        require_eq("tensor.layout", &tensor.layout, "row-major")?;
        if tensor.path.starts_with('/') || tensor.path.contains("..") {
            return Err(invalid(
                "tensor.path",
                format!(
                    "tensor path must be relative and non-escaping, got `{}`",
                    tensor.path
                ),
            ));
        }
        match tensor.dtype.as_str() {
            "bool" | "f64" | "i32" | "i64" => {}
            other => {
                return Err(invalid(
                    "tensor.dtype",
                    format!("unsupported exported dtype `{other}`"),
                ));
            }
        }
        match tensor.source_dtype.as_str() {
            "bool" | "f32" | "i32" | "i64" => {}
            other => {
                return Err(invalid(
                    "tensor.source_dtype",
                    format!("unsupported source dtype `{other}`"),
                ));
            }
        }
        let shape_numel = tensor
            .shape
            .iter()
            .try_fold(1_usize, |acc, dim| acc.checked_mul(*dim))
            .ok_or_else(|| invalid("tensor.shape", "shape product overflows usize"))?;
        require_usize("tensor.shape_product", shape_numel, tensor.numel)?;
        require_usize(
            "tensor.byte_size",
            tensor.byte_size,
            tensor.numel * dtype_size_bytes(&tensor.dtype)?,
        )?;
        if tensor.sha256.len() != 64
            || !tensor.sha256.chars().all(|value| value.is_ascii_hexdigit())
        {
            return Err(invalid("tensor.sha256", "expected 64 hex characters"));
        }
        total_numel += tensor.numel;
        total_bytes += tensor.byte_size;
    }
    require_usize("tensors.total_numel", total_numel, spec.state_dict_numel)?;
    require_usize(
        "tensors.total_bytes",
        total_bytes,
        spec.state_export_total_bytes_f64,
    )?;
    if spec.selected_model == SELECTED_MODEL_POLAR_1_S {
        validate_runtime_tensor_semantic_shapes(tensors)?;
    }
    validate_state_layout_prefix_counts(
        "tensors",
        tensors.iter().map(|tensor| tensor.name.as_str()),
        spec,
    )
}

fn validate_state_export_external_tensors(
    tensors: &[StateExportTensor],
    external_tensors: &BTreeMap<String, MacePolarExternalTensor>,
) -> Result<(), MacePolarError> {
    let exported_names = tensors
        .iter()
        .map(|tensor| tensor.name.as_str())
        .collect::<HashSet<_>>();
    for tensor in tensors {
        if !external_tensors.contains_key(&tensor.name) {
            return Err(invalid(
                "external_tensors",
                format!("missing external tensor `{}`", tensor.name),
            ));
        }
    }
    for name in external_tensors.keys() {
        if !exported_names.contains(name.as_str()) {
            return Err(invalid(
                "external_tensors",
                format!("unexpected external tensor `{name}`"),
            ));
        }
    }
    require_usize(
        "external_tensors.len",
        external_tensors.len(),
        tensors.len(),
    )?;
    for tensor in tensors {
        let external = external_tensors.get(&tensor.name).ok_or_else(|| {
            invalid(
                "external_tensors",
                format!("missing external tensor `{}`", tensor.name),
            )
        })?;
        if external.shape != tensor.shape {
            return Err(invalid(
                "external_tensors.shape",
                format!(
                    "tensor `{}` expected shape {:?}, got {:?}",
                    tensor.name, tensor.shape, external.shape
                ),
            ));
        }
        if external.values.dtype_name() != tensor.dtype {
            return Err(invalid(
                "external_tensors.dtype",
                format!(
                    "tensor `{}` expected dtype {}, got {}",
                    tensor.name,
                    tensor.dtype,
                    external.values.dtype_name()
                ),
            ));
        }
        require_usize(
            &format!("external_tensors.{}.values.len", tensor.name),
            external.values.len(),
            tensor.numel,
        )?;
        if !external.values.all_finite() {
            return Err(invalid(
                "external_tensors.values",
                format!("tensor `{}` contains non-finite values", tensor.name),
            ));
        }
    }
    Ok(())
}

fn validate_runtime_tensor_semantic_shapes(
    tensors: &[StateExportTensor],
) -> Result<(), MacePolarError> {
    for (name, expected_shape) in EXPECTED_RUNTIME_TENSOR_SHAPES {
        let tensor = tensors
            .iter()
            .find(|tensor| tensor.name == *name)
            .ok_or_else(|| invalid("runtime_tensor_shapes", format!("missing tensor `{name}`")))?;
        if tensor.shape.as_slice() != *expected_shape {
            return Err(invalid(
                "runtime_tensor_shapes",
                format!(
                    "tensor `{name}` expected shape {:?}, got {:?}",
                    expected_shape, tensor.shape
                ),
            ));
        }
    }
    Ok(())
}

