fn dtype_size_bytes(dtype: &str) -> Result<usize, MacePolarError> {
    match dtype {
        "bool" => Ok(1),
        "f64" | "i64" => Ok(8),
        "i32" => Ok(4),
        other => Err(invalid(
            "tensor.dtype",
            format!("unsupported exported dtype `{other}`"),
        )),
    }
}

fn validate_state_layout_prefix_counts<'a>(
    field: &str,
    names: impl Iterator<Item = &'a str>,
    spec: &MacePolarModelSpec,
) -> Result<(), MacePolarError> {
    let mut prefix_counts = BTreeMap::<&str, usize>::new();
    for name in names {
        let prefix = name
            .split('.')
            .next()
            .ok_or_else(|| invalid(field, "state_dict entry name must have a prefix"))?;
        *prefix_counts.entry(prefix).or_default() += 1;
    }

    for (prefix, expected_count) in spec.prefix_counts {
        require_prefix_count(field, &prefix_counts, prefix, *expected_count)?;
    }
    Ok(())
}

fn require_eq(field: &str, actual: &str, expected: &str) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(
            field,
            format!("expected `{expected}`, got `{actual}`"),
        ))
    }
}

fn require_bool(field: &str, actual: bool, expected: bool) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(
            field,
            format!("expected `{expected}`, got `{actual}`"),
        ))
    }
}

fn require_f64(field: &str, actual: f64, expected: f64) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(
            field,
            format!("expected `{expected}`, got `{actual}`"),
        ))
    }
}

fn require_usize(field: &str, actual: usize, expected: usize) -> Result<(), MacePolarError> {
    if actual == expected {
        Ok(())
    } else {
        Err(invalid(
            field,
            format!("expected `{expected}`, got `{actual}`"),
        ))
    }
}

fn require_dtype_count(
    counts: &BTreeMap<String, usize>,
    key: &str,
    expected: usize,
) -> Result<(), MacePolarError> {
    match counts.get(key).copied() {
        Some(actual) if actual == expected => Ok(()),
        Some(actual) => Err(invalid(
            "inspection.state_dict_dtype_counts",
            format!("expected {key}={expected}, got {actual}"),
        )),
        None => Err(invalid(
            "inspection.state_dict_dtype_counts",
            format!("missing dtype key `{key}`"),
        )),
    }
}

fn require_json_object(field: &str, value: &serde_json::Value) -> Result<(), MacePolarError> {
    if value.is_object() {
        Ok(())
    } else {
        Err(invalid(field, "expected JSON object metadata"))
    }
}

fn require_prefix_count(
    field: &str,
    counts: &BTreeMap<&str, usize>,
    key: &str,
    expected: usize,
) -> Result<(), MacePolarError> {
    match counts.get(key).copied() {
        Some(actual) if actual == expected => Ok(()),
        Some(actual) => Err(invalid(
            field,
            format!("expected prefix {key}={expected}, got {actual}"),
        )),
        None => Err(invalid(field, format!("missing prefix `{key}`"))),
    }
}

fn invalid(field: &str, message: impl Into<String>) -> MacePolarError {
    MacePolarError::InvalidMetadata(format!("{field}: {}", message.into()))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
pub enum MacePolarRuntimeSection {
    /// Small fixed runtime constants and buffers rather than only scalar tensors.
    PinnedScalars,
    LocalBackbone,
    LongRangeSources,
    LayerFeatureMixer,
    ExternalFieldContribution,
    ElectrostaticDescriptor,
    FieldDependentCharges,
    LocalElectronEnergy,
    CoulombEnergy,
}

impl MacePolarRuntimeSection {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::PinnedScalars => "pinned_scalars",
            Self::LocalBackbone => "local_backbone",
            Self::LongRangeSources => "long_range_sources",
            Self::LayerFeatureMixer => "layer_feature_mixer",
            Self::ExternalFieldContribution => "external_field_contribution",
            Self::ElectrostaticDescriptor => "electrostatic_descriptor",
            Self::FieldDependentCharges => "field_dependent_charges",
            Self::LocalElectronEnergy => "local_electron_energy",
            Self::CoulombEnergy => "coulomb_energy",
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct MacePolarRuntimeSectionSummary {
    pub section: MacePolarRuntimeSection,
    pub tensor_count: usize,
    pub numel: usize,
    pub byte_size: usize,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct MacePolarRuntimeInventory {
    pub tensor_count: usize,
    pub numel: usize,
    pub byte_size: usize,
    sections: Vec<MacePolarRuntimeSectionSummary>,
}

impl MacePolarRuntimeInventory {
    pub fn from_state_export_json_str(text: &str) -> Result<Self, MacePolarError> {
        let export: MacePolarStateDictExport = serde_json::from_str(text)?;
        export.validate()?;
        let spec = mace_polar_model_spec(&export.selected_model)?;
        Self::from_state_export_tensors(&export.tensors, spec)
    }

    pub fn sections(&self) -> &[MacePolarRuntimeSectionSummary] {
        &self.sections
    }

    pub fn section(
        &self,
        section: MacePolarRuntimeSection,
    ) -> Option<&MacePolarRuntimeSectionSummary> {
        self.sections
            .iter()
            .find(|summary| summary.section == section)
    }

    fn from_state_export_tensors(
        tensors: &[StateExportTensor],
        spec: &MacePolarModelSpec,
    ) -> Result<Self, MacePolarError> {
        let mut by_section = BTreeMap::<MacePolarRuntimeSection, (usize, usize, usize)>::new();
        let mut total_numel = 0_usize;
        let mut total_bytes = 0_usize;

        for tensor in tensors {
            let section = classify_runtime_tensor_name(&tensor.name)?;
            let entry = by_section.entry(section).or_default();
            entry.0 += 1;
            entry.1 += tensor.numel;
            entry.2 += tensor.byte_size;
            total_numel += tensor.numel;
            total_bytes += tensor.byte_size;
        }

        for (section, expected_count) in expected_runtime_section_counts(spec) {
            let actual_count = by_section
                .get(section)
                .map(|(count, _, _)| *count)
                .unwrap_or(0);
            require_usize(
                &format!("runtime_section.{}", section.as_str()),
                actual_count,
                *expected_count,
            )?;
        }
        require_usize(
            "runtime_sections.len",
            by_section.len(),
            expected_runtime_section_counts(spec).len(),
        )?;
        require_usize(
            "runtime_sections.total_tensors",
            tensors.len(),
            spec.state_dict_tensor_count,
        )?;
        require_usize(
            "runtime_sections.total_numel",
            total_numel,
            spec.state_dict_numel,
        )?;
        require_usize(
            "runtime_sections.total_bytes",
            total_bytes,
            spec.state_export_total_bytes_f64,
        )?;

        let sections = by_section
            .into_iter()
            .map(
                |(section, (tensor_count, numel, byte_size))| MacePolarRuntimeSectionSummary {
                    section,
                    tensor_count,
                    numel,
                    byte_size,
                },
            )
            .collect();

        Ok(Self {
            tensor_count: tensors.len(),
            numel: total_numel,
            byte_size: total_bytes,
            sections,
        })
    }
}

