fn expected_runtime_section_counts(
    spec: &MacePolarModelSpec,
) -> &'static [(MacePolarRuntimeSection, usize)] {
    match spec.selected_model {
        SELECTED_MODEL_POLAR_1_S => EXPECTED_RUNTIME_SECTION_COUNTS,
        SELECTED_MODEL_POLAR_1_M => POLAR_1_M_RUNTIME_SECTION_COUNTS,
        SELECTED_MODEL_POLAR_1_L => POLAR_1_L_RUNTIME_SECTION_COUNTS,
        _ => EXPECTED_RUNTIME_SECTION_COUNTS,
    }
}

fn classify_runtime_tensor_name(name: &str) -> Result<MacePolarRuntimeSection, MacePolarError> {
    let prefix = name
        .split('.')
        .next()
        .ok_or_else(|| invalid("runtime_section", "tensor name must have a prefix"))?;
    match prefix {
        "atomic_numbers"
        | "r_max"
        | "num_interactions"
        | "kspace_cutoff"
        | "field_feature_norms" => Ok(MacePolarRuntimeSection::PinnedScalars),
        "atomic_energies_fn" | "node_embedding" | "radial_embedding" | "interactions"
        | "products" | "readouts" | "scale_shift" => Ok(MacePolarRuntimeSection::LocalBackbone),
        "lr_source_maps" | "fukui_source_map" => Ok(MacePolarRuntimeSection::LongRangeSources),
        "layer_feature_mixer" => Ok(MacePolarRuntimeSection::LayerFeatureMixer),
        "external_field_contribution" => Ok(MacePolarRuntimeSection::ExternalFieldContribution),
        "electric_potential_descriptor" => Ok(MacePolarRuntimeSection::ElectrostaticDescriptor),
        "field_dependent_charges_maps" => Ok(MacePolarRuntimeSection::FieldDependentCharges),
        "local_electron_energy" => Ok(MacePolarRuntimeSection::LocalElectronEnergy),
        "coulomb_energy" => Ok(MacePolarRuntimeSection::CoulombEnergy),
        other => Err(invalid(
            "runtime_section",
            format!("unknown PolarMACE runtime tensor prefix `{other}`"),
        )),
    }
}
